(1721, 1, 'الباسكال (Pa = N/m²) هو وحدة الضغط في النظام الدولي، وتُستخدم مضاعفاته مثل kPa.', '["atm وحدة شائعة لكنها ليست وحدة النظام الدولي.","","mmHg وحدة مستمدة من البارومتر الزئبقي وليست وحدة النظام الدولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.965Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1722, 2, '1 atm = 760 mmHg = 760 torr = 101.3 kPa = 14.7 psi.', '["101.3 هي قيمة 1 atm بوحدة kPa لا torr.","14.7 هي قيمة 1 atm بوحدة psi لا torr.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:01.965Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1723, 0, '8.4 atm × (101.3 kPa ÷ 1 atm) = 851 kPa.', '["","قُسم على 101.3 بدل الضرب.","استُخدم معامل 760 (وحدة mmHg) بدل 101.3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.965Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1724, 1, '725 torr × (101.3 kPa ÷ 760 torr) = 96.6 kPa.', '["قُلب معامل التحويل جزئيًا (760 ÷ 725 × 101.3 ≈ 106).","","قُسم 725 على 101.3 مباشرة دون المرور بـ 760."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.965Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1725, 2, '0.750 atm × (760 mmHg ÷ 1 atm) = 570 mmHg.', '["قُسم 760 على 0.750 بدل الضرب.","استُخدم معامل 101.3 (وحدة kPa) بدل 760: 0.750 × 101.3 ≈ 76.0.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.966Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1726, 0, '2.50 atm × (14.7 psi ÷ 1 atm) = 36.8 psi.', '["","قُسم 14.7 على 2.50 بدل الضرب.","استُخدم معامل kPa (101.3) بدل psi."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:01.966Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1727, 2, 'بالتحويل إلى atm: 120 kPa ÷ 101.3 = 1.18 atm، و850 mmHg ÷ 760 = 1.12 atm؛ فالترتيب: 1.5 atm > 1.18 atm (120 kPa) > 1.12 atm (850 mmHg).', '["رُتّبت الأرقام كما هي دون توحيد الوحدات.","850 mmHg تعادل 1.12 atm فقط، وهي أقل من 120 kPa (1.18 atm).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.966Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1728, null, null, null, '(أ) الكيلوباسكال (kPa)، والضغط الجوي (atm)، والمليمتر زئبق (mmHg)، والتور (torr)، (والرطل لكل بوصة مربعة psi، والبار bar). (ب) 1 atm = 101.3 kPa = 760 mmHg = 760 torr = 14.7 psi (= 1.01 bar). (ج) الباسكال (Pa)، و1 Pa = 1 N/m².', '["أربع وحدات صحيحة برموزها","العلاقة بدلالة 1 atm","الباسكال وحدة النظام الدولي","1 Pa = 1 N/m²"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة دقيقة"},{"level":"4 درجات","description":"خطأ في قيمة واحدة"},{"level":"2–3 درجات","description":"الوحدات صحيحة مع علاقة ناقصة"},{"level":"1 درجة","description":"وحدتان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة 1 atm = 760 kPa","ذكر وحدات غير ضغط (مثل N أو J)","القول إن atm وحدة النظام الدولي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.966Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1729, null, null, null, '(أ) 1520 mmHg × (1 atm ÷ 760 mmHg) = 2.00 atm؛ و202.6 kPa × (1 atm ÷ 101.3 kPa) = 2.00 atm. (ب) الطالب الثالث (1.5 atm)؛ لأن قراءتي الطالبين الأول والثاني متساويتان (2.00 atm).', '["1520 mmHg = 2.00 atm","202.6 kPa = 2.00 atm","تحديد الطالب الثالث"]'::jsonb, '["1520 ÷ 760 = 2.00 atm","202.6 ÷ 101.3 = 2.00 atm","1.5 atm ≠ 2.00 atm ← الطالب الثالث مختلف"]'::jsonb, '[{"element":"التحويل الأول","marks":1},{"element":"التحويل الثاني","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحويلان صحيحان واستنتاج صحيح"},{"level":"2 درجتان","description":"تحويلان دون استنتاج أو تحويل واستنتاج"},{"level":"1 درجة","description":"تحويل واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["ضرب 1520 في 760","قسمة 101.3 على 202.6 (0.5 atm)","مقارنة الأرقام دون توحيد الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.967Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1730, null, null, null, '(أ) الحل خاطئ؛ فقد ضرب في 101.3 دون القسمة على 760، أي لم يستخدم معامل التحويل الصحيح (101.3 kPa ÷ 760 mmHg)، وناتجه أكبر من الضغط الجوي بمئات المرات وهذا غير معقول. (ب) 650 mmHg × (101.3 kPa ÷ 760 mmHg) = 86.6 kPa. (ج) نعم؛ لأنه أقل من 101.3 kPa (ضغط سطح البحر)، وهذا متوقع في مدينة جبلية حيث يقل الضغط الجوي بالارتفاع.', '["الحكم بخطأ الحل وتحديد الخطأ","الناتج الصحيح 86.6 kPa","الحكم بمنطقية الناتج مع التعليل"]'::jsonb, '["معامل التحويل: 101.3 kPa ÷ 760 mmHg","650 × 101.3 ÷ 760 = 86.6 kPa"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"حساب صحيح مع تقويم أو تعليل ناقص"},{"level":"2 درجتان","description":"حساب صحيح فقط"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تأييد الطالب","قسمة 650 على 101.3 (6.42 kPa)","عدم التحقق من منطقية الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.967Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1731, 0, 'نص قانون دالتون: الضغط الكلي لخليط من الغازات يساوي مجموع الضغوط الجزئية للغازات المكونة له.', '["","الضغوط الجزئية تُجمع لا تُضرب.","كل غاز في الخليط يسهم بضغطه الجزئي، لا الغاز الأثقل وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:01.969Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1732, 2, 'الضغط الكلي يساوي مجموع الضغوط الجزئية: Ptotal = P1 + P2 + P3 + ….', '["الضغوط تُجمع لا تُضرب.","الطرح يُستخدم لإيجاد ضغط جزئي مجهول من الضغط الكلي، لا لحساب الضغط الكلي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:01.970Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1733, 1, 'الضغط الجزئي هو الضغط الذي يبذله كل غاز في الخليط لو كان وحده في الإناء نفسه وعند درجة الحرارة نفسها.', '["الضغوط الجزئية لا تتساوى بالضرورة؛ فهي تعتمد على عدد مولات كل غاز.","","لكل غاز في الخليط ضغط جزئي، لا الأثقل فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.970Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1734, 0, 'Ptotal = 3 + 4 + 2 = 9 atm.', '["","ضُربت الضغوط (3 × 4 × 2 = 24) بدل جمعها.","حُسب متوسط الضغوط (9 ÷ 3) بدل مجموعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.970Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1735, 1, 'يعتمد الضغط الجزئي على عدد المولات وحجم الإناء ودرجة الحرارة، ولا يعتمد على نوع الغاز.', '["زيادة عدد المولات تزيد الضغط الجزئي، فهو يعتمد عليها.","","الضغط الجزئي يتغير بتغير درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.970Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1736, 2, 'الضغط الجزئي لا يعتمد على نوع الغاز بل على عدد مولاته (عند ثبات الحجم ودرجة الحرارة)، وعدد مولات He وCO₂ متساوٍ (0.20 mol)، فضغطاهما الجزئيان متساويان.', '["كتلة الغاز لا تحدد ضغطه الجزئي؛ فـ CO₂ وHe لهما عدد المولات نفسه.","خفة الغاز لا تعني ضغطًا جزئيًا أقل؛ وأصغر ضغط جزئي للغاز الأقل مولات (N₂).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:01.971Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1737, 0, 'وفق قانون دالتون يصبح الضغط الكلي = ضغط He الجزئي + ضغط N₂ الجزئي، فيزداد بإضافة N₂، ويبقى ضغط He الجزئي كما هو.', '["","الضغط الجزئي لـ He لا يتأثر بإضافة غاز آخر عند ثبات الحجم ودرجة الحرارة.","ثبات الحجم لا يمنع زيادة الضغط بزيادة عدد الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.971Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1738, null, null, null, '(أ) الضغط الكلي لخليط من الغازات يساوي مجموع الضغوط الجزئية للغازات المكونة له: Ptotal = P1 + P2 + P3 + …. (ب) الضغط الجزئي: الضغط الذي يبذله كل غاز في الخليط لو كان وحده في الإناء. (ج) يعتمد على عدد المولات وحجم الإناء ودرجة الحرارة، ولا يعتمد على نوع الغاز.', '["نص القانون","الصيغة الرياضية","تعريف الضغط الجزئي","العوامل: المولات، الحجم، درجة الحرارة","لا يعتمد على نوع الغاز"]'::jsonb, '[]'::jsonb, '[{"element":"النص","marks":1},{"element":"الصيغة","marks":1},{"element":"تعريف الضغط الجزئي","marks":1},{"element":"العوامل","marks":1},{"element":"ما لا يعتمد عليه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة"},{"level":"4 درجات","description":"عنصر واحد ناقص"},{"level":"3 درجات","description":"عنصران ناقصان"},{"level":"1–2 درجة","description":"النص أو الصيغة فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة الضغوط الجزيئية بدل الجزئية","القول إن الضغط الجزئي يعتمد على نوع الغاز","تعريف الضغط الجزئي بأنه الضغط الكلي مقسومًا على عدد الغازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:01.971Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1739, null, null, null, '(أ) Ptotal = 2.4 + 1.1 + 0.5 = 4.0 atm. (ب) يصبح الضغط الكلي = 2.4 + 1.1 = 3.5 atm، ولا يتغير الضغط الجزئي لـ H₂ (يبقى 2.4 atm)؛ لأن الضغط الجزئي لكل غاز يعتمد على عدد مولاته والحجم ودرجة الحرارة، وهذه لم تتغير بالنسبة إليه.', '["Ptotal = 4.0 atm","Ptotal الجديد = 3.5 atm","ضغط H₂ الجزئي لا يتغير مع التعليل"]'::jsonb, '["Ptotal = P(H₂) + P(He) + P(Ne) = 2.4 + 1.1 + 0.5 = 4.0 atm","بعد سحب Ne: Ptotal = 2.4 + 1.1 = 3.5 atm"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) الضغط الكلي الجديد","marks":1},{"element":"(ب) الحكم على ضغط H₂ وتعليله","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة معللة"},{"level":"3 درجات","description":"حسابان صحيحان وحكم دون تعليل"},{"level":"2 درجتان","description":"حسابان صحيحان فقط"},{"level":"1 درجة","description":"(أ) فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن ضغط H₂ يزداد بعد سحب Ne","ضرب الضغوط بدل جمعها","طرح ضغط Ne مرتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.972Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1740, null, null, null, 'العبارة خاطئة؛ فالضغط الجزئي لا يعتمد على نوع الغاز، بل على عدد مولاته وحجم الإناء ودرجة الحرارة، وبما أن عدد المولات متساوٍ والحجم ودرجة الحرارة واحدة فالضغطان الجزئيان متساويان. ويُفسَّر ذلك بأن جزيئات CO₂ الأثقل أبطأ، وجسيمات He الأخف أسرع، ومتوسط طاقتيهما الحركية متساوٍ عند درجة الحرارة نفسها، فيتساوى أثرهما في الضغط على الجدران؛ لأن عدد الجسيمات متساوٍ.', '["الحكم بخطأ العبارة","الضغط الجزئي لا يعتمد على نوع الغاز","تساوي عدد المولات يعني تساوي الضغطين","التفسير بتساوي متوسط الطاقة الحركية (الأثقل أبطأ)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بقانون دالتون","marks":2},{"element":"التفسير بنظرية الحركة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل وتفسير"},{"level":"3 درجات","description":"حكم وتعليل دون تفسير بالنظرية"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"تأييد العبارة"}]'::jsonb, '["تأييد العبارة","القول إن He أكبر ضغطًا لأنه أسرع","إغفال شرط تساوي الحجم ودرجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:01.972Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1741, 1, 'Ptotal = 1.20 + 0.85 + 0.45 = 2.50 atm.', '["قُسم المجموع على عدد الغازات (2.50 ÷ 3) فحُسب المتوسط.","","ضُربت الضغوط (1.20 × 0.85 × 0.45 ≈ 0.459) بدل جمعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.974Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1742, 0, 'P(O₂) = Ptotal − P(N₂) − P(CO₂) = 1.50 − 0.80 − 0.25 = 0.45 atm.', '["","جُمعت كل القيم (1.50 + 0.80 + 0.25) بدل طرح الضغوط المعلومة من الكلي.","طُرح ضغط N₂ فقط ونُسي طرح ضغط CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.975Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1743, 2, 'نوحّد الوحدات أولًا: 380 mmHg ÷ 760 = 0.50 atm. Ptotal = 0.30 + 0.50 + 0.10 = 0.90 atm.', '["جُمعت الضغوط بوحدات مختلفة دون تحويل (0.30 + 380 + 0.10).","حُوّل 380 mmHg خطأً بالقسمة على 1000 بدل 760 (0.30 + 0.38 + 0.10 = 0.78)؛ والتحويل الصحيح يعطي 0.50 atm.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T11:15:01.975Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1744, 2, 'الغاز المجموع فوق الماء خليط من H₂ وبخار الماء: P(H₂) = 99.5 − 3.2 = 96.3 kPa.', '["جُمع ضغط بخار الماء على الكلي بدل طرحه.","قُسم الضغط الكلي على ضغط بخار الماء (99.5 ÷ 3.2) بدل الطرح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.975Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1745, 0, 'P(بقية الغازات) = 101.3 − 79.1 − 21.2 = 1.0 kPa.', '["","جُمعت كل القيم (101.3 + 79.1 + 21.2) بدل الطرح.","طُرح ضغط O₂ من ضغط N₂ (79.1 − 21.2) دون استخدام الضغط الكلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:01.976Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1746, 1, 'عند ثبات الحجم ودرجة الحرارة يحتفظ كل غاز بضغطه (الضغط الجزئي يعتمد على المولات والحجم ودرجة الحرارة): Ptotal = 0.45 + 0.32 + 0.18 = 0.95 atm.', '["نُسي ضغط الهيليوم الموجود أصلًا في الدورق الثالث (0.45 + 0.32).","","حُسب متوسط الضغوط (0.95 ÷ 3) بدل مجموعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.977Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1747, 2, 'P(He) = 5.00 − 1.05 = 3.95 atm، وبالتحويل: 3.95 × 101.3 = 400 kPa.', '["حُسب الضغط بوحدة atm ولم يُحوَّل إلى kPa.","جُمع الضغطان (6.05 atm × 101.3 ≈ 613 kPa) بدل الطرح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:01.978Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1748, null, null, null, '(أ) لأن الغاز المجموع فوق الماء خليط من O₂ وبخار الماء، والضغط الكلي يساوي مجموع ضغطيهما الجزئيين (قانون دالتون). (ب) P(O₂) = Ptotal − P(H₂O) = 100.2 − 2.6 = 97.6 kPa. (ج) 97.6 kPa × (1 atm ÷ 101.3 kPa) = 0.963 atm.', '["التعليل بوجود بخار الماء في الخليط","تطبيق قانون دالتون بالطرح","P(O₂) = 97.6 kPa","التحويل إلى 0.963 atm"]'::jsonb, '["Ptotal = P(O₂) + P(H₂O)","P(O₂) = 100.2 − 2.6 = 97.6 kPa","97.6 ÷ 101.3 = 0.963 atm"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"خطأ في التحويل أو التعليل"},{"level":"2 درجتان","description":"(ب) صحيح فقط"},{"level":"1 درجة","description":"كتابة قانون دالتون فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جمع ضغط بخار الماء بدل طرحه","إهمال بخار الماء واعتبار ضغط O₂ = 100.2 kPa","قلب معامل التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T11:15:01.978Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1749, null, null, null, '(أ) N₂: 456 ÷ 760 = 0.600 atm؛ O₂: 20.3 ÷ 101.3 = 0.200 atm؛ CO₂ = 0.40 atm. (ب) Ptotal = 0.40 + 0.600 + 0.200 = 1.20 atm. (ج) N₂ (0.600 atm).', '["تحويل N₂ = 0.600 atm","تحويل O₂ = 0.200 atm","Ptotal = 1.20 atm","تحديد N₂"]'::jsonb, '["P(N₂) = 456 mmHg ÷ 760 = 0.600 atm","P(O₂) = 20.3 kPa ÷ 101.3 = 0.200 atm","Ptotal = 0.40 + 0.600 + 0.200 = 1.20 atm"]'::jsonb, '[{"element":"(أ) التحويلان","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"3 درجات","description":"خطأ في تحويل واحد مع متابعة صحيحة"},{"level":"2 درجتان","description":"تحويلان صحيحان دون الجمع"},{"level":"1 درجة","description":"تحويل واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جمع الضغوط دون توحيد الوحدات","الحكم على الأكبر من الأرقام قبل التحويل (456)","قلب معاملات التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:01.979Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1750, null, null, null, '(أ) الحل خاطئ؛ لأن الطالب جمع الضغط الكلي مع الضغوط الجزئية، والصحيح أن الضغط الكلي يساوي مجموع الضغوط الجزئية، فالضغط الجزئي المجهول = الكلي − مجموع الضغوط الأخرى، كما أن الضغط الجزئي لا يمكن أن يكون أكبر من الضغط الكلي. (ب) P(Ar) = 2.00 − 0.75 − 0.60 = 0.65 atm. (ج) بجمع الضغوط الجزئية: 0.75 + 0.60 + 0.65 = 2.00 atm، وهو الضغط الكلي المعطى.', '["الحكم بخطأ الحل وتحديد سببه","الضغط الجزئي لا يتجاوز الكلي","P(Ar) = 0.65 atm","التحقق بالجمع"]'::jsonb, '["P(Ar) = Ptotal − P(He) − P(Ne)","= 2.00 − 0.75 − 0.60 = 0.65 atm","تحقق: 0.75 + 0.60 + 0.65 = 2.00 atm"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وحساب وتحقق"},{"level":"3 درجات","description":"تقويم وحساب صحيحان دون تحقق"},{"level":"2 درجتان","description":"حساب صحيح فقط"},{"level":"1 درجة","description":"الحكم بالخطأ فقط"},{"level":"صفر","description":"تأييد الطالب"}]'::jsonb, '["تأييد الطالب","طرح ضغط غاز واحد فقط","عدم التحقق من أن مجموع الضغوط الجزئية يساوي الكلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:01.979Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
