(1757, 1, 'معدل Ne ÷ معدل Ar = √(40 ÷ 20) = 1.41، والزمن يتناسب عكسيًا مع المعدل، فزمن Ar = 30 × 1.41 ≈ 42 s.', '["قُسم الزمن على 1.41، مع أن الأرجون الأثقل أبطأ فيحتاج زمنًا أطول.","","نُسي الجذر التربيعي (30 × 2 = 60 s)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.985Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1758, null, null, null, '(أ) المعدل يتناسب عكسيًا مع الزمن: معدل Ne ÷ معدل Y = 19.6 ÷ 15.0 = 1.31. (ب) √(M_Y ÷ 20) = 1.31 ← M_Y ÷ 20 = 1.71 ← M_Y ≈ 34 g/mol. (ج) H₂S.', '["نسبة المعدلين من الأزمنة = 1.31","تربيع النسبة","M_Y ≈ 34 g/mol","اختيار H₂S"]'::jsonb, '["معدل Ne ÷ معدل Y = t_Y ÷ t_Ne = 19.6 ÷ 15.0 ≈ 1.31","M_Y ÷ M_Ne = (1.31)² ≈ 1.71","M_Y = 20 × 1.71 ≈ 34 g/mol ← H₂S"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) التربيع","marks":1},{"element":"(ب) الناتج","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"4 درجات","description":"خطأ بسيط في التقريب"},{"level":"2–3 درجات","description":"(أ) صحيح مع خطأ في التربيع"},{"level":"1 درجة","description":"فكرة التناسب العكسي مع الزمن فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قسمة 15.0 على 19.6 (قلب نسبة الأزمنة)","نسيان التربيع (M ≈ 26 g/mol)","اعتبار المعدل متناسبًا طرديًا مع الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:01.985Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1759, null, null, null, 'الحل خاطئ؛ لأن الطالب نسي الجذر التربيعي، فقانون جراهام ينص على أن المعدل يتناسب عكسيًا مع الجذر التربيعي للكتلة المولية. الحل الصحيح: معدل Ar ÷ معدل Kr = √(84 ÷ 40) = √2.1 ≈ 1.45. فالأرجون أسرع بنحو 1.45 مرة لأن كتلته المولية أقل.', '["الحكم بخطأ الحل","تحديد الخطأ: نسيان الجذر","الناتج الصحيح ≈ 1.45","Ar أسرع لأنه أقل كتلة مولية"]'::jsonb, '["معدل Ar ÷ معدل Kr = √(M_Kr ÷ M_Ar)","= √(84 ÷ 40) = √2.1 ≈ 1.45"]'::jsonb, '[{"element":"الحكم وتحديد الخطأ","marks":1},{"element":"الحساب الصحيح","marks":2},{"element":"تحديد الأسرع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وحساب صحيح وتحديد الأسرع"},{"level":"3 درجات","description":"تقويم وحساب صحيحان دون تحديد الأسرع"},{"level":"2 درجتان","description":"تحديد الخطأ دون حساب صحيح"},{"level":"1 درجة","description":"الحكم بخطأ الحل فقط"},{"level":"صفر","description":"تأييد الطالب"}]'::jsonb, '["تأييد الحل","تصحيح الحل بقلب النسبة (0.69)","القول إن Kr أسرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:01.986Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1760, null, null, null, '(أ) الإيثان؛ لأن كتلته المولية أقل فمعدل انتشاره أكبر وفق قانون جراهام. (ب) معدل C₂H₆ ÷ معدل C₃H₈ = √(44 ÷ 30) ≈ 1.21. والزمن يتناسب عكسيًا مع المعدل، فزمن البروبان = 60 × 1.21 ≈ 73 s.', '["الإيثان أولًا","التعليل بالكتلة المولية","نسبة المعدلين ≈ 1.21","زمن البروبان ≈ 73 s"]'::jsonb, '["معدل C₂H₆ ÷ معدل C₃H₈ = √(44 ÷ 30) ≈ 1.21","t(C₃H₈) = t(C₂H₆) × 1.21 = 60 × 1.21 ≈ 73 s"]'::jsonb, '[{"element":"(أ) الحكم والتعليل","marks":2},{"element":"(ب) نسبة المعدلين","marks":1},{"element":"(ب) الزمن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ بسيط في الحساب"},{"level":"2 درجتان","description":"(أ) فقط صحيح"},{"level":"1 درجة","description":"الحكم دون تعليل"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قسمة 60 على 1.21 (50 s) فيصبح الأثقل أسرع","نسيان الجذر (88 s)","القول إن البروبان أسرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.986Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1761, 1, 'قوى التشتت أضعف القوى بين الجزيئات لأنها ناتجة عن ثنائيات قطب مؤقتة، تليها قوى ثنائية القطب بين جزيئات قطبية دائمة، وأقواها الروابط الهيدروجينية.', '["قوى ثنائية القطب أقوى من قوى التشتت لا أضعف؛ لأنها تنشأ بين أقطاب دائمة.","","هذا الترتيب معكوس؛ الروابط الهيدروجينية هي الأقوى لا الأضعف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.991Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1762, 2, 'الرابطة التساهمية O–H تربط الذرات داخل الجزيء الواحد، فهي من القوى داخل الجزيء، أما التشتت والروابط الهيدروجينية فتنشأ بين جزيء وآخر.', '["قوى التشتت تنشأ بين جزيئات O2 المتجاورة، فهي قوى بين جزيئية.","الرابطة الهيدروجينية تربط جزيئًا بجزيء آخر، فهي قوة بين جزيئية (رابطة فيزيائية).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.991Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1763, 0, 'الكتل المولية متقاربة (32 و34 و32 g/mol تقريبًا)، فالفرق الكبير في الغليان يعود إلى نوع القوى بين الجزيئات: تشتت فقط في O2، وثنائية القطب في H2S، وروابط هيدروجينية في CH3OH.', '["","الكتل المولية في الجدول متقاربة جدًا فلا تفسر فرقًا يزيد على 240 °C.","الغليان يفصل الجزيئات بعضها عن بعض ولا يكسر الروابط التساهمية داخلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:01.991Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1764, 1, 'قوى ثنائية القطب تجاذب بين الطرف الموجب جزئيًا لجزيء قطبي والطرف السالب جزئيًا لجزيء آخر، وهذه الأقطاب دائمة؛ أما قوى التشتت فتنتج عن أقطاب مؤقتة.', '["الجزيئات غير القطبية لا تملك أقطابًا دائمة، والقوة السائدة بينها هي التشتت.","","قوى ثنائية القطب من القوى بين الجزيئات، لا داخل الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.991Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1765, 0, 'جزيء HCl قطبي لفرق الكهروسالبية بين H وCl، فتنشأ بين جزيئاته قوى ثنائية القطب، ولا تتكون روابط هيدروجينية لأن الهيدروجين مرتبط بالكلور لا بـ F أو O أو N.', '["","شرط الرابطة الهيدروجينية ارتباط H بـ F أو O أو N، والكلور ليس منها.","قوى التشتت موجودة لكنها أضعف من قوى ثنائية القطب بين جزيئات HCl القطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.992Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1766, 2, 'في الميثانول ترتبط ذرة H مباشرة بذرة O (مجموعة O–H) فيتحقق شرط الرابطة الهيدروجينية، أما في CH3OCH3 فكل ذرات H مرتبطة بالكربون.', '["ذرات الهيدروجين في الإيثر مرتبطة بالكربون، فلا يتحقق شرط الرابطة الهيدروجينية.","وجود الأكسجين وحده لا يكفي؛ يجب أن يرتبط H مباشرة بـ O في الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:01.992Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1767, 0, 'من فوائد القوى بين الجزيئات أنها تحدد الحالة الفيزيائية للمادة (صلبة أو سائلة أو غازية) عند درجة حرارة معينة؛ فكلما قويت ارتفعت درجة الغليان.', '["","عدد الذرات ونوعها تحدده الصيغة الكيميائية والروابط داخل الجزيء.","التفاعلات الكيميائية تتضمن كسر الروابط داخل الجزيء وتكوين روابط جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:01.992Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1768, null, null, null, 'قوى التشتت: تنشأ عن التغير المؤقت في توزيع السحب الإلكترونية (أقطاب مؤقتة)، بين الجزيئات غير القطبية (وهي موجودة بين جميع الجزيئات)، وهي الأضعف، مثل Cl2 أو N2. قوى ثنائية القطب: تجاذب بين المناطق المختلفة الشحنة في جزيئات قطبية (أقطاب دائمة)، متوسطة القوة، مثل HCl. الروابط الهيدروجينية: تجاذب بين ذرة H مرتبطة بذرة عالية الكهروسالبية (F أو O أو N) في جزيء وذرة F أو O أو N في جزيء آخر، وهي الأقوى بين القوى الثلاث، مثل H2O وNH3.', '["سبب نشوء كل قوة","نوع الجزيئات لكل قوة","الترتيب: التشتت < ثنائية القطب < الهيدروجينية","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"سبب النشوء للأنواع الثلاثة","marks":1.5},{"element":"نوع الجزيئات","marks":1.5},{"element":"القوة النسبية","marks":1},{"element":"الأمثلة الثلاثة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة دقيقة بأمثلة صحيحة"},{"level":"4 درجات","description":"مقارنة صحيحة مع نقص عنصر واحد"},{"level":"3 درجات","description":"مقارنة صحيحة لنوعين فقط"},{"level":"2 درجتان","description":"ترتيب القوة وبعض الأمثلة فقط"},{"level":"1 درجة","description":"أمثلة صحيحة دون مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر HF أو H2O مثالًا لقوى ثنائية القطب فقط مع أنهما يكوّنان روابط هيدروجينية","عكس ترتيب القوة","وصف الرابطة الهيدروجينية بأنها رابطة تساهمية داخل الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:01.992Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1769, null, null, null, 'الترتيب: H2 < HCl < H2O. التفسير: H2 جزيء غير قطبي بين جزيئاته قوى تشتت ضعيفة جدًا فدرجة غليانه الأدنى. HCl جزيء قطبي بين جزيئاته قوى ثنائية القطب (أقوى من التشتت). H2O تنشأ بين جزيئاته روابط هيدروجينية لارتباط H بـ O، وهي الأقوى، فتحتاج جزيئاته إلى طاقة أكبر للانفصال فدرجة غليانه الأعلى.', '["الترتيب الصحيح","تحديد القوة في H2","تحديد القوة في HCl","تحديد القوة في H2O والربط بالطاقة اللازمة للغليان"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":1},{"element":"نوع القوة في كل مادة","marks":2},{"element":"الربط بين قوة التجاذب ودرجة الغليان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح مع تفسير كامل للمواد الثلاث"},{"level":"3 درجات","description":"ترتيب صحيح وتحديد صحيح للقوى دون الربط بالغليان"},{"level":"2 درجتان","description":"ترتيب صحيح مع تفسير مادة واحدة"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار HCl مكوّنًا لروابط هيدروجينية لاحتوائه على H","التفسير بالكتلة المولية مع أن H2O أخف من HCl","الاعتقاد أن الغليان يكسر الروابط التساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:01.993Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1770, null, null, null, 'العبارة خاطئة؛ فالغليان تغير فيزيائي تنفصل فيه جزيئات الماء بعضها عن بعض بالتغلب على القوى بين الجزيئات (الروابط الهيدروجينية) ويبقى كل جزيء H2O سليمًا. أما الروابط O–H فهي روابط تساهمية داخل الجزيء (قوى داخل الجزيء) أقوى كثيرًا، ولا تنكسر إلا في تغير كيميائي مثل التحليل الكهربائي للماء. القوى داخل الجزيء: أيونية وتساهمية وفلزية، والقوى بين الجزيئات: التشتت وثنائية القطب والهيدروجينية.', '["الحكم بخطأ العبارة","الغليان يتغلب على القوى بين الجزيئات","الروابط التساهمية داخل الجزيء لا تنكسر بالغليان","ذكر أنواع كل من الصنفين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح مع التعليل","marks":2},{"element":"التمييز بين الصنفين","marks":1},{"element":"أمثلة لكل صنف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتمييز كامل مع أمثلة"},{"level":"3 درجات","description":"حكم صحيح وتمييز دون أمثلة"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الرابطة الهيدروجينية والرابطة التساهمية O–H","اعتبار الغليان تغيرًا كيميائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:01.993Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1771, 2, 'جزيء I2 مكون من ذرتين متماثلتين فهو غير قطبي، والقوى الوحيدة بين جزيئاته هي قوى التشتت.', '["لا يوجد في I2 هيدروجين مرتبط بـ F أو O أو N.","جزيء I2 غير قطبي فلا توجد فيه أقطاب دائمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:01.995Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1772, 0, 'كلا الجزيئين غير قطبي، وقوى التشتت تزداد بزيادة حجم الجزيء وعدد إلكتروناته، وI2 أكبر كثيرًا من F2 فقوى التشتت بين جزيئاته أقوى فيكون صلبًا.', '["","الحالة الفيزيائية تحددها القوى بين الجزيئات لا الروابط داخل الجزيء.","I2 جزيء غير قطبي لأنه مكون من ذرتين متماثلتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.996Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1773, 1, 'يزداد حجم الجزيء نزولًا في المجموعة فتزداد قوى التشتت؛ فـ F2 وCl2 غازان، وBr2 الأكبر منهما سائل، وI2 الأكبر صلب.', '["قوى التشتت بين جزيئات Br2 أقوى من Cl2 لكبر حجمه، فلا يبقى غازًا عند درجة حرارة الغرفة.","","قوى التشتت بين جزيئات Br2 أضعف من I2، فلا يصل إلى الحالة الصلبة عند درجة حرارة الغرفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.996Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1774, 2, 'كلما زاد عدد الإلكترونات كبرت السحابة الإلكترونية وسهل تشوهها وتكوّن أقطاب مؤقتة أقوى، فتزداد قوى التشتت؛ لذا قوى التشتت بين جزيئات I2 أقوى بكثير منها بين جزيئات F2.', '["العكس هو الصحيح؛ السحابة الكبيرة أسهل تشوهًا لبعد إلكتروناتها عن النواة.","قوى التشتت تعتمد على عدد الإلكترونات وحجم الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.996Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1775, 0, 'درجة غليان اليود أعلى من الفلور لأن جزيئاته الأكبر بينها قوى تشتت أقوى تحتاج إلى طاقة أكبر لفصلها.', '["","كهروسالبية الفلور لا تجعل F2 قطبيًا لأن ذرتيه متماثلتان.","صغر الجزيء يعني إلكترونات أقل وقوى تشتت أضعف، فدرجة الغليان أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:01.996Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1776, 1, 'التحول من الحالة الصلبة إلى البخار تغير فيزيائي، تكتسب فيه الجزيئات طاقة تكفي للتغلب على قوى التشتت فتتباعد، دون أن تنكسر الرابطة التساهمية I–I.', '["تغير الحالة لا يكسر الروابط التساهمية داخل الجزيء.","","لا يمكن أن تتكون روابط هيدروجينية بين جزيئات I2 لعدم وجود الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:01.997Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1777, 2, 'البيانات تُظهر ارتفاع درجة الغليان من F2 إلى I2، أي بزيادة حجم الجزيء وعدد إلكتروناته، وذلك لزيادة قوى التشتت.', '["البيانات تظهر العكس؛ درجة الغليان ترتفع من F2 إلى I2.","كونها غير قطبية جميعًا لا يعني تساوي قوى التشتت؛ فهذه القوى تختلف باختلاف الحجم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.997Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1778, null, null, null, 'كلا الجزيئين غير قطبي لأنه يتكون من ذرتين متماثلتين، فالقوى بين جزيئاتهما هي قوى التشتت فقط. وتزداد قوى التشتت بزيادة حجم الجزيء وعدد إلكتروناته لأن السحابة الإلكترونية الكبيرة يسهل تشوهها. جزيء I2 أكبر كثيرًا من F2 وفيه إلكترونات أكثر (106 مقابل 18)، فقوى التشتت بين جزيئاته أقوى، فيكون صلبًا، أما قوى التشتت بين جزيئات F2 فضعيفة جدًا فيبقى غازًا.', '["الجزيئان غير قطبيين","القوى بينهما قوى تشتت","قوى التشتت تزداد بزيادة الحجم وعدد الإلكترونات","I2 أكبر فقواه أقوى فهو صلب، وF2 أصغر فهو غاز"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع القوى","marks":1},{"element":"العامل المؤثر في قوى التشتت","marks":1},{"element":"تطبيقه على F2 وI2 والوصول للحالة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط الحجم وعدد الإلكترونات بقوة التشتت والحالة"},{"level":"3 درجات","description":"تفسير صحيح دون ذكر عدم القطبية"},{"level":"2 درجتان","description":"ذكر أن I2 أكبر دون ربطه بقوى التشتت"},{"level":"1 درجة","description":"تحديد نوع القوى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بقوة الرابطة التساهمية داخل الجزيء","الاعتقاد أن I2 قطبي","القول إن F2 خفيف فيطير في الهواء دون ذكر القوى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:01.997Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1779, null, null, null, '(أ) F2 وCl2 غازان لأن درجتي غليانهما أقل من 25 °C. Br2 سائل لأن 25 °C أعلى من درجة انصهاره (−7 °C) وأقل من درجة غليانه (59 °C). I2 صلب لأن 25 °C أقل من درجة انصهاره (114 °C). (ب) تزداد درجة الغليان نزولًا في المجموعة لأن حجم الجزيء وعدد إلكتروناته يزدادان، فتزداد قوى التشتت بين الجزيئات وتحتاج إلى طاقة أكبر للتغلب عليها.', '["حالة F2 وCl2: غاز","حالة Br2: سائل مع التعليل","حالة I2: صلب مع التعليل","الاتجاه: ازدياد الغليان بزيادة الحجم","الربط بقوى التشتت"]'::jsonb, '[]'::jsonb, '[{"element":"حالات الهالوجينات الأربعة","marks":2},{"element":"وصف الاتجاه","marks":1},{"element":"تفسيره بقوى التشتت","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للحالات الأربع مع تفسير كامل للاتجاه"},{"level":"4 درجات","description":"الحالات صحيحة مع تفسير ناقص"},{"level":"3 درجات","description":"الحالات صحيحة دون تفسير"},{"level":"2 درجتان","description":"حالتان أو ثلاث صحيحة مع وصف الاتجاه"},{"level":"1 درجة","description":"وصف الاتجاه فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار Br2 غازًا لأنه أقل من 100 °C","الخلط بين درجة الانصهار ودرجة الغليان عند تحديد الحالة","تفسير الاتجاه بالكهروسالبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:01.998Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1780, null, null, null, 'الخطأ: جزيء I2 ليس قطبيًا؛ فهو مكون من ذرتين متماثلتين في الكهروسالبية فتتوزع الإلكترونات بينهما بالتساوي، ولذلك لا توجد بين جزيئاته قوى ثنائية القطب. التصحيح: اليود صلب لأن جزيئاته الكبيرة ذات العدد الكبير من الإلكترونات تنشأ بينها قوى تشتت قوية نسبيًا تكفي لإبقائها متماسكة في الحالة الصلبة عند درجة حرارة الغرفة.', '["تحديد الخطأ: I2 غير قطبي","تعليل عدم القطبية (ذرتان متماثلتان)","التصحيح: قوى تشتت قوية لكبر الجزيء"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ وتعليله","marks":2},{"element":"العبارة المصححة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد الخطأ وتعليله وتصحيح كامل"},{"level":"2 درجتان","description":"تحديد الخطأ وتصحيحه دون تعليل عدم القطبية"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح العبارة بذكر روابط هيدروجينية","الاكتفاء بقول «اليود ثقيل» دون ذكر قوى التشتت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:01.999Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1781, 1, 'قوى التشتت قوى ضعيفة ناتجة عن التغير المؤقت في كثافة السحب الإلكترونية، فيتكون في الجزيء قطب مؤقت.', '["انتقال الإلكترونات الدائم يكوّن أيونات، وهذه رابطة أيونية لا قوى تشتت.","","الأقطاب الدائمة سبب قوى ثنائية القطب لا قوى التشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.002Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1782, 0, 'حركة الإلكترونات المستمرة تجعل تجمعها في جانب من الجزيء لحظيًا، فيتكون قطب يزول ثم يتكون غيره، ولذلك يسمى قطبًا مؤقتًا.', '["","قوى التشتت موجودة عند جميع درجات الحرارة، وأثرها أوضح عند انخفاضها.","قوى التشتت هي التي تُبقي جزيئات السوائل غير القطبية متقاربة، فلا تختفي في السائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.002Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1783, 2, 'الطرف السالب المؤقت يتنافر مع إلكترونات الجزيء المجاور (أو يجذبها الطرف الموجب)، فتتشوه سحابته ويتكون فيه قطب مستحث، فيتجاذب القطبان؛ وهذه هي قوى التشتت.', '["القطب المستحث مؤقت ويزول بزوال المؤثر، فلا يصبح الجزيء قطبيًا دائمًا.","لا تنتقل إلكترونات بين الجزيئات في قوى التشتت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.002Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1784, 1, 'قوى التشتت تنشأ عن حركة الإلكترونات، والإلكترونات موجودة في كل الجزيئات، ولذلك تنشأ حتى بين الجزيئات غير القطبية وتكون القوة الوحيدة بينها.', '["قوى التشتت هي القوة الوحيدة بين الجزيئات غير القطبية، فلا تقتصر على القطبية.","","التجاذب بين الأيونات رابطة أيونية لا قوى تشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.002Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1785, 0, 'إلكترونات الجزيء الكبير أبعد عن الأنوية وأقل ارتباطًا بها، فتتشوه السحابة بسهولة وتتكون أقطاب مؤقتة أكبر، فتزداد قوى التشتت.', '["","عدد الإلكترونات في الجزيء المتعادل يساوي عدد البروتونات، فلا يصبح أيونًا.","القطبية الدائمة تعتمد على فرق الكهروسالبية وشكل الجزيء لا على عدد الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.003Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1786, 2, 'عدد الإلكترونات: H2 = 2 ، N2 = 14 ، Cl2 = 34؛ وكلما زاد عدد الإلكترونات وحجم الجزيء زادت قوى التشتت، فالترتيب H2 < N2 < Cl2.', '["H2 أصغر من N2 وفيه إلكترونان فقط، فقوى التشتت فيه أضعف.","هذا الترتيب معكوس؛ Cl2 أكبر الجزيئات فقوى التشتت فيه الأقوى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.003Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1787, 0, 'بعد التوزيع المتماثل للإلكترونات (المرحلة 1) تتجمع الإلكترونات لحظيًا في جانب فيتكون قطب مؤقت (المرحلة 2)، ثم يستحث قطبًا في الجزيء المجاور (المرحلة 3)، فيتجاذبان (المرحلة 4).', '["","لا ينتقل إلكترون بين الجزيئات في قوى التشتت.","الجزيء غير القطبي لا يكتسب قطبًا دائمًا؛ القطب هنا مؤقت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.003Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1788, null, null, null, '(1) الإلكترونات في جزيء Cl2 في حركة مستمرة، وتوزيعها متماثل في المتوسط. (2) في لحظة ما تتجمع الإلكترونات في أحد طرفي الجزيء فيصبح سالبًا جزئيًا والطرف الآخر موجبًا جزئيًا، فيتكون قطب مؤقت. (3) يؤثر هذا القطب في سحابة الجزيء المجاور فيشوهها ويستحث فيه قطبًا مؤقتًا. (4) يتجاذب الطرف الموجب لأحد الجزيئين مع الطرف السالب للآخر، وهذا التجاذب الضعيف هو قوى التشتت، ويتكرر باستمرار.', '["حركة الإلكترونات المستمرة","تكون قطب مؤقت","استحثاث قطب في الجزيء المجاور","التجاذب بين القطبين المؤقتين"]'::jsonb, '[]'::jsonb, '[{"element":"حركة الإلكترونات وتكون القطب المؤقت","marks":1},{"element":"القطب المستحث","marks":1},{"element":"التجاذب وتسميته قوى التشتت","marks":1},{"element":"ترتيب الخطوات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خطوات صحيحة مرتبة"},{"level":"3 درجات","description":"ثلاث خطوات صحيحة"},{"level":"2 درجتان","description":"ذكر القطب المؤقت والتجاذب فقط"},{"level":"1 درجة","description":"ذكر أنها قوى ضعيفة بين جزيئات غير قطبية دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Cl2 قطبي لأن الكلور عالي الكهروسالبية","وصف القطب بأنه دائم","افتراض انتقال إلكترونات بين الجزيئين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.003Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1789, null, null, null, 'لأن قوى التشتت تنشأ عن أقطاب مؤقتة لحظية تتكون وتزول باستمرار وتكون شحناتها الجزئية صغيرة، بينما تنشأ قوى ثنائية القطب بين أقطاب دائمة في جزيئات قطبية تبقى شحناتها الجزئية موجودة طوال الوقت، فيكون التجاذب بينها أقوى.', '["أقطاب التشتت مؤقتة وتزول","أقطاب ثنائية القطب دائمة","الربط بقوة التجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"وصف أقطاب التشتت بأنها مؤقتة","marks":1},{"element":"وصف أقطاب ثنائية القطب بأنها دائمة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل يقارن الأقطاب ويستنتج"},{"level":"2 درجتان","description":"ذكر نوعي الأقطاب دون استنتاج"},{"level":"1 درجة","description":"ذكر أن التشتت مؤقت فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعليل بأن الجزيئات غير القطبية أخف دائمًا","القول إن قوى التشتت تنشأ داخل الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:02.003Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1790, null, null, null, '(أ) رغم أن جزيئات N2 غير قطبية، تنشأ بينها قوى تشتت بسبب التغير المؤقت في توزيع السحب الإلكترونية وتكوّن أقطاب مؤقتة ومستحثة، وهذه القوى هي التي تجمع الجزيئات في الحالة السائلة عند التبريد. (ب) جزيء N2 صغير وعدد إلكتروناته قليل (14)، فقوى التشتت بين جزيئاته ضعيفة جدًا، ولا تتغلب على حركة الجزيئات إلا عندما تقل طاقتها الحركية كثيرًا بالتبريد الشديد.', '["وجود قوى تشتت بين الجزيئات غير القطبية","سببها الأقطاب المؤقتة","ضعفها لصغر الجزيء","الحاجة إلى تقليل الطاقة الحركية بالتبريد"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الجزء (أ)","marks":2},{"element":"تفسير الجزء (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للجزأين"},{"level":"3 درجات","description":"تفسير كامل لجزء وناقص للآخر"},{"level":"2 درجتان","description":"تفسير جزء واحد فقط"},{"level":"1 درجة","description":"ذكر قوى التشتت دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن الجزيئات غير القطبية لا تتجاذب إطلاقًا","عدم الربط بين التبريد وتقليل الطاقة الحركية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.004Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1791, 0, 'جزيء N2 مكون من ذرتين متماثلتين فهو غير قطبي، فلا توجد بين جزيئاته إلا قوى التشتت.', '["","HCl جزيء قطبي تنشأ بين جزيئاته قوى ثنائية القطب إضافة إلى التشتت.","NH3 تنشأ بين جزيئاته روابط هيدروجينية لارتباط H بـ N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.006Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1792, 1, 'O2 وCl2 وBr2 جزيئات ثنائية الذرة متماثلة غير قطبية، فالقوى بين جزيئاتها قوى تشتت فقط، وهي من أمثلة المذكرة.', '["هذه المواد تكوّن روابط هيدروجينية لارتباط H بـ O أو N أو F.","","هذه جزيئات قطبية تنشأ بينها قوى ثنائية القطب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.006Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1793, 2, 'H2 وN2 جزيئان غير قطبيين (ذرتان متماثلتان) فلا توجد بين جزيئاتهما إلا قوى التشتت.', '["H2S قطبي (ثنائية القطب)، وHF يكوّن روابط هيدروجينية.","كلاهما يكوّن روابط هيدروجينية لارتباط H بـ F أو O.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.006Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1794, 0, 'الهيدروكربونات مثل C2H6 غير قطبية، والهيدروجين فيها مرتبط بالكربون، فالقوى بين جزيئاتها قوى تشتت.', '["","ذرات H في الإيثان مرتبطة بالكربون لا بـ F أو O أو N.","الجزيء غير قطبي فلا أقطاب دائمة فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.007Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1795, 1, 'المادة (ب) جزيئاتها غير قطبية ولا تحتوي على H مرتبط بـ F أو O أو N، فقوى التشتت هي القوى الوحيدة بينها.', '["المادة (أ) قطبية فتنشأ بين جزيئاتها قوى ثنائية القطب.","","المادة (ج) فيها H مرتبط بـ O فتكوّن روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.007Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1796, 2, 'O2 جزيء غير قطبي لا يحتوي على ذرات H، فلا يحقق شرط الرابطة الهيدروجينية، والقوى بين جزيئاته قوى تشتت فقط.', '["الرابطة الهيدروجينية تتطلب ذرة H مرتبطة بـ F أو O أو N، وO2 لا يحتوي على H.","ذرتا الأكسجين متماثلتان في الكهروسالبية فالجزيء غير قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.007Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1797, 0, 'الميثان جزيء رباعي الأوجه متماثل فهو غير قطبي، وذرات H فيه مرتبطة بالكربون، فالقوى بين جزيئاته قوى تشتت.', '["","الماء تنشأ بين جزيئاته روابط هيدروجينية.","HBr جزيء قطبي تنشأ بين جزيئاته قوى ثنائية القطب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.007Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1798, null, null, null, 'أمثلة: الهيدروجين H2، والنيتروجين N2، والكلور Cl2 (ويقبل O2 وF2 وBr2 وI2 وCH4). الصفة المشتركة: أن جزيئاتها غير قطبية، فلا توجد فيها أقطاب دائمة تنشأ عنها قوى ثنائية القطب، ولا تحتوي على H مرتبط بـ F أو O أو N فلا تكوّن روابط هيدروجينية، فتبقى قوى التشتت الناتجة عن الأقطاب المؤقتة هي القوى الوحيدة.', '["ثلاثة أمثلة صحيحة","الجزيئات غير قطبية","لا يوجد H مرتبط بـ F أو O أو N"]'::jsonb, '[]'::jsonb, '[{"element":"الأمثلة الثلاثة","marks":1.5},{"element":"الصفة المشتركة (عدم القطبية)","marks":1},{"element":"نفي الروابط الهيدروجينية","marks":0.5}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع بيان الصفة المشتركة كاملة"},{"level":"2 درجتان","description":"ثلاثة أمثلة صحيحة مع ذكر عدم القطبية فقط"},{"level":"1 درجة","description":"مثالان صحيحان دون بيان الصفة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر HCl أو H2O مثالًا","عدم ذكر عدم القطبية سببًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.008Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1799, null, null, null, 'قوى التشتت فقط: F2 وI2 وCH4 (جزيئات غير قطبية). نوع أقوى: HCl (قوى ثنائية القطب لأنه قطبي)، وNH3 وH2O (روابط هيدروجينية لارتباط H بـ N أو O).', '["F2 وI2 وCH4 تشتت فقط","HCl ثنائية القطب","NH3 وH2O روابط هيدروجينية"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف مواد التشتت","marks":1.5},{"element":"تصنيف HCl ونوع قوته","marks":1},{"element":"تصنيف NH3 وH2O ونوع قوتهما","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للمواد الست مع الأنواع"},{"level":"3 درجات","description":"خطأ في مادة واحدة"},{"level":"2 درجتان","description":"خطأ في مادتين"},{"level":"1 درجة","description":"تصنيف صحيح لمادتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار CH4 مكونًا لروابط هيدروجينية لاحتوائه على H","اعتبار HCl مكونًا لروابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.008Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1800, null, null, null, 'الإيثان هيدروكربون غير قطبي وذرات H فيه مرتبطة بالكربون، والبروم جزيء ثنائي الذرة متماثل غير قطبي؛ فلا توجد في أي منهما أقطاب دائمة ولا روابط هيدروجينية، فالقوى بين جزيئاتهما قوى تشتت فقط. درجة غليان Br2 أعلى لأن عدد إلكتروناته (70) أكبر كثيرًا من الإيثان (18)، فسحابته الإلكترونية أكبر وأسهل تشوهًا، فقوى التشتت بين جزيئاته أقوى.', '["C2H6 غير قطبي","Br2 غير قطبي","توقع أن Br2 أعلى غليانًا","التعليل بعدد الإلكترونات وقوى التشتت"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل كون كل منهما مثالًا","marks":2},{"element":"التوقع الصحيح","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"تعليل المثالين والتوقع دون تعليل"},{"level":"2 درجتان","description":"تعليل مثال واحد مع التوقع"},{"level":"1 درجة","description":"التوقع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التوقع بأن الإيثان أعلى لأنه يحتوي على ذرات أكثر","اعتبار الإيثان قطبيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.008Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1801, 0, 'جزيء HCl قطبي لاختلاف كهروسالبية H وCl، فتتجاذب جزيئاته بقوى ثنائية القطب (الطرف δ+ لجزيء مع الطرف δ− لجزيء آخر).', '["","Cl₂ جزيء غير قطبي (ذرتان متماثلتان)، فالقوى بين جزيئاته قوى تشتت.","CH₄ جزيء غير قطبي لتماثل شكله، فالقوى بين جزيئاته قوى تشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.010Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1802, 1, 'تنشأ قوى ثنائية القطب بين الجزيئات القطبية التي لها طرف موجب جزئيًا وطرف سالب جزئيًا بصورة دائمة.', '["الجزيئات غير القطبية تسود بينها قوى التشتت.","","الذرات الفلزية ترتبط بالرابطة الفلزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.011Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1803, 2, 'الكلور أعلى كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة نحوه فيحمل δ−، ويحمل الهيدروجين δ+.', '["صغر الحجم لا يحدد الشحنة؛ الهيدروجين أقل كهروسالبية فيحمل δ+.","لو تساوت الشحنتان لكان الجزيء غير قطبي، وHCl قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:02.011Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1804, 0, 'يتجاذب الطرف السالب جزئيًا (Cl) لجزيء مع الطرف الموجب جزئيًا (H) للجزيء المجاور، فيكون Cl(δ−) لأحدهما مقابل H(δ+) للآخر.', '["","في هذا الوضع يتقابل طرفان سالبان (Cl مع Cl) فيتنافران.","في هذا الوضع يتقابل طرفان موجبان (H مع H) فيتنافران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.011Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1805, 0, 'اختلاف الكهروسالبية بين الذرتين المترابطتين يجعل الإلكترونات المشتركة أقرب إلى الذرة الأعلى كهروسالبية، فيتكون قطب دائم في الجزيء (مع شكل غير متماثل).', '["","الانتقال الكامل للإلكترون يكوّن أيونات ورابطة أيونية.","الحركة المؤقتة للإلكترونات تسبب أقطابًا مؤقتة (قوى تشتت) لا دائمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.011Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1806, 1, 'الجزيء القطبي تنشأ بين جزيئاته قوى ثنائية القطب إضافة إلى قوى التشتت، فتكون القوى بينها أكبر وتحتاج طاقة أكبر لفصلها.', '["قوى التشتت متقاربة لتقارب الحجم، والقطبي يمتلك قوة إضافية.","","تقارب الكتلة يعني تقارب قوى التشتت فقط، ويبقى الفرق في القطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:02.011Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1807, 2, 'قوى ثنائية القطب تقع في المرتبة الوسطى: أقوى من قوى التشتت وأضعف من الروابط الهيدروجينية.', '["الروابط الهيدروجينية أقوى من قوى ثنائية القطب.","قوى ثنائية القطب تنشأ بين جزيئين لا داخل الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.012Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1808, null, null, null, 'قوى ثنائية القطب: قوى تجاذب بين المناطق المختلفة الشحنة في الجزيئات القطبية، أي بين الطرف الموجب جزئيًا لجزيء والطرف السالب جزئيًا لجزيء آخر. التمثيل: δ+H–Clδ− ··· δ+H–Clδ− ··· δ+H–Clδ−؛ حيث يحمل H شحنة جزئية موجبة وCl شحنة جزئية سالبة لأنه أعلى كهروسالبية، وتترتب الجزيئات بحيث يقابل Cl لكل جزيء ذرة H للجزيء التالي.', '["التعريف الصحيح","وضع δ+ على H وδ− على Cl","ترتيب الطرف السالب مقابل الطرف الموجب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشحنات الجزئية الصحيحة","marks":1},{"element":"الترتيب الصحيح للجزيئات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وتمثيل صحيح للشحنات والترتيب"},{"level":"2 درجتان","description":"تعريف صحيح مع خطأ في الترتيب أو الشحنات"},{"level":"1 درجة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع δ− على الهيدروجين","ترتيب الجزيئات بحيث يتقابل طرفان متشابهان","الخلط بين قوى ثنائية القطب والرابطة التساهمية داخل HCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.012Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1809, null, null, null, 'قوى ثنائية القطب: تنشأ بين الجزيئات القطبية، وأقطابها دائمة ناتجة عن اختلاف الكهروسالبية، وهي أقوى من قوى التشتت. قوى التشتت: تنشأ بين الجزيئات غير القطبية (وتوجد بين جميع الجزيئات)، وأقطابها مؤقتة ناتجة عن التغير المؤقت في السحب الإلكترونية، وهي أضعف (لجزيئات متقاربة الحجم).', '["نوع الجزيئات لكل منهما","دائمة/مؤقتة","ثنائية القطب أقوى"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الجزيئات","marks":1},{"element":"طبيعة الأقطاب","marks":1},{"element":"القوة النسبية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"مقارنة صحيحة في الأوجه الثلاثة"},{"level":"2 درجتان","description":"مقارنة صحيحة في وجهين"},{"level":"1 درجة","description":"مقارنة صحيحة في وجه واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس طبيعة الأقطاب","القول إن قوى التشتت أقوى دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.012Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1810, null, null, null, 'في HBr ترتبط ذرتان مختلفتان في الكهروسالبية؛ فالبروم أعلى كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة نحوه، فيحمل Br شحنة جزئية سالبة وH شحنة جزئية موجبة، فيكون الجزيء قطبيًا ذا قطب دائم، فتتجاذب الجزيئات بقوى ثنائية القطب. أما Br2 فذرتاه متماثلتان في الكهروسالبية فتتوزع الإلكترونات بينهما بالتساوي، فالجزيء غير قطبي ولا أقطاب دائمة فيه، فلا تنشأ بين جزيئاته إلا قوى التشتت.', '["HBr: اختلاف الكهروسالبية وقطب دائم","Br2: ذرتان متماثلتان وتوزيع متساو","الاستنتاج لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير قطبية HBr","marks":2},{"element":"تفسير عدم قطبية Br2","marks":1},{"element":"ذكر قوى التشتت في Br2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للمادتين"},{"level":"3 درجات","description":"تفسير HBr كامل وBr2 ناقص"},{"level":"2 درجتان","description":"تفسير مادة واحدة"},{"level":"1 درجة","description":"ذكر أن HBr قطبي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بكبر حجم Br2","اعتبار HBr مكونًا لروابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.012Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1811, 1, 'HI جزيء قطبي لاختلاف كهروسالبية H وI، ولا يحتوي على H مرتبط بـ F أو O أو N، فتنشأ بين جزيئاته قوى ثنائية القطب.', '["Cl2 غير قطبي فبين جزيئاته قوى تشتت فقط.","","NH3 تنشأ بين جزيئاته روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:02.015Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1812, 0, 'HCl وHBr وHI جزيئات قطبية، والهيدروجين فيها غير مرتبط بـ F أو O أو N، فهي أمثلة على قوى ثنائية القطب.', '["","هذه المواد تكوّن روابط هيدروجينية لارتباط H بـ F أو O أو N، فلا تُعد أمثلة لثنائية القطب فقط.","هذه جزيئات غير قطبية تسود بينها قوى التشتت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:02.015Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1813, 2, 'جزيء HF قطبي جدًا، لكن ارتباط H مباشرة بالفلور العالي الكهروسالبية يحقق شرط الرابطة الهيدروجينية، فتكون الروابط الهيدروجينية هي القوة السائدة لا ثنائية القطب.', '["HF قطبي جدًا لفرق الكهروسالبية الكبير بين H وF.","HF مركب تساهمي قطبي (جزيئي) لا أيوني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.015Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1814, 0, 'H2S جزيء منحنٍ قطبي، والكبريت ليس من الذرات F أو O أو N، فتنشأ بين جزيئاته قوى ثنائية القطب دون روابط هيدروجينية.', '["","H2O تنشأ بين جزيئاته روابط هيدروجينية لارتباط H بـ O.","N2 غير قطبي فبين جزيئاته قوى تشتت فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.015Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1815, 2, 'فرق الكهروسالبية: HCl = 3.2 − 2.2 = 1.0 ، HBr = 3.0 − 2.2 = 0.8 ، HI = 2.7 − 2.2 = 0.5؛ فجزيء HCl أكثر قطبية فقوى ثنائية القطب بين جزيئاته أقوى.', '["فرق الكهروسالبية في HI هو الأقل (0.5) فهو الأقل قطبية.","فرق الكهروسالبية في HBr (0.8) أقل من HCl (1.0).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.016Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1816, 1, 'HCl وHBr كلاهما قطبي، فيتجاذب الطرف الموجب جزئيًا لأحدهما مع الطرف السالب جزئيًا للآخر بقوى ثنائية القطب.', '["I2 وBr2 غير قطبيين فبينهما قوى تشتت فقط.","","N2 وO2 غير قطبيين فبينهما قوى تشتت فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.016Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1817, 0, 'قوى ثنائية القطب تنشأ بين الجزيئات القطبية ذات الأقطاب الدائمة، لذا يجب أن يكون الجزيء قطبيًا.', '["","الذرتان المتماثلتان تكوّنان جزيئًا غير قطبي.","كثرة الإلكترونات تزيد قوى التشتت ولا تجعل الجزيء قطبيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T11:15:02.016Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1818, null, null, null, 'أمثلة: كلوريد الهيدروجين HCl، وبروميد الهيدروجين HBr، ويوديد الهيدروجين HI (ويقبل H2S). هذه الجزيئات قطبية لأن الهيدروجين مرتبط بذرة أعلى كهروسالبية منه، فتتكون فيها أقطاب دائمة تتجاذب. ولا تتكون فيها روابط هيدروجينية لأن الهيدروجين مرتبط بـ Cl أو Br أو I وليس بإحدى الذرات العالية الكهروسالبية الصغيرة F أو O أو N.', '["ثلاثة أمثلة صحيحة","تعليل القطبية","تعليل عدم تكون روابط هيدروجينية"]'::jsonb, '[]'::jsonb, '[{"element":"الأمثلة الثلاثة","marks":1.5},{"element":"تعليل القطبية","marks":0.5},{"element":"نفي الروابط الهيدروجينية مع السبب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع تعليل كامل"},{"level":"2 درجتان","description":"أمثلة صحيحة مع تعليل ناقص"},{"level":"1 درجة","description":"مثال أو مثالان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر HF أو H2O مثالًا لثنائية القطب","ذكر Cl2 أو HCl خلطًا بينهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.016Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1819, null, null, null, 'المعلومة غير دقيقة؛ فالمواد التي يرتبط فيها H مباشرة بـ F أو O (مثل HF وH2O) تكوّن روابط هيدروجينية بين جزيئاتها، وهي أقوى من قوى ثنائية القطب، فتُصنف أمثلة على الروابط الهيدروجينية. كما أن H–F وH–O روابط داخل الجزيء لا قوى بين الجزيئات. والأمثلة الأدق على مواد تنشأ بين جزيئاتها قوى ثنائية القطب: HCl وHBr وHI.', '["الحكم بعدم الدقة","HF وH2O يكوّنان روابط هيدروجينية","التمييز بين الرابطة داخل الجزيء والقوة بين الجزيئات","أمثلة صحيحة: HCl وHBr وHI"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل","marks":2},{"element":"اقتراح أمثلة صحيحة","marks":1},{"element":"ملاحظة أن H–F رابطة داخل الجزيء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتعليل كامل وأمثلة صحيحة"},{"level":"3 درجات","description":"حكم وتعليل وأمثلة دون التمييز بين داخل الجزيء وبينه"},{"level":"2 درجتان","description":"حكم صحيح مع أمثلة دون تعليل"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول المعلومة لأن HF وH2O جزيئات قطبية","اقتراح أمثلة غير قطبية مثل Cl2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.017Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1820, null, null, null, 'Br2: تشتت (غير قطبي). HBr: ثنائية القطب (قطبي، H مرتبط بـ Br). H2S: ثنائية القطب (قطبي، H مرتبط بـ S). CH3OCH3: ثنائية القطب (قطبي، وذرات H مرتبطة بالكربون فلا روابط هيدروجينية). CH3OH: روابط هيدروجينية (H مرتبط بـ O).', '["Br2 تشتت","HBr وH2S ثنائية القطب","CH3OCH3 ثنائية القطب","CH3OH روابط هيدروجينية"]'::jsonb, '[]'::jsonb, '[{"element":"Br2","marks":1},{"element":"HBr وH2S","marks":1},{"element":"CH3OCH3","marks":1},{"element":"CH3OH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للمواد الخمس"},{"level":"3 درجات","description":"خطأ في مادة واحدة"},{"level":"2 درجتان","description":"خطأ في مادتين"},{"level":"1 درجة","description":"تصنيف صحيح لمادتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار CH3OCH3 مكونًا لروابط هيدروجينية لاحتوائه على O","اعتبار H2S مكونًا لروابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:02.017Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1821, 0, 'في NH₃ ترتبط ذرة H بذرة N عالية الكهروسالبية، ولذرة N زوج إلكترونات حر، فتتكون روابط هيدروجينية بين الجزيئات.', '["","ذرات H في CH₄ مرتبطة بالكربون، وهو ليس F أو O أو N، فلا تتكون روابط هيدروجينية.","H₂ جزيء غير قطبي، والقوى بين جزيئاته قوى تشتت فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.019Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1822, 0, 'يشترط أن يرتبط الهيدروجين بذرة صغيرة عالية الكهروسالبية، وهي الفلور أو الأكسجين أو النيتروجين.', '["","ارتباط H بـ Cl أو Br أو I يعطي جزيئات قطبية تنشأ بينها قوى ثنائية القطب فقط.","كهروسالبية C وS وP غير كافية لتكوين روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.019Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1823, 1, 'الرابطة الهيدروجينية قوة بين جزيئية؛ فكسرها عند الغليان مثلًا تغير فيزيائي يبقي الجزيئات سليمة، ولذلك تسمى رابطة فيزيائية.', '["الروابط داخل الجزيء روابط كيميائية (تساهمية) لا فيزيائية.","","الروابط الهيدروجينية تنكسر في تغيرات فيزيائية كالغليان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.019Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1824, 2, 'الرابطة الهيدروجينية تنشأ بين ذرة H (δ+) مرتبطة بـ O في جزيء، وذرة O (δ−) التي تحمل أزواجًا غير مرتبطة في جزيء آخر.', '["ذرتا H تحملان شحنتين موجبتين جزئيتين فتتنافران ولا تتجاذبان.","O–H داخل الجزيء رابطة تساهمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.021Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1825, 0, 'الروابط الهيدروجينية قوى قوية بين الجزيئات تحتاج طاقة أكبر لفصلها، فوجودها يرفع درجة الغليان.', '["","التجاذب الأقوى بين الجزيئات يحتاج طاقة أكبر لا أقل للتغلب عليه.","درجة الغليان تعتمد على قوة القوى بين الجزيئات، فلا بد أن تتأثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.022Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1826, 1, 'ارتباط H بـ F أو O أو N يجعل الرابطة شديدة القطبية فيحمل H شحنة جزئية موجبة كبيرة، ولصغر حجمه يقترب كثيرًا من الذرة السالبة في الجزيء المجاور فيكون التجاذب قويًا.', '["الرابطة قطبية لا أيونية؛ لا ينتقل الإلكترون انتقالًا كاملًا.","","الرابطة الهيدروجينية قوة بين جزيئية لا رابطة تساهمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.022Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1827, 2, 'في HF يرتبط H مباشرة بالفلور العالي الكهروسالبية، ويحمل F أزواجًا غير مرتبطة، فتتكون روابط هيدروجينية.', '["H في الميثان مرتبط بالكربون.","H في H2S مرتبط بالكبريت، وهو ليس من F أو O أو N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.022Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1828, null, null, null, 'الرابطة الهيدروجينية: قوة تجاذب قوية (رابطة فيزيائية) بين ذرة هيدروجين مرتبطة بذرة عالية الكهروسالبية في جزيء وذرة عالية الكهروسالبية في جزيء آخر. شرطاها: (1) وجود ذرة عالية الكهروسالبية صغيرة الحجم (F أو O أو N) تحمل أزواجًا غير مرتبطة في أحد الجزيئين. (2) وجود ذرة H مرتبطة مباشرة بإحدى الذرات F أو O أو N في الجزيء الآخر.', '["التعريف","الشرط الأول: ذرة F أو O أو N","الشرط الثاني: H مرتبطة بـ F أو O أو N"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشرط الأول","marks":1},{"element":"الشرط الثاني","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وشرطان صحيحان"},{"level":"2 درجتان","description":"تعريف صحيح وشرط واحد"},{"level":"1 درجة","description":"تعريف صحيح فقط أو شرطان دون تعريف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بوجود H في الجزيء","إدخال Cl ضمن الذرات المطلوبة","وصفها بأنها رابطة داخل الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.022Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1829, null, null, null, 'في كل جزيء NH3 ترتبط ذرة N بثلاث ذرات H، وN أعلى كهروسالبية فتحمل δ− وتحمل كل H شحنة δ+. تنشأ الرابطة الهيدروجينية بين ذرة H (δ+) من الجزيء الأول وذرة N (δ−) ذات الزوج غير المرتبط في الجزيء الثاني: H2N–H(δ+) ··· :N(δ−)H3.', '["شحنة δ− على N وδ+ على H","الرابطة بين H من جزيء وN من الجزيء الآخر","تمييز الرابطة الهيدروجينية (···) عن الرابطة التساهمية (–)"]'::jsonb, '[]'::jsonb, '[{"element":"الشحنات الجزئية","marks":1},{"element":"موقع الرابطة الصحيح","marks":1},{"element":"التمييز بين نوعي الرابطة في الرسم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"رسم صحيح كامل"},{"level":"2 درجتان","description":"موقع صحيح مع خطأ في الشحنات أو التمييز"},{"level":"1 درجة","description":"ذكر أن الرابطة بين جزيئي NH3 دون تحديد موقعها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الرابطة بين ذرتي H","رسم الرابطة بين N وH داخل الجزيء نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.022Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1830, null, null, null, 'CH3OH: نعم، لأن ذرة H مرتبطة مباشرة بذرة O (مجموعة O–H)، والأكسجين يحمل أزواجًا غير مرتبطة. HCl: لا، لأن H مرتبط بالكلور وهو ليس من F أو O أو N، فتنشأ بين جزيئاته قوى ثنائية القطب. CH4: لا، لأن H مرتبط بالكربون، والجزيء غير قطبي فتنشأ بين جزيئاته قوى تشتت.', '["CH3OH نعم مع التعليل","HCl لا مع التعليل","CH4 لا مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"CH3OH","marks":1},{"element":"HCl","marks":1},{"element":"CH4","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم وتعليل صحيحان للمواد الثلاث"},{"level":"2 درجتان","description":"حكم وتعليل صحيحان لمادتين"},{"level":"1 درجة","description":"حكم صحيح لمادة واحدة مع تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار HCl مكونًا لروابط هيدروجينية لأن الكلور عالي الكهروسالبية","اعتبار CH4 مكونًا لها لاحتوائه على أربع ذرات H"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.023Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1831, 1, 'في الماء ترتبط كل ذرة H مباشرة بذرة O، فتنشأ روابط هيدروجينية بين جزيئاته، وهو من أمثلة المذكرة.', '["H2 غير قطبي وH فيه غير مرتبط بـ F أو O أو N.","","H في HCl مرتبط بالكلور فتنشأ قوى ثنائية القطب لا روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.025Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1832, 0, 'في H2O وNH3 وHF يرتبط الهيدروجين مباشرة بـ O أو N أو F، فجميعها تكوّن روابط هيدروجينية.', '["","H2S وHCl لا يكوّنان روابط هيدروجينية لارتباط H بـ S وCl.","CH4 وN2 لا يكوّنان روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.025Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1833, 2, 'في NH3 يرتبط H مباشرة بـ N، وعلى N زوج غير مرتبط، فتتكون روابط هيدروجينية.', '["في الإيثر ذرات H مرتبطة بالكربون رغم وجود الأكسجين.","الكبريت ليس من F أو O أو N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.025Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1834, 1, 'وجود مجموعة الهيدروكسيل O–H يجعل H مرتبطًا مباشرة بالأكسجين، فيتحقق شرط الرابطة الهيدروجينية.', '["ارتباط H بالكربون لا يحقق شرط الرابطة الهيدروجينية.","","الإيثانول جزيء قطبي، وعدم القطبية يعني قوى تشتت فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T11:15:02.026Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1835, 0, 'H2O أخف من H2S لكن درجة غليانه أعلى كثيرًا (100 °C مقابل −60 °C)، وهذا يدل على روابط هيدروجينية بين جزيئاته لارتباط H بـ O.', '["","H2S أثقل من H2O لكن غليانه أقل كثيرًا لأن S لا يكوّن روابط هيدروجينية.","CH4 غير قطبي وغليانه منخفض جدًا (قوى تشتت فقط)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.026Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1836, 2, 'في CH3OCH3 لا توجد ذرة H مرتبطة بالأكسجين، فكل ذرات H مرتبطة بالكربون، فلا تتكون روابط هيدروجينية بين جزيئاته.', '["الميثانول يحتوي على O–H فيكوّن روابط هيدروجينية.","الأمونيا تحتوي على N–H فتكوّن روابط هيدروجينية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.026Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1837, 1, 'يمكن أن ترتبط ذرة H في الماء (مرتبطة بـ O) بذرة N في الأمونيا، أو H في الأمونيا بذرة O في الماء، فتتكون روابط هيدروجينية بينهما.', '["لا يوجد H مرتبط بـ F أو O أو N في أي منهما.","","الجزيئان غير قطبيين ولا يحققان الشرط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.027Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1838, null, null, null, 'الماء H2O: الهيدروجين مرتبط بالأكسجين O. الأمونيا NH3: الهيدروجين مرتبط بالنيتروجين N. فلوريد الهيدروجين HF: الهيدروجين مرتبط بالفلور F. (ويقبل الميثانول CH3OH والإيثانول: H مرتبط بـ O).', '["ثلاثة أمثلة صحيحة","تحديد الذرة المرتبطة بالهيدروجين في كل مثال"]'::jsonb, '[]'::jsonb, '[{"element":"الأمثلة الثلاثة","marks":1.5},{"element":"تحديد الذرات","marks":1.5}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع تحديد الذرات"},{"level":"2 درجتان","description":"ثلاثة أمثلة دون تحديد الذرات أو مثالان مع التحديد"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر HCl أو H2S مثالًا","ذكر CH4 لاحتوائه على الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:02.027Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1839, null, null, null, '(أ) HF ، H2O ، NH3 ، CH3OH؛ لأن الهيدروجين فيها مرتبط مباشرة بـ F أو O أو N. (ب) مثلًا: H2S لا يكوّن روابط هيدروجينية لأن H مرتبط بالكبريت وهو ليس من F أو O أو N (تنشأ قوى ثنائية القطب). CH3OCH3 لا يكوّن روابط هيدروجينية بين جزيئاته لأن ذرات H مرتبطة بالكربون رغم وجود الأكسجين. (ويقبل HCl: H مرتبط بـ Cl، أو H2: جزيء غير قطبي).', '["استخراج المواد الأربع","تعليل المادة الأولى","تعليل المادة الثانية"]'::jsonb, '[]'::jsonb, '[{"element":"المواد الأربع في (أ)","marks":2},{"element":"تعليل مادتين في (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"استخراج صحيح كامل وتعليل صحيح لمادتين"},{"level":"3 درجات","description":"استخراج صحيح مع تعليل مادة واحدة"},{"level":"2 درجتان","description":"استخراج ثلاث مواد صحيحة مع تعليل ناقص"},{"level":"1 درجة","description":"استخراج مادتين صحيحتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدخال CH3OCH3 لاحتوائه على O","إدخال HCl لأن Cl عالي الكهروسالبية","إغفال CH3OH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.027Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1840, null, null, null, 'HF مثال على مادة تنشأ بين جزيئاتها روابط هيدروجينية لأن H مرتبط مباشرة بالفلور العالي الكهروسالبية، وهي قوى قوية تحتاج إلى طاقة كبيرة لفصل الجزيئات، فدرجة غليانه مرتفعة نسبيًا. أما HCl فالهيدروجين فيه مرتبط بالكلور فلا تتكون روابط هيدروجينية، والقوى بين جزيئاته قوى ثنائية القطب أضعف، فدرجة غليانه أقل رغم أن كتلته المولية أكبر.', '["HF يكوّن روابط هيدروجينية مع التعليل","HCl ثنائية القطب فقط","الربط بين قوة التجاذب ودرجة الغليان","الكتلة ليست العامل الحاسم هنا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع القوى في HF وتعليله","marks":1.5},{"element":"تحديد نوع القوى في HCl","marks":1},{"element":"الربط بدرجة الغليان","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يحدد القوى ويربطها بالغليان"},{"level":"3 درجات","description":"تحديد صحيح للقوى مع ربط ناقص"},{"level":"2 درجتان","description":"تحديد القوى في مادة واحدة"},{"level":"1 درجة","description":"ذكر أن HF أعلى غليانًا دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بالكتلة المولية","اعتبار HCl مكونًا لروابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.028Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1841, 1, 'الأكسجين أعلى كهروسالبية من النيتروجين فالرابطة O–H أكثر قطبية، ويكوّن جزيء الماء روابط هيدروجينية أكثر، فتكون القوى بين جزيئاته أقوى.', '["الكتلتان متقاربتان جدًا (18 و17 g/mol)، فالفرق لا يفسر الفرق الكبير في الغليان.","","الأمونيا جزيء قطبي ويكوّن روابط هيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-10-11T11:15:02.030Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1842, 2, 'كهروسالبية الأكسجين أعلى من النيتروجين، فتكون الرابطة O–H أكثر قطبية والشحنة الجزئية على H أكبر، فتقوى الروابط الهيدروجينية بين جزيئات الماء.', '["الأكسجين أعلى كهروسالبية من النيتروجين لا العكس.","كهروسالبية O وN مختلفة، فتختلف قوة الروابط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.030Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1843, 0, 'الفرق في الكتلة 1 g/mol فقط، بينما الفرق في الغليان نحو 133 °C؛ فالسبب هو قوة الروابط الهيدروجينية الأكبر في الماء لا الكتلة.', '["","البيانات تُظهر أن الماء هو الأعلى غليانًا.","فرق الكتلة ضئيل (1 g/mol) لا يفسر فرقًا نحو 133 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
