(1844, 1, 'على ذرة O في الماء زوجان غير مرتبطين، وعلى ذرة N في الأمونيا زوج واحد؛ ولذلك يستطيع جزيء الماء تكوين روابط هيدروجينية أكثر.', '["هذا معكوس؛ الأكسجين يحمل زوجين والنيتروجين زوجًا واحدًا.","","النيتروجين يرتبط بثلاث ذرات H فيبقى عليه زوج واحد فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1845, 0, 'للماء ذرتا H (تشارك كل منهما في رابطة) وزوجان غير مرتبطين على O (يستقبل كل منهما رابطة)، أما الأمونيا فلها ثلاث ذرات H لكن زوج واحد فقط على N يحد من عدد الروابط.', '["","عدد الإلكترونات متساوٍ (10 لكل منهما) والحجم متقارب.","عدد ذرات H الأكبر لا يفيد مع وجود زوج غير مرتبط واحد فقط، ولا يسبب تنافرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.031Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1846, 2, 'درجة غليان الأمونيا (−33 °C) أقل كثيرًا من 25 °C فتغلي وتتحول إلى غاز، أما الماء فدرجة غليانه 100 °C فيبقى سائلًا.', '["هذا عكس المتوقع؛ الماء يغلي عند 100 °C.","الأمونيا لا تبقى سائلة عند 25 °C تحت الضغط الجوي لأن غليانها −33 °C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.032Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1847, 2, 'الماء والأمونيا كلاهما يكوّن روابط هيدروجينية، لكنها في الماء أقوى (كهروسالبية O أعلى) وأكثر عددًا.', '["الأمونيا تكوّن روابط هيدروجينية لارتباط H بـ N.","لو تساوت القوة لتقاربت درجتا الغليان، والفرق بينهما كبير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.032Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1848, null, null, null, 'السبب أن الروابط الهيدروجينية بين جزيئات الماء أقوى وأكثر عددًا منها بين جزيئات الأمونيا: (1) الأكسجين أعلى كهروسالبية من النيتروجين، فالرابطة O–H أكثر قطبية من N–H وتكون الشحنة الجزئية على H أكبر، فتقوى الروابط الهيدروجينية في الماء. (2) جزيء الماء فيه ذرتا H وزوجان غير مرتبطين، فيكوّن روابط هيدروجينية أكثر من الأمونيا التي على ذرة النيتروجين فيها زوج واحد غير مرتبط. لذلك تحتاج جزيئات الماء إلى طاقة أكبر لتنفصل، فدرجة غليانه (100 °C) أعلى بكثير من الأمونيا (−33 °C تقريبًا)، فيكون سائلًا عند درجة حرارة الغرفة والأمونيا غازًا.', '["كلاهما يكوّن روابط هيدروجينية","كهروسالبية O أعلى من N","الماء يكوّن روابط هيدروجينية أكثر","الربط بالطاقة اللازمة ودرجة الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"أثر الكهروسالبية","marks":1.5},{"element":"عدد الروابط الهيدروجينية","marks":1.5},{"element":"الربط بدرجة الغليان والحالة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالعاملين مع الربط بالحالة"},{"level":"3 درجات","description":"تفسير بالعاملين دون ربط بالحالة"},{"level":"2 درجتان","description":"تفسير بعامل واحد مع الربط"},{"level":"1 درجة","description":"ذكر أن الروابط في الماء أقوى دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بالكتلة المولية","القول إن الأمونيا لا تكوّن روابط هيدروجينية","القول إن النيتروجين أعلى كهروسالبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-10-11T11:15:02.032Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1849, null, null, null, 'التفسير غير مقبول؛ لأن الفرق في الكتلة المولية 1 g/mol فقط، بينما الفرق في درجتي الغليان نحو 133 °C (100 − (−33))، وفرق ضئيل في الكتلة لا يمكن أن يسبب هذا الفرق الكبير. التفسير الصحيح: الروابط الهيدروجينية بين جزيئات الماء أقوى (لأن O أعلى كهروسالبية من N) وأكثر عددًا (زوجان غير مرتبطين على O مقابل زوج واحد على N).', '["الحكم بعدم صحة التفسير","حساب الفرق في الكتلة والغليان","التفسير الصحيح"]'::jsonb, '["فرق الكتلة = 18 − 17 = 1 g/mol","فرق الغليان = 100 − (−33) = 133 °C","المقارنة: فرق ضئيل في الكتلة مقابل فرق كبير في الغليان"]'::jsonb, '[{"element":"الحكم مع الاستدلال بالأرقام","marks":2},{"element":"التفسير الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مستدل بالأرقام مع تفسير بديل كامل"},{"level":"3 درجات","description":"حكم صحيح بالأرقام مع تفسير بديل ناقص"},{"level":"2 درجتان","description":"حكم صحيح مع تفسير بديل دون أرقام"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول تفسير الطالب","حساب فرق الغليان 67 °C بإهمال الإشارة السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.032Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1850, null, null, null, 'الماء: الهيدروجين مرتبط بالأكسجين؛ على O زوجان غير مرتبطين؛ الروابط الهيدروجينية أقوى؛ سائل. الأمونيا: الهيدروجين مرتبط بالنيتروجين؛ على N زوج واحد غير مرتبط؛ الروابط الهيدروجينية أضعف؛ غاز.', '["الذرة المرتبطة بـ H","عدد الأزواج غير المرتبطة","قوة الروابط الهيدروجينية","الحالة الفيزيائية"]'::jsonb, '[]'::jsonb, '[{"element":"الذرة المرتبطة","marks":1},{"element":"عدد الأزواج","marks":1},{"element":"قوة الروابط","marks":1},{"element":"الحالة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الأوجه الأربعة"},{"level":"3 درجات","description":"ثلاثة أوجه صحيحة"},{"level":"2 درجتان","description":"وجهان صحيحان"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس عدد الأزواج غير المرتبطة","وصف الأمونيا بأنها سائلة عند درجة حرارة الغرفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.033Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1851, 1, 'الأوكتان والميثان هيدروكربونات غير قطبية، والهيدروجين فيها مرتبط بالكربون، فالقوى بين جزيئاتهما قوى تشتت فقط.', '["H مرتبط بالكربون لا بـ F أو O أو N.","","الأوكتان غير قطبي مثل الميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.035Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1852, 2, 'قوى التشتت تزداد بزيادة حجم الجزيء وعدد إلكتروناته؛ وجزيء الأوكتان (66 إلكترونًا) أكبر كثيرًا من الميثان (10 إلكترونات)، فقوى التشتت بين جزيئاته أقوى.', '["كلاهما غير قطبي.","الحالة الفيزيائية تحددها القوى بين الجزيئات لا الروابط داخلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.035Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1853, 0, 'M = 8(12.0) + 18(1.0) = 96 + 18 = 114 g/mol.', '["","ناتج 8(12.0) + 6(1.0): خطأ في عدد ذرات الهيدروجين.","ناتج جمع عدد الذرات (8 + 18 = 26) دون ضربها في الكتل الذرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.036Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1854, 1, 'كلما زاد عدد ذرات الكربون زاد حجم الجزيء وعدد إلكتروناته فتقوى قوى التشتت وترتفع درجة الغليان: من −162 °C للميثان إلى 126 °C للأوكتان.', '["البيانات تُظهر العكس.","","البيانات تُظهر علاقة طردية واضحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.036Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1855, 2, 'درجة غليان البنتان (36 °C) أعلى من 25 °C فيبقى سائلًا، أما البروبان (−42 °C) والميثان (−162 °C) فدرجتا غليانهما أقل من 25 °C فهما غازان.', '["درجة غليان البروبان −42 °C أقل من درجة حرارة الغرفة فهو غاز.","درجة غليان الميثان −162 °C فهو غاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T11:15:02.036Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1856, 0, 'شرط الرابطة الهيدروجينية أن يرتبط H بذرة F أو O أو N، وفي الأوكتان كل ذرات H مرتبطة بالكربون.', '["","الأوكتان يحتوي فعلًا على 18 ذرة هيدروجين.","الأوكتان مركب تساهمي جزيئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.036Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1857, 1, '114 ÷ 16 ≈ 7.1، أي أن جزيء الأوكتان أثقل بنحو 7 مرات، ويرافق ذلك حجم أكبر وإلكترونات أكثر وقوى تشتت أقوى.', '["ناتج عكس القسمة (16 ÷ 114 ≈ 0.14).","","ناتج طرح الكتلتين (114 − 16 = 98) لا قسمتهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.036Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1858, null, null, null, 'الأوكتان والميثان مركبان هيدروكربونيان غير قطبيين، والقوى بين جزيئاتهما قوى تشتت فقط. جزيء الأوكتان أكبر كثيرًا من جزيء الميثان (سلسلة من 8 ذرات كربون، وكتلة مولية 114 g/mol مقابل 16 g/mol) ويحتوي على عدد أكبر من الإلكترونات (66 مقابل 10)، فسحابته الإلكترونية أسهل تشوهًا وقوى التشتت بين جزيئاته أقوى، فتحتاج إلى طاقة أكبر للانفصال، فيكون سائلًا، بينما قوى التشتت بين جزيئات الميثان الصغيرة ضعيفة فيكون غازًا.', '["كلاهما غير قطبي","القوى قوى تشتت","الأوكتان أكبر حجمًا وكتلة وإلكترونات","قوى تشتت أقوى فهو سائل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع القوى","marks":1},{"element":"المقارنة في الحجم/الكتلة/الإلكترونات","marks":1},{"element":"الاستنتاج بقوة التشتت والحالة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجتان","description":"تعليل بالحجم دون ذكر نوع القوى"},{"level":"1 درجة","description":"ذكر أن الأوكتان أكبر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر روابط هيدروجينية في الأوكتان","التعليل بقوة الروابط C–C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.037Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1859, null, null, null, 'الأوكتان: M = 8(12.0) + 18(1.0) = 114 g/mol. الميثان: M = 12.0 + 4(1.0) = 16.0 g/mol. الأوكتان أثقل بنحو 7 مرات (114 ÷ 16 ≈ 7.1)، فجزيئه أكبر وفيه إلكترونات أكثر، فتكون قوى التشتت بين جزيئاته (وكلاهما غير قطبي) أقوى، فالأوكتان سائل والميثان غاز.', '["حساب كتلة الأوكتان","حساب كتلة الميثان","الربط بين الكتلة/الحجم وقوى التشتت","الاستنتاج"]'::jsonb, '["M(C8H18) = 8 × 12.0 + 18 × 1.0 = 114 g/mol","M(CH4) = 12.0 + 4 × 1.0 = 16.0 g/mol","114 ÷ 16 ≈ 7.1","الأكبر كتلة وحجمًا → قوى تشتت أقوى → سائل"]'::jsonb, '[{"element":"حساب الكتلتين","marks":2},{"element":"الربط بقوى التشتت","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسير كامل"},{"level":"3 درجات","description":"حسابان صحيحان وتفسير ناقص"},{"level":"2 درجتان","description":"حساب صحيح واحد مع تفسير"},{"level":"1 درجة","description":"حساب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوحدة g بدل g/mol","نسيان ضرب عدد ذرات H في كتلتها","تفسير الحالة بالكتلة دون ذكر قوى التشتت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T11:15:02.037Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1860, null, null, null, 'الترتيب: CH4 < C4H10 < C8H18. التفسير: جميعها غير قطبية والقوى بين جزيئاتها قوى تشتت، وتزداد هذه القوى بزيادة طول السلسلة الكربونية (حجم الجزيء وعدد الإلكترونات)، فترتفع درجة الغليان. البيوتان عند 25 °C غاز لأن درجة غليانه (−1 °C) أقل من 25 °C.', '["الترتيب الصحيح","نوع القوى","العلاقة بين الحجم وقوى التشتت","حالة البيوتان"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"التفسير","marks":2},{"element":"حالة البيوتان مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب وتفسير وتوقع صحيح"},{"level":"3 درجات","description":"ترتيب وتفسير صحيحان دون التوقع"},{"level":"2 درجتان","description":"ترتيب صحيح مع توقع صحيح دون تفسير"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع أن البيوتان سائل لأن غليانه قريب من الصفر","التفسير بالقطبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.037Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1861, 0, 'جسيمات المادة الصلبة متراصة بشدة في مواقع ثابتة تربطها قوى تجاذب قوية جدًا، فلا تستطيع إلا الاهتزاز في أماكنها.', '["","هذا وصف جسيمات السائل.","هذا وصف جسيمات الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:02.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1862, 1, 'قوى التجاذب في السائل أضعف منها في الصلب، فتستطيع جسيماته الانزلاق بعضها فوق بعض وتغيير مواقعها، بينما جسيمات الصلب تهتز في مواقعها الثابتة.', '["جسيمات السائل في حركة مستمرة، ولا توجد جسيمات ساكنة تمامًا.","","جسيمات السائل متقاربة وتتجاذب بقوى تحد من حركتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:02.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1863, 2, 'جسيمات الصلب مثبتة في مواقعها بقوى تجاذب قوية فيبقى شكله ثابتًا، أما جسيمات السائل فتنزلق وتغير مواقعها فتأخذ شكل الإناء.', '["حجم الجسيمات للمادة نفسها لا يتغير بتغير الحالة.","جسيمات الصلب متراصة أكثر لا متباعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1864, 0, 'في كثير من المواد الصلبة (البلورية) تترتب الجسيمات في نمط هندسي منتظم، بينما يكون ترتيبها في السائل غير منتظم.', '["","التباعد والعشوائية الكاملة من صفات الغاز.","جسيمات الصلب مرتبة في مواقع محددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1865, 2, 'جسيمات المادة الصلبة ليست ساكنة؛ فلها طاقة حركية تعتمد على درجة الحرارة، لكنها تقتصر على الاهتزاز حول مواقع ثابتة.', '["هذا اعتقاد خاطئ شائع؛ الجسيمات تهتز ولا تكون ساكنة.","الحركة الحرة صفة جسيمات الغاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T11:15:02.040Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1866, 1, 'عند الانصهار تكتسب الجزيئات طاقة تكفي للتغلب جزئيًا على قوى التجاذب، فتترك مواقعها الثابتة وتنزلق بعضها فوق بعض مع بقائها متقاربة.', '["التباعد الكبير والحركة الحرة يحدثان عند التحول إلى غاز.","","الانصهار يقلل ثبات المواقع لا يزيده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.041Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1867, 0, 'قوى التجاذب بين جسيمات المادة الصلبة قوية جدًا فتثبتها في مواقعها، بينما هي في السائل أضعف فتسمح بانزلاق الجسيمات.', '["","لو كانت أقوى في السائل لكانت جسيماته أكثر ثباتًا من الصلب.","لو تساوت لما اختلفت حركة الجسيمات في الحالتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.041Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1868, null, null, null, 'المادة الصلبة: جسيماتها متراصة بشدة في مواقع ثابتة، تهتز في أماكنها فقط، وقوى التجاذب بينها قوية جدًا، ولها شكل ثابت وحجم ثابت. السائل: جسيماته متقاربة لكنها غير مثبتة، تنزلق بعضها فوق بعض، وقوى التجاذب بينها أضعف، وله حجم ثابت ويأخذ شكل الإناء.', '["تقارب الجسيمات","حركة الجسيمات","قوى التجاذب","الشكل والحجم"]'::jsonb, '[]'::jsonb, '[{"element":"تقارب الجسيمات","marks":1},{"element":"حركتها","marks":1},{"element":"قوى التجاذب","marks":1},{"element":"الشكل والحجم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الأوجه الأربعة"},{"level":"3 درجات","description":"ثلاثة أوجه صحيحة"},{"level":"2 درجتان","description":"وجهان صحيحان"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف جسيمات الصلب بأنها ساكنة","القول إن السائل ليس له حجم ثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.041Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1869, null, null, null, 'جسيمات الماء متقاربة لكن قوى التجاذب بينها أضعف، فتنزلق بعضها فوق بعض وتغير مواقعها، فيسيل الماء ويأخذ شكل الإناء الجديد. أما جسيمات الحديد فمتراصة في مواقع ثابتة تربطها قوى تجاذب قوية جدًا، فلا تستطيع إلا الاهتزاز في أماكنها، فتحتفظ القطعة بشكلها ولا تنسكب.', '["جسيمات الماء تنزلق وتغير مواقعها","قوى التجاذب في السائل أضعف","جسيمات الحديد ثابتة المواقع بقوى قوية"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير سلوك الماء","marks":1.5},{"element":"تفسير سلوك الحديد","marks":1.5}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل للحالتين"},{"level":"2 درجتان","description":"تفسير كامل لحالة وناقص للأخرى"},{"level":"1 درجة","description":"تفسير حالة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بثقل الحديد","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:02.042Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1870, null, null, null, 'في الشمع الصلب تكون الجسيمات متراصة في مواقع ثابتة تهتز في أماكنها بفعل قوى تجاذب قوية. بالتسخين تزداد الطاقة الحركية فيزداد اهتزاز الجسيمات، وعند درجة الانصهار تصبح طاقتها كافية للتغلب جزئيًا على قوى التجاذب، فتترك مواقعها الثابتة وتنزلق بعضها فوق بعض مع بقائها متقاربة، فيفقد الشمع شكله الثابت ويحتفظ بحجمه تقريبًا ويأخذ شكل الإناء.', '["وصف الحالة الصلبة","زيادة الطاقة الحركية بالتسخين","التغلب الجزئي على قوى التجاذب","وصف الحالة السائلة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحالة الابتدائية","marks":1},{"element":"دور التسخين والطاقة الحركية","marks":1},{"element":"وصف الحالة النهائية","marks":1},{"element":"بقاء الجسيمات متقاربة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نموذج كامل مترابط"},{"level":"3 درجات","description":"نموذج صحيح ينقصه عنصر"},{"level":"2 درجتان","description":"وصف الحالتين دون دور الطاقة"},{"level":"1 درجة","description":"وصف حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجسيمات تتباعد كثيرًا كالغاز","القول إن الجسيمات تكبر بالتسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.043Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1871, 1, 'للسائل حجم ثابت لكنه يأخذ شكل الإناء الذي يوضع فيه لأن جسيماته تنزلق بعضها فوق بعض.', '["لا يوجد سائل له شكل ثابت.","","تغير الشكل والحجم معًا صفة الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.045Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1872, 2, 'السوائل غير قابلة للانضغاط تقريبًا لتقارب جسيماتها، فقابلية الانضغاط الكبيرة صفة للغازات لا للسوائل.', '["كثافة السوائل أعلى كثيرًا من الغازات، وهي من خصائصها.","السوائل تنساب فهي من الموائع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.045Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1873, 0, 'التوتر السطحي (ومثله اللزوجة والخاصية الشعرية) من خصائص السوائل الناتجة عن قوى التجاذب بين جسيماتها.', '["","الانتشار السريع صفة الغازات لتباعد جسيماتها.","قابلية الانضغاط الكبيرة صفة الغازات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.045Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1874, 2, 'العينة (ج) حجمها ثابت لكنها تأخذ شكل الإناء، وتنساب، ولا تنضغط إلا قليلًا جدًا؛ وهذه خصائص السائل.', '["العينة (أ) شكلها وحجمها ثابتان ولا تنساب، فهي صلبة.","العينة (ب) قابلة للانضغاط بدرجة كبيرة وتملأ الإناء كله، فهي غاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1875, 1, 'للسائل حجم ثابت فيبقى 250 mL، لكنه يأخذ شكل الإناء الجديد (الدورق المخروطي).', '["هذا عكس سلوك السائل.","","حجم السائل ثابت لا يتغير بتغير الإناء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1876, 1, 'جسيمات السائل متقاربة فكثافته أعلى كثيرًا من الغاز؛ أما الانسياب وأخذ شكل الإناء فخاصيتان مشتركتان بين السوائل والغازات.', '["الانسياب مشترك بين السوائل والغازات.","","أخذ شكل الإناء مشترك بين السوائل والغازات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1877, 2, 'السوائل تنساب فهي موائع، لكن قوى التجاذب الأقوى بين جسيماتها تجعل ميوعتها أقل من الغازات.', '["ثبات الحجم لا يمنع الانسياب؛ فالسوائل من الموائع.","الغازات أكثر ميوعة لضعف قوى التجاذب بين جسيماتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1878, null, null, null, 'من خصائص السوائل: (1) لها حجم ثابت وتأخذ شكل الإناء. (2) كثافتها أعلى كثيرًا من كثافة الغازات. (3) غير قابلة للانضغاط تقريبًا. (4) موائع تنساب، لكن ميوعتها أقل من الغازات. (ويقبل: اللزوجة، التوتر السطحي، الخاصية الشعرية).', '["أربع خصائص صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى","marks":1},{"element":"الخاصية الثانية","marks":1},{"element":"الخاصية الثالثة","marks":1},{"element":"الخاصية الرابعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خصائص صحيحة"},{"level":"3 درجات","description":"ثلاث خصائص صحيحة"},{"level":"2 درجتان","description":"خاصيتان صحيحتان"},{"level":"1 درجة","description":"خاصية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «قابلة للانضغاط بسهولة»","ذكر «ليس لها حجم ثابت»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1879, null, null, null, 'مثال: (1) الحجم الثابت وأخذ شكل الإناء: جسيمات السائل متقاربة تربطها قوى تجاذب تحافظ على المسافات بينها فيبقى الحجم ثابتًا، لكنها غير مثبتة في مواقعها فتنزلق وتأخذ شكل الإناء. (2) ضعف قابلية الانضغاط: جسيمات السائل متقاربة جدًا والفراغات بينها صغيرة، فلا يمكن تقريبها أكثر إلا بضغط هائل. (ويقبل تفسير الكثافة أو الميوعة).', '["خاصية أولى صحيحة مع تفسيرها","خاصية ثانية صحيحة مع تفسيرها"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى وتفسيرها","marks":2},{"element":"الخاصية الثانية وتفسيرها","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"خاصيتان صحيحتان مع تفسير كامل"},{"level":"3 درجات","description":"خاصيتان مع تفسير كامل لواحدة"},{"level":"2 درجتان","description":"خاصيتان دون تفسير أو واحدة مع تفسير"},{"level":"1 درجة","description":"خاصية واحدة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الخاصية بحجم الجسيمات بدل المسافات بينها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:02.046Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1880, null, null, null, 'الحجم: السائل حجمه ثابت، والغاز يملأ الإناء كله. الكثافة: السائل أعلى كثافة كثيرًا، والغاز منخفض الكثافة. قابلية الانضغاط: السائل غير قابل للانضغاط تقريبًا، والغاز قابل للانضغاط بدرجة كبيرة. الميوعة: كلاهما مائع، لكن الغاز أكثر ميوعة من السائل.', '["الحجم","الكثافة","الانضغاط","الميوعة"]'::jsonb, '[]'::jsonb, '[{"element":"الحجم","marks":1},{"element":"الكثافة","marks":1},{"element":"الانضغاط","marks":1},{"element":"الميوعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الأوجه الأربعة"},{"level":"3 درجات","description":"ثلاثة أوجه صحيحة"},{"level":"2 درجتان","description":"وجهان صحيحان"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الغاز ليس من الموائع","القول إن السائل أكثر ميوعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.047Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1881, 2, 'متوسط الطاقة الحركية لجسيمات السائل يعتمد على درجة الحرارة؛ فكلما ارتفعت زادت الطاقة الحركية.', '["حجم الإناء لا يغير الطاقة الحركية للجسيمات.","شكل الإناء يحدد شكل السائل لا طاقة جسيماته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1882, 1, 'ارتفاع درجة الحرارة يزيد متوسط الطاقة الحركية لجسيمات السائل فتتحرك أسرع.', '["الطاقة الحركية تقل بانخفاض درجة الحرارة لا بارتفاعها.","","الطاقة الحركية تعتمد على درجة الحرارة فلا بد أن تتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1883, 0, 'أعلى درجة حرارة في العينة (أ) (80 °C)، فمتوسط الطاقة الحركية لجسيماتها أكبر وحركتها أسرع، ولا يؤثر حجم العينة في ذلك.', '["","العينة (ب) أكبر حجمًا، لكن الحجم لا يحدد متوسط الطاقة الحركية.","العينة (ج) أبرد العينات فجسيماتها أبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.049Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1884, 1, 'العينتان عند درجة الحرارة نفسها، ومتوسط الطاقة الحركية يعتمد على درجة الحرارة لا على شكل الإناء، فهو متساوٍ.', '["اتساع الإناء لا يزيد الطاقة الحركية للجسيمات.","","ضيق الإناء لا يزيد الطاقة الحركية للجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1885, 0, 'قوى التجاذب بين جسيمات السائل المتقاربة تحد من حركتها، فلا تتحرك بحرية كجسيمات الغاز.', '["","عند درجة الحرارة نفسها يكون متوسط الطاقة الحركية متقاربًا؛ والفرق في قوى التجاذب.","حجم الجسيمات للمادة نفسها لا يتغير بتغير الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1886, 1, 'انخفاض درجة الحرارة يقلل متوسط الطاقة الحركية للجسيمات فتتحرك أبطأ.', '["التبريد يقلل الطاقة الحركية لا يزيدها.","","الطاقة الحركية تتغير بتغير درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1887, 2, 'متوسط الطاقة الحركية يزداد بارتفاع درجة الحرارة، فالعلاقة طردية ويمثلها خط صاعد.', '["الخط الأفقي يعني عدم تأثر الطاقة بدرجة الحرارة.","الخط الهابط يعني أن الطاقة تقل بارتفاع درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.050Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1888, null, null, null, 'العامل هو درجة الحرارة. كلما ارتفعت درجة حرارة السائل زاد متوسط الطاقة الحركية لجسيماته فتتحرك أسرع، وكلما انخفضت قلت الطاقة الحركية فتتحرك أبطأ (علاقة طردية).', '["العامل: درجة الحرارة","العلاقة طردية","الأثر في سرعة الجسيمات"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العامل","marks":1},{"element":"نوع العلاقة","marks":1},{"element":"الأثر في الحركة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد العامل وبيان العلاقة وأثرها"},{"level":"2 درجتان","description":"تحديد العامل والعلاقة دون أثرها"},{"level":"1 درجة","description":"تحديد العامل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الضغط أو حجم الإناء عاملًا","عكس العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.051Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1889, null, null, null, 'ينتشر الحبر أسرع في الماء الساخن؛ لأن درجة حرارته أعلى فيكون متوسط الطاقة الحركية لجزيئاته أكبر وحركتها أسرع، فتصطدم بجسيمات الحبر وتوزعها في الماء بسرعة أكبر من الماء البارد الذي تكون جزيئاته أبطأ.', '["الماء الساخن","الطاقة الحركية أكبر بارتفاع الحرارة","حركة أسرع تنشر الحبر أسرع"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة الصحيحة","marks":1},{"element":"ربط الحرارة بالطاقة الحركية","marks":1},{"element":"ربط الحركة بالانتشار","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة وتفسير كاملان"},{"level":"2 درجتان","description":"إجابة صحيحة مع تفسير ناقص"},{"level":"1 درجة","description":"إجابة صحيحة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الماء البارد","التفسير بأن الماء الساخن أقل كثافة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.051Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1890, null, null, null, 'العبارة خاطئة؛ فمتوسط الطاقة الحركية لجسيمات السائل يعتمد على درجة الحرارة فقط لا على كمية السائل أو حجم الإناء. وبما أن درجتي الحرارة متساويتان فمتوسط الطاقة الحركية لجسيمات الماءين متساوٍ. (أما الطاقة الكلية فتختلف بحسب الكمية، لكن السؤال عن طاقة الجسيمات).', '["الحكم بالخطأ","الطاقة الحركية تعتمد على درجة الحرارة","تساوي الحرارة يعني تساوي متوسط الطاقة الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بدرجة الحرارة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم وتعليل واستنتاج صحيح"},{"level":"2 درجتان","description":"حكم صحيح مع تعليل دون استنتاج"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة","الخلط بين متوسط طاقة الجسيم والطاقة الكلية للعينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.051Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1891, 1, 'جسيمات السائل متقاربة جدًا بسبب قوى التجاذب، فيوجد عدد أكبر من الجسيمات (كتلة أكبر) في وحدة الحجم، بينما معظم حجم الغاز فراغ.', '["حجم الجزيء الواحد لا يتغير بتغير الحالة؛ الفرق في المسافات بينها.","","السرعة لا تحدد الكثافة، وجسيمات الغاز أكثر حرية لا أبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:02.053Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1892, 0, 'قوى التجاذب بين جسيمات السائل تبقيها متقاربة، أما في الغاز فهي ضعيفة جدًا فتتباعد الجسيمات.', '["","كتلة الجزيء لا تتغير بين السائل والغاز للمادة نفسها.","ارتفاع درجة الحرارة يزيد الحركة ويبعد الجسيمات لا يقربها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1893, 1, 'النسبة = 0.96 ÷ 0.00059 ≈ 1.6×10³، أي أن الماء السائل أكثف من بخاره بنحو 1600 مرة.', '["هذا ناتج القسمة المعكوسة (0.00059 ÷ 0.96 ≈ 6.1×10⁻⁴) وهي لا تعبر عن كم مرة يزيد السائل.","","هذه قيمة كثافة السائل نفسها لا النسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:02.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1894, 1, 'بالتكثف تتقارب الجسيمات فيقل الحجم كثيرًا مع ثبات الكتلة، فتزداد الكثافة (الكثافة = الكتلة ÷ الحجم).', '["الجسيمات تتقارب عند التكثف لا تتباعد.","","الكتلة ثابتة لكن الحجم يقل كثيرًا فتزداد الكثافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1895, 2, 'جسيمات الغاز متباعدة ومعظم حجمه فراغ، بينما جسيمات السائل متقاربة، فيكون في الحجم نفسه من السائل كتلة أكبر بكثير.', '["هذا عكس الواقع.","الجسيمات لا تتمدد؛ والفرق في المسافات بينها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.054Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1896, 0, 'جزيء الماء هو نفسه في الحالتين (18 g/mol)، فالكتلة الأكبر في اللتر تعني عددًا أكبر كثيرًا من الجزيئات في وحدة الحجم لتقاربها.', '["","كتلة الجزيء ثابتة في الحالات الثلاث.","الماء والبخار المادة نفسها (H2O)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1897, 2, 'البخار أقلها كثافة لتباعد جسيماته، والجليد أقل كثافة من الماء السائل (ولذلك يطفو عليه)، فالترتيب: البخار < الجليد < الماء السائل.', '["البخار هو الأقل كثافة لا الأعلى.","الجليد أقل كثافة من الماء السائل استثناءً، ولذلك يطفو.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1898, null, null, null, 'لأن جسيمات السائل متقاربة جدًا بسبب قوى التجاذب بينها، فيوجد عدد كبير من الجسيمات (كتلة كبيرة) في وحدة الحجم، بينما جسيمات الغاز متباعدة جدًا وقوى التجاذب بينها ضعيفة جدًا ومعظم حجم الغاز فراغ، فتكون الكتلة في وحدة الحجم صغيرة. وبما أن الكثافة = الكتلة ÷ الحجم، تكون كثافة السائل أعلى.', '["تقارب جسيمات السائل بفعل قوى التجاذب","تباعد جسيمات الغاز","كتلة أكبر في وحدة الحجم"]'::jsonb, '[]'::jsonb, '[{"element":"حالة السائل","marks":1},{"element":"حالة الغاز","marks":1},{"element":"الربط بالكثافة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل"},{"level":"2 درجتان","description":"تفسير لحالة السائل مع الربط بالكثافة دون الغاز"},{"level":"1 درجة","description":"ذكر أن جسيمات السائل متقاربة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بكبر حجم جزيئات السائل","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.055Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1899, null, null, null, '(أ) النسبة = 0.96 ÷ 0.00059 ≈ 1.6×10³ مرة (نحو 1600 مرة). (ب) جزيئات الماء هي نفسها في الحالتين، لكنها في السائل متقاربة بفعل الروابط الهيدروجينية فيوجد عدد كبير منها في كل cm³، أما في البخار فمتباعدة جدًا ومعظم الحجم فراغ، فتكون الكتلة في كل cm³ أقل بنحو 1600 مرة.', '["إعداد القسمة الصحيحة","الناتج ≈ 1.6×10³","التفسير بتقارب الجزيئات في السائل","تباعدها في البخار"]'::jsonb, '["النسبة = كثافة السائل ÷ كثافة البخار","= 0.96 ÷ 0.00059","≈ 1627 ≈ 1.6×10³ (رقمان معنويان)"]'::jsonb, '[{"element":"القسمة الصحيحة","marks":1},{"element":"الناتج بالأرقام المعنوية المناسبة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح وتفسير كامل"},{"level":"3 درجات","description":"حساب صحيح وتفسير ناقص"},{"level":"2 درجتان","description":"حساب صحيح دون تفسير أو تفسير دون حساب"},{"level":"1 درجة","description":"إعداد القسمة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة كثافة البخار على كثافة السائل","خطأ في نقل الفاصلة العشرية في 0.00059","تفسير الفرق بتغير حجم الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:02.056Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1900, null, null, null, 'التصميم: نزن بالونًا أو قارورة فارغة مغلقة مملوءة بالهواء (حجم معلوم مثل 500 mL)، ثم نملأ القارورة نفسها بـ 500 mL من الماء ونزنها، ونطرح كتلة القارورة في كل حالة. التوقع: كتلة الماء (نحو 500 g) أكبر بكثير من كتلة الهواء (أقل من 1 g). التفسير: جسيمات السائل متقاربة بفعل قوى التجاذب فيوجد عدد كبير منها في الحجم نفسه، أما جسيمات الغاز فمتباعدة ومعظم الحجم فراغ، فكثافة السائل أعلى.', '["خطوات تجربة صحيحة مع ثبات الحجم","قياس الكتلة وطرح كتلة الوعاء","التوقع الصحيح","التفسير بالنموذج الجزيئي"]'::jsonb, '[]'::jsonb, '[{"element":"تصميم التجربة وضبط المتغيرات","marks":2},{"element":"التوقع","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم سليم وتوقع وتفسير صحيحان"},{"level":"3 درجات","description":"تصميم سليم وتوقع صحيح وتفسير ناقص"},{"level":"2 درجتان","description":"تصميم ناقص مع توقع صحيح"},{"level":"1 درجة","description":"توقع صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تثبيت الحجم بين العينتين","إهمال كتلة الوعاء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.056Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1901, 0, 'جسيمات السائل متقاربة جدًا ولا يوجد بينها إلا فراغات صغيرة، فلا يمكن تقريبها أكثر إلا بضغط كبير جدًا.', '["","جسيمات السائل في حركة مستمرة.","هذا وصف الغاز، والغاز قابل للانضغاط بسهولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.058Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1902, 2, 'السوائل غير قابلة للانضغاط تقريبًا؛ فهي تنضغط بمقدار ضئيل جدًا عند تعريضها لضغط كبير جدًا، لا أنها لا تنضغط إطلاقًا.', '["هذا تعميم غير دقيق؛ الانضغاط ضئيل لكنه ليس صفرًا.","انضغاط الغازات أكبر بكثير لتباعد جسيماتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.058Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1903, 1, 'جسيمات الهواء متباعدة ومعظم حجمه فراغ فينضغط بسهولة، أما جسيمات الماء فمتقاربة والفراغات بينها صغيرة جدًا فلا يكاد ينضغط.', '["هذا عكس الملاحظة.","","الفراغات بين جسيمات الغاز أكبر بكثير فلا يتساوى الانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:02.058Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1904, 1, 'لأن السائل لا يكاد ينضغط، فإن الضغط المؤثر في طرف ينتقل عبره إلى الطرف الآخر دون أن يُستهلك في تقليص حجمه.', '["السوائل ضعيفة الانضغاط؛ ولو كانت تنضغط بسهولة لضاع الضغط في تقليل حجمها.","","كثافة السوائل مرتفعة مقارنة بالغازات، والخاصية المطلوبة هنا عدم الانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1905, 2, 'الهواء غاز معظم حجمه فراغ فيقل حجمه كثيرًا بالضغط، أما الماء فجسيماته متقاربة والفراغات بينها صغيرة جدًا فلا يكاد حجمه يتغير.', '["الفرق سببه المسافات بين الجسيمات لا حجمها.","قوى التجاذب في السائل أقوى لا أضعف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1906, 0, 'جسيمات المادة الصلبة متراصة بشدة في مواقع ثابتة فهي غير قابلة للانضغاط (عمليًا).', '["","جسيمات الصلب متراصة فلا تنضغط بسهولة.","الغازات أكثر المواد قابلية للانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1907, 2, 'الصلب أقلها انضغاطًا لتراص جسيماته، يليه السائل (انضغاط ضئيل جدًا)، والغاز أكثرها انضغاطًا لتباعد جسيماته.', '["هذا الترتيب معكوس.","السائل أكثر قليلًا قابلية للانضغاط من الصلب لا أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.059Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1908, null, null, null, 'لأن جسيمات السائل متقاربة جدًا بفعل قوى التجاذب، والفراغات بينها صغيرة جدًا، فلا يمكن تقريبها أكثر إلا بضغط كبير جدًا يغير الحجم بمقدار ضئيل. أما جسيمات الغاز فمتباعدة ومعظم حجمه فراغ، فيمكن تقريبها بسهولة بزيادة الضغط فيقل حجمه كثيرًا.', '["تقارب جسيمات السائل وصغر الفراغات","الحاجة إلى ضغط كبير جدًا لتغيير ضئيل","تباعد جسيمات الغاز"]'::jsonb, '[]'::jsonb, '[{"element":"حالة السائل","marks":2},{"element":"المقارنة بالغاز","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل مع المقارنة"},{"level":"2 درجتان","description":"تفسير حالة السائل دون مقارنة"},{"level":"1 درجة","description":"ذكر أن جسيمات السائل متقاربة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن جسيمات السائل لا تتحرك","القول إن السوائل لا تنضغط إطلاقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.060Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1909, null, null, null, 'الملاحظة: يتحرك مكبس محقنة الهواء بسهولة ويقل حجم الهواء كثيرًا، بينما لا يكاد مكبس محقنة الماء يتحرك. التفسير: جسيمات الهواء متباعدة ومعظم حجمه فراغ فتتقارب بسهولة، أما جسيمات الماء فمتقاربة والفراغات بينها صغيرة جدًا فلا يكاد حجمه يقل. التطبيق: المكابح الهيدروليكية أو الرافعات الهيدروليكية التي تنقل الضغط عبر سائل لا يكاد ينضغط.', '["المقارنة بين النتيجتين","التفسير الجزيئي","تطبيق حياتي صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة","marks":1},{"element":"التفسير","marks":2},{"element":"التطبيق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة وتفسير وتطبيق صحيح"},{"level":"3 درجات","description":"مقارنة وتفسير دون تطبيق"},{"level":"2 درجتان","description":"مقارنة مع تطبيق دون تفسير"},{"level":"1 درجة","description":"مقارنة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس النتيجتين","ذكر تطبيق لا يعتمد على عدم الانضغاط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:02.060Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1910, null, null, null, 'العبارة غير دقيقة؛ فالسوائل تنضغط فعلًا لكن بمقدار ضئيل جدًا، ولا يحدث ذلك إلا تحت ضغط كبير جدًا (مثلًا يحتاج تقليل حجم الماء بنحو 1٪ إلى ضغط هائل)، لأن الفراغات بين جسيماتها صغيرة جدًا. الصياغة الأدق: «السوائل غير قابلة للانضغاط تقريبًا» أو «قابلية السوائل للانضغاط ضعيفة جدًا».', '["الحكم بعدم الدقة","بيان أن الانضغاط ضئيل تحت ضغط كبير","الصياغة الأدق"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل","marks":2},{"element":"الصياغة الأدق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم وتعليل وصياغة أدق"},{"level":"2 درجتان","description":"حكم وصياغة دون تعليل"},{"level":"1 درجة","description":"حكم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي","القول إن السوائل تنضغط بسهولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.060Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
