(1915, 0, 'الغاز الطبيعي (غاز) والنفط (سائل) كلاهما من الموائع القادرة على الانسياب، فيمكن ضخهما عبر الأنابيب.', '["","الغاز الطبيعي قابل للانضغاط.","الموائع تأخذ شكل الإناء ولا شكل ثابت لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:02.063Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1916, 1, 'المادتان (ب) و(ج) تنسابان وتأخذان شكل الإناء، فهما من الموائع (سائل وغاز)، أما (أ) فشكلها ثابت ولا تنساب فهي صلبة.', '["(أ) لا تنساب لثبات مواقع جسيماتها فليست مائعًا.","","(أ) مادة صلبة لا تنساب، فلا تُضم إلى الموائع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.063Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1917, 2, 'الهواء غاز، وجسيمات الغاز تنساب وتغير مواقعها بحرية، وانسيابه يظهر في حركة الرياح، فهو من الموائع.', '["الغازات أيضًا من الموائع.","قابلية الانضغاط لا تنفي الميوعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.063Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1918, null, null, null, 'الموائع هي المواد القادرة على الانسياب. جسيمات الغازات والسوائل غير مثبتة في مواقعها، فتستطيع تغيير مواقعها والتحرك بعضها فوق بعض، فتنساب وتأخذ شكل الإناء، فتُصنف موائع. أما جسيمات المادة الصلبة فمثبتة في مواقعها بقوى تجاذب قوية جدًا ولا تستطيع إلا الاهتزاز، فلا تنساب، فلا تُصنف من الموائع.', '["تعريف الموائع","جسيمات الغاز والسائل تغير مواقعها","جسيمات الصلب ثابتة المواقع"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الموائع","marks":1},{"element":"تفسير الغاز والسائل","marks":1},{"element":"تفسير الصلب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل للحالات الثلاث"},{"level":"2 درجتان","description":"تفسير الغاز والسائل دون الصلب"},{"level":"1 درجة","description":"تعريف الموائع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حصر الموائع في السوائل","التفسير بالكثافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1919, null, null, null, 'تطبيق لسائل: نقل الماء إلى المنازل عبر الأنابيب؛ إذ ينساب الماء فيها ويأخذ شكلها. تطبيق لغاز: نقل الغاز الطبيعي في الأنابيب أو توزيع الهواء في أجهزة التكييف؛ إذ ينساب الغاز ويملأ المجاري. (ويقبل: الري، الوقود، المناطيد، الإطارات...).', '["تطبيق صحيح لسائل","تطبيق صحيح لغاز","بيان دور الانسياب"]'::jsonb, '[]'::jsonb, '[{"element":"تطبيق السائل","marks":1},{"element":"تطبيق الغاز","marks":1},{"element":"دور الانسياب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تطبيقان صحيحان مع بيان الدور"},{"level":"2 درجتان","description":"تطبيقان دون بيان الدور"},{"level":"1 درجة","description":"تطبيق واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تطبيقين لسوائل فقط","ذكر تطبيق لمادة صلبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1920, null, null, null, 'لا يُعد الرمل مائعًا؛ فكل حبة رمل مادة صلبة جسيماتها مثبتة في مواقعها بقوى تجاذب قوية، والذي ينساب هو الحبيبات كأجسام صغيرة منفصلة تتدحرج بعضها فوق بعض، لا الجسيمات (الذرات أو الجزيئات) المكونة لها. أما الموائع (السوائل والغازات) فجسيماتها نفسها تغير مواقعها وتنساب.', '["الحكم: الرمل ليس مائعًا","حبة الرمل صلبة جسيماتها ثابتة","الانسياب للحبيبات لا للجسيمات","المقارنة بالموائع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التمييز بين انسياب الحبيبات وانسياب الجسيمات","marks":2},{"element":"ربط ذلك بتعريف الموائع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتمييز كامل مع ربط بالتعريف"},{"level":"3 درجات","description":"حكم صحيح مع تمييز ناقص"},{"level":"2 درجتان","description":"حكم صحيح مع ذكر أن الرمل صلب فقط"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الرمل مائعًا لأنه ينساب","عدم التمييز بين الحبيبات والجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.065Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1921, 0, 'قوى التجاذب الأقوى بين جسيمات السائل المتقاربة تحد من حركتها وتقاوم انسيابها، بينما جسيمات الغاز متباعدة ولا توجد بينها قوى تجاذب تُذكر.', '["","الوزن ليس السبب؛ فالمادة نفسها أقل ميوعة سائلةً منها غازًا مع أن جزيئها واحد.","جسيمات السائل تتحرك وتنزلق، ولذلك يُعد مائعًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.068Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
