(1928, null, null, null, 'لأن جسيمات السائل متقاربة وقوى التجاذب بينها أقوى، فتحد هذه القوى من حركة الجسيمات وتقاوم انسيابها، بينما جسيمات الغاز متباعدة ولا توجد بينها قوى تجاذب تُذكر، فتتحرك بحرية وتنساب بسهولة.', '["قوى التجاذب أقوى في السائل","تحد من حركة الجسيمات","جسيمات الغاز متباعدة وقواها ضعيفة جدًا"]'::jsonb, '[]'::jsonb, '[{"element":"حالة السائل","marks":2},{"element":"المقارنة بالغاز","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل مع مقارنة"},{"level":"2 درجتان","description":"تفسير السائل دون مقارنة"},{"level":"1 درجة","description":"ذكر قوى التجاذب دون ربطها بالانسياب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بثقل جسيمات السائل","القول إن السوائل ليست موائع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.069Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1929, null, null, null, 'السوائل: المسافات صغيرة، قوى التجاذب أقوى، الميوعة أقل. الغازات: المسافات كبيرة، قوى التجاذب تكاد تكون معدومة، الميوعة أعلى. الاستنتاج: كلما زادت قوى التجاذب بين جسيمات المائع قلت ميوعته (علاقة عكسية).', '["المسافات","قوى التجاذب","الميوعة","الاستنتاج"]'::jsonb, '[]'::jsonb, '[{"element":"المسافات","marks":1},{"element":"قوى التجاذب","marks":1},{"element":"الميوعة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الأوجه الثلاثة مع استنتاج"},{"level":"3 درجات","description":"مقارنة صحيحة دون استنتاج"},{"level":"2 درجتان","description":"وجهان صحيحان"},{"level":"1 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس العلاقة","القول إن الغاز أقل ميوعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.069Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1930, null, null, null, 'العبارة غير صحيحة في تعليلها؛ فالماء السائل وبخار الماء يتكونان من جزيئات H2O نفسها ذات الكتلة نفسها (18 g/mol)، ومع ذلك فالماء السائل أقل ميوعة من البخار. فالسبب ليس ثقل الجسيمات، بل أن جزيئات السائل متقاربة وقوى التجاذب (الروابط الهيدروجينية) بينها قوية فتقاوم الانسياب، أما جزيئات البخار فمتباعدة وقوى التجاذب بينها ضعيفة جدًا.', '["الحكم بخطأ التعليل","جزيئات الماء وبخاره متماثلة الكتلة","السبب الصحيح: قوى التجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع الاستدلال بالمثال","marks":2},{"element":"التعليل الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مستدل بالمثال مع تعليل صحيح"},{"level":"3 درجات","description":"حكم صحيح مع تعليل صحيح دون المثال"},{"level":"2 درجتان","description":"حكم صحيح مع المثال دون تعليل بديل"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة","الاعتقاد أن جزيء الماء السائل أثقل من جزيء البخار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.070Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
