(1958, null, null, null, 'التوتر السطحي: الطاقة اللازمة لزيادة مساحة سطح السائل بمقدار معين. سببه: الجزيء داخل السائل تجذبه الجزيئات المحيطة به من جميع الاتجاهات بالتساوي فتتوازن القوى عليه، أما الجزيء على السطح فلا توجد فوقه جزيئات سائل، فتجذبه الجزيئات المجاورة والتي تحته فقط، فتكون محصلة القوى عليه نحو الداخل، فيسلك السطح سلوك غشاء مشدود.', '["التعريف","جزيء الداخل: قوى متوازنة","جزيء السطح: محصلة نحو الداخل","السطح كغشاء مشدود"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"جزيء الداخل","marks":1},{"element":"جزيء السطح","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتفسير كامل"},{"level":"3 درجات","description":"تعريف وتفسير ينقصه عنصر"},{"level":"2 درجتان","description":"تعريف مع تفسير جزئي"},{"level":"1 درجة","description":"تعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التوتر السطحي بمقاومة التدفق","القول إن سطح الماء مادة مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.083Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1959, null, null, null, 'المخطط: جزيء الداخل تحيط به أسهم قوى متساوية في كل الاتجاهات (محصلة صفر). جزيء السطح أسهم القوى نحو الجانبين والأسفل فقط (محصلة نحو الداخل). التفسير: سحب جزيئات السطح نحو الداخل يجعل السطح مشدودًا كالغشاء ويقاوم زيادة مساحته، فعندما تقف الحشرة الخفيفة لا تكفي قوة وزنها لاختراق السطح فتبقى عليه.', '["تمثيل جزيء الداخل","تمثيل جزيء السطح","الربط بوقوف الحشرة"]'::jsonb, '[]'::jsonb, '[{"element":"تمثيل الجزيئين","marks":2},{"element":"تفسير وقوف الحشرة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح وتفسير كامل"},{"level":"3 درجات","description":"مخطط صحيح وتفسير ناقص"},{"level":"2 درجتان","description":"مخطط صحيح لجزيء واحد مع تفسير"},{"level":"1 درجة","description":"ذكر التوتر السطحي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوى نحو الأعلى على جزيء السطح","التفسير بأن الحشرة أقل كثافة من الماء فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.083Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1960, null, null, null, 'الاستنتاج: قوى التجاذب بين جزيئات الماء أقوى منها بين جزيئات الإيثانول، لأن التوتر السطحي يزداد بزيادة قوى التجاذب، والتوتر السطحي للماء أكبر بنحو 3.3 مرات (0.073 ÷ 0.022). يحتاج تكبير مساحة سطح الماء إلى طاقة أكبر لأن نقل جزيئات من الداخل إلى السطح يتطلب التغلب على قوى تجاذب أقوى (روابط هيدروجينية كثيرة)، والتوتر السطحي هو مقدار هذه الطاقة لكل وحدة مساحة.', '["قوى التجاذب في الماء أقوى","العلاقة الطردية بين قوى التجاذب والتوتر السطحي","تفسير الحاجة إلى طاقة أكبر"]'::jsonb, '["النسبة = 0.073 ÷ 0.022 ≈ 3.3"]'::jsonb, '[{"element":"الاستنتاج","marks":1},{"element":"ذكر العلاقة الطردية","marks":1},{"element":"تفسير الطاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"استنتاج وتفسير كاملان"},{"level":"2 درجتان","description":"استنتاج صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"استنتاج صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استنتاج أن الإيثانول أقوى تجاذبًا","عدم ربط الطاقة بالتغلب على قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.084Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1961, 1, 'الصابون والمنظفات من المواد الخافضة للتوتر السطحي؛ فهي تقلل التوتر السطحي للماء.', '["ملح الطعام ليس من المواد الخافضة للتوتر السطحي.","","السكر ليس من المواد الخافضة للتوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:02.086Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1962, 0, 'الصابون والمنظفات (مثل سائل الجلي ومسحوق الغسيل) مواد تقلل التوتر السطحي للماء.', '["","الملح والسكر يذوبان في الماء لكنهما لا يُعدان من المواد الخافضة للتوتر السطحي.","الجلسرين والعسل سوائل لزجة لا تُستخدم مواد خافضة للتوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:02.086Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
