(1965, 1, 'انخفض التوتر السطحي للعينة (ب) كثيرًا مقارنة بالماء النقي، وهذا يدل على إضافة مادة خافضة للتوتر السطحي مثل المنظفات.', '["الملح لا يخفض التوتر السطحي للماء بهذا المقدار.","","السكر لا يخفض التوتر السطحي للماء بهذا المقدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.086Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1966, 1, 'المنظف مادة خافضة للتوتر السطحي، فيقل ميل الماء إلى التجمع في قطرات، فينتشر على السطح ويبلله.', '["زيادة التوتر السطحي تجعل الماء يتجمع في قطرات أكثر.","","زيادة اللزوجة لا تجعل الماء ينتشر ويبلل الأسطح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.087Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1967, 2, 'مساحيق الغسيل تحتوي على منظفات، وهي مواد خافضة للتوتر السطحي تساعد الماء على تبليل الألياف.', '["ملح الطعام لا يُستخدم لخفض التوتر السطحي.","السكر لا يُستخدم لخفض التوتر السطحي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.088Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1968, null, null, null, 'مثالان: الصابون، والمنظفات (مثل سائل الجلي أو مسحوق الغسيل). تأثيرها: تضعف الروابط الهيدروجينية بين جزيئات الماء على السطح، فيقل التوتر السطحي للماء.', '["المثال الأول","المثال الثاني","بيان الأثر وآليته"]'::jsonb, '[]'::jsonb, '[{"element":"المثالان","marks":2},{"element":"الأثر وآليته","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"مثالان صحيحان مع بيان الأثر والآلية"},{"level":"2 درجتان","description":"مثالان صحيحان دون الآلية"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الملح أو السكر مثالًا","القول إنها تزيد التوتر السطحي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:02.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1969, null, null, null, 'الأدوات: طبق فيه ماء، وإبرة فولاذية أو مشبك ورق، ومنديل ورقي، وسائل جلي. الخطوات: نضع الإبرة على قطعة منديل ونضعها برفق على سطح الماء حتى يغوص المنديل وتبقى الإبرة طافية بفعل التوتر السطحي، ثم نضيف قطرة من سائل الجلي إلى الماء بعيدًا عن الإبرة. الملاحظة المتوقعة: تغرق الإبرة، لأن سائل الجلي خفض التوتر السطحي فلم يعد السطح قادرًا على حملها.', '["الأدوات","خطوات صحيحة","الملاحظة: غرق الإبرة","التفسير بخفض التوتر السطحي"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات والخطوات","marks":2},{"element":"الملاحظة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تجربة كاملة مع ملاحظة وتفسير صحيحين"},{"level":"3 درجات","description":"تجربة صحيحة مع ملاحظة دون تفسير"},{"level":"2 درجتان","description":"خطوات ناقصة مع ملاحظة صحيحة"},{"level":"1 درجة","description":"فكرة صحيحة دون خطوات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة سائل الجلي قبل وضع الإبرة","توقع بقاء الإبرة طافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
