(1970, null, null, null, 'لأن للماء توترًا سطحيًا عاليًا يجعله يتجمع في قطرات ولا ينتشر بسهولة بين ألياف القماش والأوساخ. والمنظفات من المواد الخافضة للتوتر السطحي؛ تضعف الروابط الهيدروجينية بين جزيئات الماء على السطح فيقل توتره السطحي، فينتشر الماء ويبلل الألياف وينفذ بينها وبين الأوساخ فيسهل إزالتها.', '["التوتر السطحي العالي للماء يمنع انتشاره","المنظف يخفض التوتر السطحي","الماء ينتشر ويبلل الألياف"]'::jsonb, '[]'::jsonb, '[{"element":"مشكلة التوتر السطحي العالي","marks":1},{"element":"دور المنظف","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجتان","description":"تعليل يذكر دور المنظف ونتيجته فقط"},{"level":"1 درجة","description":"ذكر أن المنظف يخفض التوتر السطحي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المنظف يذيب الأوساخ كيميائيًا فقط","القول إنه يزيد التوتر السطحي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.089Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1971, 0, 'جزيئات الماء قطبية وترتبط بروابط هيدروجينية قوية، فتكون قوى التجاذب بين جزيئات السطح والداخل كبيرة، فيرتفع التوتر السطحي.', '["","هذا اعتقاد خاطئ؛ التوتر السطحي يعتمد على قوى التجاذب لا الكثافة.","صغر الكتلة يعني عادة قوى تشتت أضعف، فلا يفسر ارتفاع التوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.091Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1972, 2, 'لجزيء الماء ذرتا H وزوجان غير مرتبطين على O، فيستطيع تكوين حتى أربع روابط هيدروجينية مع الجزيئات المجاورة.', '["جزيء الماء يكوّن أكثر من رابطة لامتلاكه ذرتي H وزوجين غير مرتبطين.","ذرتا H تشكلان رابطتين، والزوجان غير المرتبطين يستقبلان رابطتين أخريين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.092Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1973, 1, 'الماء (0.073 J/m²) يتفوق على الإيثانول (0.022) والهكسان (0.018)؛ لأن روابطه الهيدروجينية أقوى وأكثر عددًا.', '["الهكسان غير القطبي له أقل توتر سطحي في الجدول.","","البيانات تُظهر ارتباطًا واضحًا بين قوة القوى والتوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.092Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1974, 2, 'الزئبق فلز سائل قوى التماسك بين ذراته قوية جدًا، فتوتره السطحي أعلى من الماء؛ لذلك يقال «معظم السوائل».', '["الإيثانول توتره السطحي أقل من الماء.","لون الإناء لا يؤثر في التوتر السطحي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.092Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1975, 0, 'جزيء الداخل محاط بجزيئات من كل الجهات ويكوّن روابط هيدروجينية أكثر، وعند انتقاله إلى السطح يفقد بعضها، ويلزم لذلك طاقة؛ وهذا أصل التوتر السطحي العالي للماء.', '["","كتلة الجزيء لا تتغير بتغير موقعه.","وجود الجزيء على السطح لا يعني تبخره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T11:15:02.092Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1976, 1, 'الهكسان غير قطبي ولا تنشأ بين جزيئاته إلا قوى التشتت، فقوى التجاذب أضعف فيكون توتره السطحي أقل من الماء والجلسرين.', '["الماء يكوّن روابط هيدروجينية كثيرة فتوتره السطحي مرتفع.","","الجلسرين يكوّن روابط هيدروجينية فتوتره السطحي مرتفع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.092Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1977, 1, 'التوتر السطحي العالي يجعل سطح الماء مشدودًا كالغشاء فيرتفع فوق حافة الكوب قليلًا دون أن ينسكب.', '["التبخر يرتبط بالطاقة الحركية ودرجة الحرارة.","","الذوبان ظاهرة مختلفة لا تدل على التوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:02.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1978, null, null, null, 'لأن جزيئات الماء قطبية وترتبط بعضها ببعض بروابط هيدروجينية قوية، ويستطيع كل جزيء ماء أن يكوّن روابط هيدروجينية مع عدة جزيئات مجاورة (حتى أربعة)، فتكون قوى التجاذب التي تسحب جزيئات السطح نحو الداخل كبيرة، ويحتاج تكبير مساحة السطح إلى طاقة كبيرة، أي أن توتره السطحي مرتفع.', '["الروابط الهيدروجينية القوية","كثرة الروابط لكل جزيء","الربط بقوى السحب نحو الداخل والطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"الروابط الهيدروجينية","marks":1},{"element":"كثرتها","marks":1},{"element":"الربط بالتوتر السطحي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل"},{"level":"2 درجتان","description":"تفسير بالروابط الهيدروجينية دون كثرتها"},{"level":"1 درجة","description":"ذكر الروابط الهيدروجينية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التفسير بكثافة الماء","القول إن الماء أعلى توترًا من جميع السوائل بلا استثناء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1979, null, null, null, 'الماء: روابط هيدروجينية قوية وكثيرة، توتر سطحي عالٍ (0.073 J/m²). الهكسان: قوى تشتت فقط (غير قطبي)، توتر سطحي منخفض (0.018 J/m²). التوقع: الماء يتجمع في قطرات أكثر كروية، لأن توتره السطحي الأعلى يسحب جزيئات السطح نحو الداخل بقوة أكبر فيقلل مساحة السطح إلى أقصى حد، أما الهكسان فينتشر أكثر.', '["نوع القوى في كل منهما","مقارنة التوتر السطحي","التوقع الصحيح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"نوع القوى","marks":1},{"element":"التوتر السطحي","marks":1},{"element":"التوقع والتعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة وتوقع وتعليل كامل"},{"level":"3 درجات","description":"مقارنة كاملة وتوقع دون تعليل"},{"level":"2 درجتان","description":"مقارنة جزئية مع توقع صحيح"},{"level":"1 درجة","description":"توقع صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الهكسان قطبيًا","توقع أن الهكسان أكثر كروية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1980, null, null, null, 'الخطأ: التوتر السطحي لا يعتمد على ثقل السائل أو كثافته، بل على قوى التجاذب بين جزيئاته؛ فالماء ليس ثقيلًا مقارنة بسوائل أكثف منه توترها السطحي أقل. التصحيح: التوتر السطحي للماء عالٍ لأن جزيئاته ترتبط بروابط هيدروجينية قوية وكثيرة تسحب جزيئات السطح نحو الداخل.', '["تحديد الخطأ","العامل الصحيح: قوى التجاذب","العبارة المصححة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"التصحيح بالروابط الهيدروجينية","marks":2}]'::jsonb, '[{"level":"3 درجات","description":"تحديد الخطأ وتصحيح كامل"},{"level":"2 درجتان","description":"تحديد الخطأ وتصحيح ناقص"},{"level":"1 درجة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التصحيح بكثافة الماء","التصحيح بقوى التشتت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.093Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1981, 1, 'التوتر السطحي يسحب جزيئات السطح نحو الداخل فيميل السائل إلى أصغر مساحة سطح ممكنة، والكرة هي الشكل ذو أقل مساحة سطح لحجم معين.', '["الجاذبية تفلطح القطرات الكبيرة ولا تجعلها كروية.","","لزوجة الماء منخفضة، واللزوجة لا تحدد شكل القطرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.095Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
