(2025, 2, 'عندما يكون التلاصق أكبر من التماسك ينجذب الماء إلى سطح الزجاج أكثر من انجذاب جزيئاته بعضها لبعض فيبلل السطح.', '["لو كان التماسك أكبر لبقيت القطرة متكوّرة ولم تبلل السطح.","انتشار الماء على الزجاج دليل على وجود تجاذب قوي بينهما لا انعدامه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.114Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2026, 1, 'التماسك تجاذب بين جسيمات المادة نفسها (متشابهة)، والتلاصق تجاذب بين جسيمات مواد مختلفة.', '["كلاهما يمكن أن يحدث في السوائل؛ فالماء مثلًا له تماسك بين جزيئاته وتلاصق مع الزجاج.","","كلا النوعين قوى تجاذب لا يميز بينهما مقدار درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.115Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2027, 0, 'تجمع الماء في قطرات وعدم بلله للسطح يعني أن جزيئاته تنجذب بعضها إلى بعض (التماسك) أكثر من انجذابها إلى الشمع (التلاصق).', '["","تكوّر القطرات دليل على قوة التماسك بين جزيئات الماء لا انعدامه.","لو كان التلاصق أكبر لانتشر الماء على الورقة وبللها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.115Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2028, null, null, null, 'التلاصق: قوى التجاذب بين جسيمات مواد مختلفة. مثاله: التجاذب بين جزيئات الماء وجزيئات الزجاج. الفرق: التماسك تجاذب بين جسيمات المادة نفسها (مثل تجاذب جزيئات الماء بعضها مع بعض)، أما التلاصق فبين جسيمات مادتين مختلفتين.', '["تعريف التلاصق بأنه تجاذب بين جسيمات مواد مختلفة","مثال صحيح (الماء والزجاج)","تعريف التماسك أو وصفه","إبراز معيار الفرق: تشابه الجسيمات أو اختلافها"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"الفرق بين المفهومين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومثال صحيح وفرق واضح"},{"level":"3 درجات","description":"تعريف ومثال صحيحان مع فرق ناقص"},{"level":"1–2 درجة","description":"تعريف فقط أو مثال فقط"},{"level":"صفر","description":"خلط بين التلاصق والتماسك أو لا إجابة"}]'::jsonb, '["تبديل تعريفي التماسك والتلاصق","ذكر مثال على التماسك بدل التلاصق (كتجاذب جزيئات الماء معًا)","تعريف التلاصق بالتوتر السطحي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.115Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2029, null, null, null, 'في الماء: قوى التلاصق بين جزيئات الماء والزجاج أكبر من قوى التماسك بين جزيئات الماء، فينجذب الماء إلى الزجاج وينتشر عليه ويبلله. في الزئبق: قوى التماسك بين ذرات الزئبق أكبر من قوى تلاصقه بالزجاج، فتنجذب ذراته بعضها إلى بعض وتتكور ولا تبلل الزجاج.', '["الماء: التلاصق أكبر من التماسك","نتيجة ذلك: البلل والانتشار","الزئبق: التماسك أكبر من التلاصق","نتيجة ذلك: التكور وعدم البلل"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير سلوك الماء","marks":2},{"element":"تفسير سلوك الزئبق","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير السائلين بمقارنة صحيحة للقوتين"},{"level":"3 درجات","description":"تفسير صحيح لسائل وناقص للآخر"},{"level":"1–2 درجة","description":"ذكر المفهومين دون مقارنة صحيحة"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["عكس المقارنة بين التلاصق والتماسك","تفسير عدم بلل الزئبق بكثافته العالية","الاكتفاء بالوصف دون ذكر القوى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.115Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2030, null, null, null, '(أ) تلاصق؛ لأنه تجاذب بين جزيئات الماء وجزيئات الزجاج (مادتين مختلفتين). (ب) تلاصق؛ لأنه تجاذب بين جسيمات الطلاء وجسيمات الجدار (مادتين مختلفتين). (ج) تماسك؛ لأنه تجاذب بين جزيئات الماء بعضها مع بعض (مادة واحدة).', '["(أ) تلاصق مع التعليل","(ب) تلاصق مع التعليل","(ج) تماسك مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف المواقف الثلاثة مع تعليل صحيح لكل منها"},{"level":"4–5 درجات","description":"تصنيف صحيح مع نقص في تعليل واحد أو خطأ في موقف"},{"level":"2–3 درجات","description":"تصنيف صحيح دون تعليل أو موقف واحد كامل"},{"level":"صفر","description":"تصنيفات خاطئة أو لا إجابة"}]'::jsonb, '["عدّ اندماج القطرات تلاصقًا لأنها تلتقي","عدّ التصاق الماء بالزجاج تماسكًا","التصنيف دون ذكر نوع الجسيمات المتجاذبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.116Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2031, 0, 'يرتفع الماء لأن قوى التلاصق بين جزيئاته وجزيئات الزجاج أكبر من قوى التماسك بين جزيئات الماء نفسها.', '["","إذا كان التماسك أكبر ينخفض السائل في الأنبوب كما يحدث للزئبق.","مفهوم شائع خاطئ؛ فالارتفاع ناتج عن قوى التجاذب لا عن فرق ضغط الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2032, 1, 'تنجذب الجزيئات الملاصقة للجدار إلى أعلى بقوى التلاصق، وتسحب معها الجزيئات المجاورة بقوى التماسك، فيرتفع عمود الماء كله.', '["الالتصاق بالجدار يحدث بقوى التلاصق، والتماسك لا يمنعه بل يكمل عمله.","","التماسك تجاذب بين جزيئات الماء ولا يدفعها بعيدًا عن الجدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2033, 1, 'كلما ضاق الأنبوب زاد ارتفاع الماء فيه؛ لأن نسبة الماء الملامس للجدار إلى وزن العمود تكون أكبر، وأضيق أنبوب هو (ب).', '["هذا أوسع الأنابيب فيكون ارتفاع الماء فيه أقل.","","قطره متوسط فيكون ارتفاع الماء فيه أقل من الأنبوب (ب)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2034, 1, 'يستمر الماء في الارتفاع حتى يتوازن وزن العمود المرتفع مع قوى التجاذب التي ترفعه.', '["قوى التلاصق لا تختفي، بل يصبح وزن العمود مساويًا لها.","","الماء يستقر فوق مستوى الحوض لا عنده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.118Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2035, 2, 'في الزئبق قوى التماسك أكبر من قوى التلاصق بالزجاج، فلا ينجذب إلى الجدار بل ينخفض داخل الأنبوب، وهذا يبين أن السوائل لا ترتفع جميعها في الأنابيب الشعرية.', '["لو كان التلاصق أكبر لارتفع الزئبق كما يرتفع الماء.","الزئبق أعلى كثافة من الماء بكثير، والانخفاض يفسَّر بمقارنة القوى لا بالكثافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2036, 0, 'ارتفاع الماء ناتج عن كون قوى التلاصق بين الماء والزجاج أكبر من قوى التماسك بين جزيئات الماء، لا عن دفع الهواء.', '["","هذا مفهوم شائع خاطئ؛ فالارتفاع يحدث لأن الماء ينجذب إلى جدار الزجاج.","تفوق التماسك يؤدي إلى انخفاض السائل في الأنبوب لا ارتفاعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2037, 2, 'لأن التلاصق أكبر من التماسك تنجذب جزيئات الماء الملامسة للجدار إلى أعلى، فيصبح السطح مقعرًا.', '["التحدب يحدث للزئبق الذي يكون تماسكه أكبر من تلاصقه بالزجاج.","القوى غير متساوية؛ فالتلاصق بالزجاج أكبر من التماسك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2038, null, null, null, '1) قوى التلاصق بين جزيئات الماء وجزيئات الزجاج أكبر من قوى التماسك بين جزيئات الماء. 2) لذلك تنجذب جزيئات الماء الملامسة للجدار إلى أعلى. 3) تسحب هذه الجزيئات معها الجزيئات المجاورة بقوى التماسك فيرتفع عمود الماء. 4) يتوقف الارتفاع عندما يتوازن وزن عمود الماء مع قوى التجاذب الرافعة.', '["مقارنة التلاصق بالتماسك (التلاصق أكبر)","انجذاب الجزيئات الملاصقة للجدار إلى أعلى","دور التماسك في سحب بقية الجزيئات","التوقف عند توازن وزن العمود مع قوى التجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"سبب الارتفاع (مقارنة القوتين)","marks":2},{"element":"دور التماسك","marks":1},{"element":"شرط التوقف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متسلسل كامل مع شرط التوقف"},{"level":"3 درجات","description":"تفسير صحيح دون شرط التوقف أو دون دور التماسك"},{"level":"1–2 درجة","description":"ذكر التلاصق فقط دون مقارنة"},{"level":"صفر","description":"تفسير بضغط الهواء أو لا إجابة"}]'::jsonb, '["تفسير الارتفاع بضغط الهواء","عكس المقارنة بين التلاصق والتماسك","إغفال شرط توقف الارتفاع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.119Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2039, null, null, null, 'الماء: يرتفع داخل الأنبوب فوق مستواه في الحوض، وسطحه مقعر، والسبب أن قوى التلاصق بالزجاج أكبر من قوى التماسك بين جزيئاته. الزئبق: ينخفض داخل الأنبوب تحت مستواه في الحوض، وسطحه محدب، والسبب أن قوى التماسك بين ذراته أكبر من قوى تلاصقه بالزجاج.', '["الماء يرتفع والزئبق ينخفض","الماء مقعر والزئبق محدب","سبب سلوك الماء","سبب سلوك الزئبق"]'::jsonb, '[]'::jsonb, '[{"element":"المستوى","marks":1},{"element":"شكل السطح","marks":1},{"element":"السبب للماء","marks":1},{"element":"السبب للزئبق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة في المعايير الثلاثة"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"1–2 درجة","description":"وصف السلوك دون أسباب"},{"level":"صفر","description":"مقارنة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن جميع السوائل ترتفع في الأنابيب الشعرية","تبديل شكلي السطحين","تفسير انخفاض الزئبق بكثافته فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.120Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2040, null, null, null, '(أ) علاقة عكسية: كلما ضاق الأنبوب زاد الارتفاع؛ فعند مضاعفة القطر يقل الارتفاع إلى النصف تقريبًا (حاصل ضرب القطر في الارتفاع ثابت تقريبًا ≈ 3.0 cm·mm). (ب) h ≈ 3.0 ÷ 4.0 ≈ 0.75 cm (نحو 0.7–0.8 cm). (ج) لأن قطر الكأس كبير جدًا، فيكون وزن الماء كبيرًا مقارنة بقوى التلاصق مع الجدار، فلا يرتفع إلا ارتفاعًا ضئيلًا عند الحواف.', '["العلاقة عكسية","الاستدلال من البيانات (مضاعفة القطر تنصف الارتفاع)","التوقع ≈ 0.75 cm","تفسير غياب الارتفاع في الأوعية الواسعة"]'::jsonb, '["d × h ≈ 0.5 × 5.9 ≈ 1.0 × 3.0 ≈ 2.0 × 1.5 ≈ 3.0 cm·mm","h(4.0 mm) ≈ 3.0 ÷ 4.0 ≈ 0.75 cm"]'::jsonb, '[{"element":"(أ) العلاقة مع الدليل","marks":2},{"element":"(ب) التوقع","marks":2},{"element":"(ج) التفسير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"علاقة صحيحة بدليل وتوقع منطقي وتفسير سليم"},{"level":"4–5 درجات","description":"خطأ بسيط في التوقع أو نقص في التفسير"},{"level":"2–3 درجات","description":"وصف العلاقة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["وصف العلاقة بأنها طردية","توقع ارتفاع أكبر من 1.5 cm للأنبوب الأوسع","تفسير غياب الارتفاع في الكأس بأن الماء لا يتلاصق مع الزجاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.120Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2041, 0, 'الخاصية الشعرية هي حركة السائل (ارتفاعه) داخل الأنابيب الرفيعة جدًا (الشعرية).', '["","هذا تعريف اللزوجة.","هذا تعريف التوتر السطحي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2042, 2, 'يتحرك الماء خلال الفراغات الدقيقة بين ألياف المنديل، وهذا تطبيق على الخاصية الشعرية.', '["انتشار الرائحة مثال على انتشار الغازات.","طفو الجليد يفسَّر بقلة كثافته لا بالخاصية الشعرية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2043, 2, 'يرتفع السائل في الأنابيب الرفيعة عندما تكون قوى تلاصقه بالجدار أكبر من قوى التماسك بين جزيئاته.', '["عندئذ ينخفض السائل في الأنبوب كما في الزئبق.","تساوي القوتين لا يسبب ارتفاع السائل في الأنبوب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2044, 1, 'صعود الماء في الأوعية الدقيقة جدًا في النبات من تطبيقات الخاصية الشعرية.', '["اللزوجة مقاومة السائل للتدفق.","","التوتر السطحي يتعلق بسطح السائل لا بحركته في الأوعية الدقيقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2045, 2, 'تظهر الخاصية الشعرية في الأنابيب الرفيعة جدًا، وأضيق وعاء في الجدول هو الأنبوب الذي قطره 0.5 mm.', '["قطرها كبير فلا يظهر فيها ارتفاع ملحوظ للماء.","قطره أكبر الأوعية فلا تظهر فيه الخاصية الشعرية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2046, 1, 'الفراغات بين ألياف المنديل تعمل كأنابيب رفيعة جدًا، وتلاصق الماء بالألياف أكبر من تماسكه فيتحرك الماء خلالها.', '["المنديل لا يذيب الماء؛ بل ينتقل الماء خلال الفراغات بين الألياف.","","الامتصاص يحدث فورًا بانتقال السائل لا بالتبخر والتكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.123Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2047, 1, 'كلما ضاق الأنبوب زاد ارتفاع السائل فيه، ولا ترتفع إلا السوائل التي يكون تلاصقها بالجدار أكبر من تماسكها.', '["مفهوم خاطئ؛ فالخاصية الشعرية تظهر بوضوح في الأنابيب الرفيعة فقط.","","الزئبق مثلًا ينخفض في الأنبوب الزجاجي الشعري لأن تماسكه أكبر من تلاصقه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.124Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2048, null, null, null, 'الخاصية الشعرية: حركة السائل (ارتفاعه) داخل الأنابيب الرفيعة جدًا، وتحدث عندما تكون قوى التلاصق بين السائل والجدار أكبر من قوى التماسك بين جزيئاته. من أمثلتها: امتصاص المناديل الورقية للماء، وصعود الماء في سيقان النباتات، وصعود الزيت في فتيل المصباح.', '["تعريف الخاصية الشعرية","الإشارة إلى الأنابيب الرفيعة جدًا","مثال أول صحيح","مثال ثان صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومثالان صحيحان"},{"level":"3 درجات","description":"تعريف صحيح ومثال واحد"},{"level":"1–2 درجة","description":"تعريف ناقص أو مثالان دون تعريف"},{"level":"صفر","description":"خلط بالتوتر السطحي أو اللزوجة أو لا إجابة"}]'::jsonb, '["تعريف الخاصية الشعرية بالتوتر السطحي","ذكر أمثلة لا علاقة لها بالأنابيب الرفيعة (كطفو الجليد)","إغفال شرط ضيق الأنبوب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.124Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2049, null, null, null, 'يتكون المنديل من ألياف بينها فراغات دقيقة جدًا تعمل عمل الأنابيب الشعرية. قوى التلاصق بين جزيئات الماء والألياف أكبر من قوى التماسك بين جزيئات الماء، فتنجذب جزيئات الماء إلى الألياف، وتسحب معها الجزيئات المجاورة بقوى التماسك، فيتحرك الماء خلال الفراغات ويُمتص، وهذا هو الخاصية الشعرية.', '["الفراغات بين الألياف كالأنابيب الشعرية","التلاصق أكبر من التماسك","دور التماسك في سحب بقية الجزيئات","تسمية الظاهرة الخاصية الشعرية"]'::jsonb, '[]'::jsonb, '[{"element":"الفراغات الدقيقة","marks":1},{"element":"مقارنة القوتين","marks":2},{"element":"دور التماسك وتسمية الظاهرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط البنية بالقوى والظاهرة"},{"level":"3 درجات","description":"تفسير صحيح ينقصه عنصر"},{"level":"1–2 درجة","description":"تسمية الظاهرة فقط أو ذكر التلاصق دون مقارنة"},{"level":"صفر","description":"تفسير بالتبخر أو الذوبان أو لا إجابة"}]'::jsonb, '["تفسير الامتصاص بذوبان الماء في الورق","إغفال دور ضيق الفراغات","عكس المقارنة بين القوتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.124Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2050, null, null, null, 'الأدوات: حوض فيه ماء ملوّن بصبغة طعام، وثلاثة أنابيب زجاجية نظيفة مختلفة القطر (مثلًا 0.5 mm و1 mm و2 mm)، ومسطرة. الخطوات: تُغمس الأنابيب رأسيًا في الماء الملون في الوقت نفسه، ثم يُقاس ارتفاع الماء في كل أنبوب فوق مستوى الحوض بعد استقراره. النتيجة المتوقعة: يرتفع الماء في الأنابيب كلها، ويكون الارتفاع أكبر في الأضيق. التفسير: التلاصق بين الماء والزجاج أكبر من التماسك، وفي الأنبوب الأضيق يكون وزن العمود أقل مقارنة بقوى التلاصق مع الجدار فيرتفع الماء أكثر.', '["أدوات مناسبة (أنابيب مختلفة القطر وماء ملون)","خطوات واضحة مع ضبط المتغيرات","النتيجة: ارتفاع أكبر في الأضيق","التفسير بالتلاصق والتماسك"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات والخطوات","marks":2},{"element":"النتيجة المتوقعة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصميم سليم بضبط المتغيرات ونتيجة صحيحة وتفسير كامل"},{"level":"3–4 درجات","description":"تصميم مقبول مع نقص في التفسير أو ضبط المتغيرات"},{"level":"1–2 درجة","description":"ذكر أدوات أو نتيجة دون تصميم واضح"},{"level":"صفر","description":"تصميم لا يقيس الظاهرة أو لا إجابة"}]'::jsonb, '["استخدام أنابيب واسعة لا تظهر فيها الظاهرة","توقع ارتفاع أكبر في الأنبوب الأوسع","تغيير أكثر من متغير في الوقت نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.124Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2051, 2, 'للمادة الصلبة شكل ثابت وحجم ثابت لأن جسيماتها مثبتة في مواقعها بقوى تجاذب قوية جدًا.', '["هذا وصف المادة الغازية التي تملأ الإناء كله.","هذا وصف المادة السائلة التي تأخذ شكل الإناء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.126Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2052, 0, 'جسيمات المادة الصلبة متراصة في مواقع ثابتة ولا تستطيع إلا الاهتزاز في أماكنها.', '["","الحركة العشوائية الحرة في خطوط مستقيمة صفة جسيمات الغاز.","الانزلاق صفة جسيمات السائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.126Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2053, 1, 'المادة (ب) لها شكل ثابت وحجم ثابت وقابليتها للانضغاط ضئيلة جدًا، وهذه خصائص المادة الصلبة.', '["تأخذ شكل الإناء مع ثبات حجمها، فهي سائلة.","","تملأ الإناء وتنضغط بسهولة، فهي غازية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2054, 2, 'قوى التجاذب بين جسيمات المادة الصلبة قوية جدًا، وهي أقوى منها في السوائل والغازات، ولذلك تتراص الجسيمات في مواقع ثابتة.', '["لو كانت أضعف لما احتفظت المادة الصلبة بشكل ثابت.","اختلاف قوى التجاذب هو ما يميز حالات المادة بعضها من بعض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2055, 2, 'الانسياب وأخذ شكل الإناء من خصائص الموائع (السوائل والغازات)، والمواد الصلبة لا تنساب.', '["تراص الجسيمات في مواقع ثابتة من فرضيات المادة الصلبة.","الاحتفاظ بشكل ثابت من أهم خصائص المادة الصلبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2056, 1, 'كثافة معظم المواد في الحالة الصلبة أعلى منها في الحالة السائلة لتراص الجسيمات، مع استثناءات أشهرها الماء.', '["تتغير الكثافة عادة بتغير الحالة لتغير المسافات بين الجسيمات.","","هذا استثناء لبعض المواد كالماء، لا القاعدة العامة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2057, 0, 'المادة الصلبة لها شكل ثابت وحجم ثابت لا يتغيران بتغير الإناء.', '["","التمدد لملء الإناء صفة الغازات.","تغير الشكل مع ثبات الحجم صفة السوائل لا الصلبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2058, null, null, null, 'من خصائص المواد الصلبة: 1) لها شكل ثابت وحجم ثابت. 2) جسيماتها متراصة في مواقع ثابتة وتهتز في أماكنها. 3) قوى التجاذب بين جسيماتها قوية جدًا. 4) كثافتها عالية (أعلى غالبًا من حالتها السائلة). 5) قابليتها للانضغاط ضئيلة جدًا. 6) لا تُعد من الموائع لأنها لا تنساب.', '["الشكل والحجم الثابتان","تراص الجسيمات واهتزازها في أماكنها","قوى تجاذب قوية جدًا","الكثافة العالية","ضعف القابلية للانضغاط","ليست من الموائع"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى","marks":1},{"element":"الخاصية الثانية","marks":1},{"element":"الخاصية الثالثة","marks":1},{"element":"الخاصية الرابعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خصائص صحيحة"},{"level":"3 درجات","description":"ثلاث خصائص صحيحة"},{"level":"1–2 درجة","description":"خاصية أو خاصيتان"},{"level":"صفر","description":"خصائص لا تخص الصلب أو لا إجابة"}]'::jsonb, '["ذكر خاصية الانسياب أو أخذ شكل الإناء","القول إن الصلب لا ينضغط إطلاقًا","تكرار الخاصية نفسها بصياغتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.127Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2059, null, null, null, 'الصلبة: شكل ثابت، وحجم ثابت، وجسيماتها تهتز في أماكنها. السائلة: تأخذ شكل الإناء، وحجمها ثابت، وجسيماتها تنزلق بعضها فوق بعض. الغازية: تأخذ شكل الإناء، وتملأ حجمه كله، وجسيماتها تتحرك حركة عشوائية سريعة في خطوط مستقيمة.', '["مقارنة الشكل في الحالات الثلاث","مقارنة الحجم في الحالات الثلاث","مقارنة حركة الجسيمات في الحالات الثلاث"]'::jsonb, '[]'::jsonb, '[{"element":"الشكل","marks":2},{"element":"الحجم","marks":2},{"element":"حركة الجسيمات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة صحيحة في المعايير الثلاثة للحالات الثلاث"},{"level":"4–5 درجات","description":"خطأ أو نقص في خانة أو خانتين"},{"level":"2–3 درجات","description":"مقارنة صحيحة في معيار واحد"},{"level":"صفر","description":"مقارنة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن حجم الغاز ثابت","وصف جسيمات الصلب بأنها ساكنة تمامًا لا تهتز","وصف جسيمات السائل بأنها تهتز في أماكنها فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T11:15:02.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2060, null, null, null, 'جسيمات المادة الصلبة متراصة بشدة تربطها قوى تجاذب قوية جدًا، فتبقى في مواقع ثابتة ولا تستطيع إلا الاهتزاز في أماكنها دون أن تنزلق بعضها فوق بعض؛ لذلك يبقى شكلها ثابتًا. ولأن جسيماتها متقاربة جدًا والفراغات بينها ضئيلة جدًا، لا يتغير حجمها إلا بقدر ضئيل جدًا، فيبقى ثابتًا.', '["قوى تجاذب قوية جدًا","الجسيمات في مواقع ثابتة تهتز ولا تنزلق ← شكل ثابت","التراص وضآلة الفراغات ← حجم ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"قوى التجاذب","marks":1},{"element":"تفسير ثبات الشكل","marks":2},{"element":"تفسير ثبات الحجم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير الشكل والحجم بالقوى وحركة الجسيمات"},{"level":"3 درجات","description":"تفسير أحدهما كاملًا والآخر ناقصًا"},{"level":"1–2 درجة","description":"ذكر قوى التجاذب دون ربط"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن جسيمات الصلب لا تتحرك إطلاقًا","ربط ثبات الشكل بكبر حجم الجسيمات","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.128Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2061, 1, 'يعتمد متوسط الطاقة الحركية لجسيمات المادة الصلبة على درجة الحرارة.', '["حجم القطعة لا يغير متوسط طاقة جسيماتها ما دامت درجة الحرارة ثابتة.","","الشكل الخارجي لا علاقة له بطاقة حركة الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:02.130Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2062, 2, 'التسخين يرفع درجة الحرارة فيزداد متوسط الطاقة الحركية للجسيمات، فيزداد اهتزازها في أماكنها.', '["التسخين يزيد طاقة الجسيمات لا يوقفها.","ما دامت المادة صلبة تبقى جسيماتها في مواقعها ولا تتحرك بحرية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.131Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2063, 2, 'متوسط الطاقة الحركية يزداد بارتفاع درجة الحرارة، وأعلى درجة حرارة للقطعة (ب) عند 80 °C.', '["أقل القطع حرارة فمتوسط طاقة جسيماتها هو الأقل.","درجة حرارتها أقل من القطعة (ب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2064, 2, 'متوسط الطاقة الحركية يعتمد على درجة الحرارة فقط، والقطعتان عند درجة الحرارة نفسها فمتوسط طاقة جسيماتهما متساوٍ.', '["الكتلة لا تحدد متوسط طاقة الجسيمات؛ فدرجة الحرارة هي العامل المؤثر.","صغر الكتلة لا يزيد متوسط طاقة الجسيمات ما دامت درجة الحرارة واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.132Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2065, 2, 'ارتفاع درجة الحرارة يزيد الطاقة الحركية للجسيمات فيقوى اهتزازها، وعندما يصبح كافيًا للتغلب على قوى التجاذب تنصهر المادة.', '["الجسيمات نفسها لا تتمدد ولا تلين؛ بل تتغير حركتها والمسافات بينها.","التسخين لا يزيد قوى التجاذب، بل يزيد طاقة الجسيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2066, 1, 'انخفاض درجة الحرارة يقلل متوسط الطاقة الحركية للجزيئات فيقل اهتزازها في أماكنها.', '["الزيادة تحدث عند رفع درجة الحرارة لا خفضها.","","متوسط الطاقة الحركية يتغير بتغير درجة الحرارة حتى في الحالة الصلبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2067, 0, 'العلاقة طردية: بارتفاع درجة الحرارة يزداد متوسط الطاقة الحركية لجسيمات الصلب.', '["","هذه علاقة عكسية تخالف الواقع؛ فالتسخين يزيد طاقة الجسيمات.","درجة الحرارة هي العامل الذي تعتمد عليه الطاقة الحركية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2068, null, null, null, 'العامل هو درجة الحرارة. كلما ارتفعت درجة الحرارة زاد متوسط الطاقة الحركية للجسيمات فيزداد اهتزازها في أماكنها الثابتة، وكلما انخفضت قلت الطاقة الحركية وقل الاهتزاز.', '["تحديد العامل: درجة الحرارة","العلاقة الطردية","أثرها في اهتزاز الجسيمات في أماكنها"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العامل","marks":1},{"element":"نوع العلاقة","marks":1},{"element":"الأثر في حركة الجسيمات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"العامل والعلاقة والأثر صحيحة"},{"level":"2 درجتان","description":"العامل مع العلاقة أو الأثر"},{"level":"1 درجة","description":"العامل فقط"},{"level":"صفر","description":"عامل خاطئ أو لا إجابة"}]'::jsonb, '["ذكر الكتلة أو الحجم عاملًا مؤثرًا","وصف حركة جسيمات الصلب بالانزلاق","عكس العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T11:15:02.133Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2069, null, null, null, 'عند −10 °C تهتز جزيئات الجليد في أماكنها. بالتسخين ترتفع درجة الحرارة فيزداد متوسط الطاقة الحركية للجزيئات ويقوى اهتزازها. وعندما يصبح الاهتزاز قويًا بما يكفي للتغلب على قوى التجاذب التي تثبت الجزيئات في مواقعها، تبدأ الجزيئات بمغادرة مواقعها والانزلاق بعضها فوق بعض، فينصهر الجليد ويتحول إلى ماء سائل.', '["الحالة الابتدائية: اهتزاز في أماكنها","ارتفاع الحرارة يزيد الطاقة الحركية والاهتزاز","التغلب على قوى التجاذب","تحرر الجزيئات وانزلاقها (الانصهار)"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الحرارة بالطاقة الحركية","marks":2},{"element":"التغلب على قوى التجاذب","marks":2},{"element":"وصف الانصهار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير متسلسل كامل"},{"level":"3–4 درجات","description":"تفسير صحيح ينقصه عنصر"},{"level":"1–2 درجة","description":"ذكر زيادة الطاقة فقط"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن قوى التجاذب تزداد بالتسخين","وصف الجسيمات بأنها تتمدد وتكبر","إغفال دور قوى التجاذب في الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:02.134Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2070, null, null, null, '(أ) في القطعة الصغيرة. (ب) لأن متوسط الطاقة الحركية للجسيمات يعتمد على درجة الحرارة لا على الكتلة أو الحجم، ودرجة حرارة القطعة الصغيرة أعلى. (ج) يزداد حتى يساوي متوسط الطاقة الحركية لجسيمات القطعة الصغيرة لأن درجتي حرارتهما تصبحان متساويتين.', '["(أ) القطعة الصغيرة","(ب) التعليل بدرجة الحرارة لا الكتلة","(ج) يزداد ويتساوى مع الصغيرة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الإجابات الثلاث صحيحة مع تعليل سليم"},{"level":"3–4 درجات","description":"خطأ في جزء أو تعليل ناقص"},{"level":"1–2 درجة","description":"إجابة (أ) فقط"},{"level":"صفر","description":"اختيار القطعة الكبيرة بسبب كتلتها أو لا إجابة"}]'::jsonb, '["اختيار القطعة الكبيرة لأن كتلتها أكبر","الخلط بين متوسط الطاقة الحركية والطاقة الكلية","القول إن الطاقة لا تتغير في (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:02.134Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2071, 1, 'جسيمات المادة الصلبة متراصة بشدة في ترتيب منتظم، فيوجد عدد أكبر من الجسيمات (كتلة أكبر) في وحدة الحجم.', '["التباعد يعني حجمًا أكبر وكثافة أقل، وهذا عكس المطلوب.","","كتلة الجسيم لا تتغير بتغير الحالة الفيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.136Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2072, 2, 'الكتلة محفوظة، ويقل الحجم لتراص الجسيمات، فتزداد الكثافة (الكتلة ÷ الحجم).', '["الكتلة لا تتغير بتغير الحالة الفيزيائية.","زيادة الحجم عند التجمد سلوك شاذ يخص مواد قليلة كالماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:02.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2073, 1, 'الكثافة = الكتلة ÷ الحجم: الصلبة 50.0 ÷ 40.0 = 1.25 g/cm³، والسائلة 50.0 ÷ 45.0 = 1.11 g/cm³؛ فالصلبة أعلى كثافة لأن الكتلة نفسها تشغل حجمًا أصغر.', '["الحسابات صحيحة لكن القيمتين معكوستان بين الحالتين.","","ناتج قسمة الحجم على الكتلة (V ÷ m) بدل m ÷ V."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2074, 0, 'الماء استثناء؛ فالجليد أقل كثافة من الماء السائل ولذلك يطفو عليه.', '["","الحديد الصلب أعلى كثافة من الحديد المنصهر كمعظم المواد.","البنزين يسلك السلوك المعتاد؛ فمكعباته الصلبة تغرق في سائله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2075, 2, 'تراص الجسيمات في الحالة الصلبة يجعل عددها في وحدة الحجم أكبر، فتكون الكثافة أعلى.', '["حجم الجسيم نفسه لا يتغير بتغير الحالة؛ بل تتغير المسافات بين الجسيمات.","هذا يعني كثافة أقل، وهو خاص بالمواد الشاذة كالماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.137Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2076, 2, 'الرصاص كمعظم المواد تكون كثافته في الحالة الصلبة أعلى منها في الحالة السائلة، فتغرق القطعة الصلبة في المنصهر.', '["هذا سلوك المواد الشاذة كالماء، والرصاص يسلك السلوك المعتاد.","كثافة المادة الصلبة تختلف عادة عن كثافة حالتها السائلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2077, 0, 'قوى التجاذب القوية تجعل الجسيمات متقاربة متراصة، فيقل الحجم الذي تشغله الكتلة نفسها وتزداد الكثافة.', '["","التجاذب يقرّب الجسيمات لا يُبعدها.","قوى التجاذب لا تغير كتلة الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2078, null, null, null, 'في الحالة الصلبة تكون الجسيمات متراصة بشدة في ترتيب منتظم بفعل قوى التجاذب القوية، فتكون المسافات بينها أصغر منها في الحالة السائلة. لذلك تشغل الكتلة نفسها حجمًا أصغر، أي يكون عدد الجسيمات (الكتلة) في وحدة الحجم أكبر، وبما أن الكثافة = الكتلة ÷ الحجم فإن كثافة الحالة الصلبة تكون أعلى.', '["تراص الجسيمات في الصلب بفعل قوى التجاذب","الكتلة نفسها تشغل حجمًا أصغر","الربط بعلاقة الكثافة = الكتلة ÷ الحجم"]'::jsonb, '[]'::jsonb, '[{"element":"تراص الجسيمات","marks":1},{"element":"حجم أصغر للكتلة نفسها","marks":1},{"element":"الربط بالكثافة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل مترابط"},{"level":"2 درجتان","description":"تفسير ينقصه الربط بالكثافة"},{"level":"1 درجة","description":"ذكر التراص فقط"},{"level":"صفر","description":"تفسير بزيادة الكتلة أو لا إجابة"}]'::jsonb, '["القول إن الكتلة تزداد عند التجمد","تعميم القاعدة على الماء","القول إن الجسيمات نفسها تصغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2079, null, null, null, '(أ) V = m ÷ d: الحالة السائلة V = 180 ÷ 0.80 = 225 cm³، والحالة الصلبة V = 180 ÷ 0.90 = 200 cm³. (ب) يقل الحجم بمقدار 225 − 200 = 25 cm³ مع بقاء الكتلة ثابتة. (ج) لأن الجسيمات في الحالة الصلبة تتراص في ترتيب منتظم أقرب بعضها إلى بعض منها في السائلة، فتشغل حجمًا أصغر وتكون الكثافة أعلى.', '["استخدام V = m ÷ d","حجم السائل 225 cm³","حجم الصلب 200 cm³","يقل الحجم بمقدار 25 cm³","التفسير بتراص الجسيمات"]'::jsonb, '["V(سائل) = 180 g ÷ 0.80 g/cm³ = 225 cm³","V(صلب) = 180 g ÷ 0.90 g/cm³ = 200 cm³","ΔV = 225 − 200 = 25 cm³ (نقصان)"]'::jsonb, '[{"element":"(أ) الحسابان بالوحدات","marks":2},{"element":"(ب) الاستنتاج","marks":1},{"element":"(ج) التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة بالوحدات واستنتاج وتفسير سليمان"},{"level":"3–4 درجات","description":"خطأ في حساب واحد أو تفسير ناقص"},{"level":"1–2 درجة","description":"كتابة العلاقة فقط أو الاستنتاج دون حساب"},{"level":"صفر","description":"حسابات خاطئة كليًا أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في الكثافة بدل القسمة","القول إن الحجم يزداد عند التجمد","إهمال الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.138Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2080, null, null, null, 'العبارة غير دقيقة لأنها تعمم القاعدة؛ فمعظم المواد فعلًا تكون كثافتها في الحالة الصلبة أعلى لتراص جسيماتها، لكن هناك استثناءات أشهرها الماء؛ فالجليد أقل كثافة من الماء السائل ولذلك يطفو عليه. الصياغة الأدق: «معظم المواد تكون كثافتها في الحالة الصلبة أعلى من كثافتها في الحالة السائلة، ويُستثنى من ذلك الماء».', '["الحكم: العبارة غير دقيقة (تعميم)","تأييد القاعدة لمعظم المواد مع السبب","ذكر الماء استثناءً مع الدليل (طفو الجليد)","صياغة بديلة دقيقة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع ذكر الاستثناء","marks":2},{"element":"السبب للمواد المعتادة","marks":1},{"element":"الصياغة الأدق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح باستثناء وتعليل وصياغة دقيقة"},{"level":"3 درجات","description":"حكم واستثناء دون صياغة بديلة"},{"level":"1–2 درجة","description":"حكم صحيح دون مبرر"},{"level":"صفر","description":"قبول العبارة على إطلاقها أو لا إجابة"}]'::jsonb, '["قبول العبارة دون تحفظ","ذكر البنزين استثناءً","رفض القاعدة كليًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T11:15:02.139Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2081, 0, 'جسيمات المادة الصلبة متراصة بشدة في مواقع ثابتة والفراغات بينها ضئيلة جدًا، فلا يمكن تقريبها أكثر إلا بقدر ضئيل جدًا.', '["","جسيمات الصلب تربطها قوى تجاذب قوية جدًا.","هذا وصف جسيمات الغاز التي تنضغط بسهولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.141Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2082, 1, 'قابلية الانضغاط تزداد بزيادة الفراغات بين الجسيمات: الصلبة (الأقل) ثم السائلة ثم الغازية (الأكبر).', '["السائلة أكثر قابلية للانضغاط قليلًا من الصلبة لا أقل.","","هذا ترتيب تنازلي؛ فالغاز هو الأكثر قابلية للانضغاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.141Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2083, 2, 'الإسفنج فيه فراغات (مسام) مملوءة بالهواء، والهواء هو الذي ينضغط ويخرج، أما مادة الإسفنج الصلبة نفسها فقابليتها للانضغاط ضئيلة جدًا.', '["جسيمات مادة الإسفنج نفسها متراصة كأي صلب؛ والذي ينضغط هو الهواء في فراغاته.","الضغط باليد لا يغير حالة مادة الإسفنج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.141Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2084, 1, 'تغير حجم العينة (ج) ضئيل جدًا (0.01 mL من 100.00 mL)، وهذا سلوك المادة الصلبة التي تكاد لا تنضغط.', '["نقص حجمها إلى النصف، وهذا سلوك الغاز.","","نقص حجمها قليلًا (0.5%)، وهذا سلوك السائل الذي ينضغط أكثر من الصلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2085, 2, 'ضعف قابلية الصلب للانضغاط يعني أنه يحافظ على حجمه وشكله تحت الأحمال الثقيلة، فيصلح لبناء الركائز.', '["المواد الصلبة لا تنساب؛ فالانسياب صفة الموائع.","جسيمات الصلب ثابتة في مواقعها تهتز فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2086, 1, 'المواد الصلبة تنضغط بدرجة ضئيلة جدًا لا معدومة؛ فالأدق القول إن قابليتها للانضغاط ضعيفة جدًا.', '["الغازات وحدها تنضغط بسهولة لكبر الفراغات بين جسيماتها.","","الفراغات بين جسيمات الصلب ضئيلة جدًا لكنها ليست معدومة تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2087, 0, 'المسافات الكبيرة بين جسيمات الغاز تسمح بتقريبها بسهولة عند الضغط، بعكس الصلب الذي تتراص جسيماته.', '["","قوى التجاذب بين جسيمات الغاز ضعيفة جدًا لا كبيرة.","ثبات الجسيمات في مواقعها صفة الصلب لا الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.142Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2088, null, null, null, 'جسيمات المادة الصلبة متراصة بشدة في مواقع ثابتة تربطها قوى تجاذب قوية جدًا، والفراغات بينها ضئيلة جدًا. لذلك عند الضغط عليها لا يمكن تقريب الجسيمات بعضها من بعض إلا بقدر ضئيل جدًا، فيبقى حجمها ثابتًا تقريبًا، أي أن قابليتها للانضغاط ضعيفة جدًا (لا معدومة).', '["تراص الجسيمات في مواقع ثابتة","ضآلة الفراغات بين الجسيمات","النتيجة: تغير ضئيل جدًا في الحجم عند الضغط"]'::jsonb, '[]'::jsonb, '[{"element":"تراص الجسيمات","marks":1},{"element":"ضآلة الفراغات","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل مع الإشارة إلى أن الانضغاط ضئيل لا معدوم"},{"level":"2 درجتان","description":"تفسير صحيح ينقصه عنصر"},{"level":"1 درجة","description":"ذكر التراص فقط"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن الصلب لا ينضغط إطلاقًا لعدم وجود فراغات","التفسير بثقل المادة الصلبة","الخلط بين الانضغاط والانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.143Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2089, null, null, null, 'الغاز: قابليته للانضغاط كبيرة؛ لأن المسافات بين جسيماته كبيرة جدًا وقوى التجاذب بينها ضعيفة جدًا، فيمكن تقريب الجسيمات بسهولة. المادة الصلبة: قابليتها للانضغاط ضئيلة جدًا؛ لأن جسيماتها متراصة والمسافات بينها ضئيلة جدًا وقوى التجاذب قوية جدًا تثبتها في مواقعها.', '["الغاز سهل الانضغاط","تفسيره بالمسافات الكبيرة والقوى الضعيفة","الصلب ضعيف الانضغاط","تفسيره بالتراص والقوى القوية"]'::jsonb, '[]'::jsonb, '[{"element":"الغاز: الحكم والتفسير","marks":2},{"element":"الصلب: الحكم والتفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة بتفسير للحالتين"},{"level":"3 درجات","description":"مقارنة صحيحة مع تفسير ناقص لإحداهما"},{"level":"1–2 درجة","description":"الحكم دون تفسير"},{"level":"صفر","description":"مقارنة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الحكم بين الحالتين","تفسير الانضغاط بحجم الجسيمات لا بالمسافات بينها","إغفال قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.143Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2090, null, null, null, '(أ) النسبة المئوية للنقص = (النقص ÷ الحجم الأصلي) × 100: العينة (أ): (500 ÷ 1000) × 100 = 50%؛ العينة (ب): (0.5 ÷ 100.0) × 100 = 0.5%؛ العينة (ج): (0.01 ÷ 100.00) × 100 = 0.01%. (ب) (أ) غاز، (ب) سائل، (ج) صلب. (ج) لأن جسيمات المادة الصلبة متراصة بشدة والفراغات بينها ضئيلة جدًا، فلا تقترب إلا بقدر ضئيل جدًا.', '["قانون النسبة المئوية للنقص","50% و0.5% و0.01%","تحديد الحالات: غاز، سائل، صلب","التفسير بتراص جسيمات الصلب"]'::jsonb, '["(أ): (1000 − 500) ÷ 1000 × 100 = 50%","(ب): (100.0 − 99.5) ÷ 100.0 × 100 = 0.5%","(ج): (100.00 − 99.99) ÷ 100.00 × 100 = 0.01%"]'::jsonb, '[{"element":"(أ) الحسابات","marks":3},{"element":"(ب) تحديد الحالات","marks":1},{"element":"(ج) التفسير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة وتحديد سليم وتفسير كامل"},{"level":"4–5 درجات","description":"خطأ في حساب واحد أو تفسير ناقص"},{"level":"2–3 درجات","description":"تحديد الحالات دون حسابات صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على الحجم النهائي بدل الأصلي","عدّ العينة (ب) صلبة لأن تغيرها صغير","القول إن حجم الصلب لا يتغير أبدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T11:15:02.143Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2091, 0, 'الحديد مادة صلبة جسيماتها مثبتة في مواقعها فلا تنساب، أما الغازات (الهواء) والسوائل (الزيت) فتنساب فتُعد موائع.', '["","الهواء غاز تنساب جسيماته، فهو من الموائع.","الزيت سائل ينساب ويأخذ شكل الإناء، فهو من الموائع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T11:15:02.145Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2092, 0, 'لا تُصنف المواد الصلبة من الموائع لأن جسيماتها في مواقع ثابتة لا تنزلق بعضها فوق بعض، فلا تستطيع الانسياب.', '["","الكتلة لا علاقة لها بقدرة المادة على الانسياب.","جسيمات الصلب متراصة لا متباعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:02.146Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2093, 2, 'الماء والزيت سائلان، والهواء غاز، وكلها تنساب فهي موائع.', '["الملح والسكر مادتان صلبتان.","الحديد مادة صلبة لا تنساب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.146Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2094, 0, 'السكر مادة صلبة؛ فكل حبيبة منه لها شكل ثابت وجزيئاتها ثابتة في مواقعها، وما ينسكب هو حبيبات صلبة متفرقة لا مادة تنساب.', '["","جزيئات السكر داخل كل حبيبة ثابتة في مواقعها ولا تنزلق.","انسكاب الحبيبات حركة لقطع صلبة صغيرة، لا انسياب للمادة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.146Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
