(2095, 2, 'جسيمات المادة (ب) تهتز في مواقع ثابتة ولا تنزلق، فهي صلبة لا تنساب، أما (أ) فسائلة و(ج) غازية وكلتاهما من الموائع.', '["جسيماتها تنزلق فهي سائلة تنساب.","جسيماتها حرة الحركة فهي غازية تنساب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.146Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2096, 2, 'قوى التجاذب القوية جدًا تثبت جسيمات الصلب في مواقعها فتهتز فقط ولا تنزلق، فلا تنساب المادة.', '["قوى التجاذب تقرّب الجسيمات ولا تباعدها.","الحركة السريعة العشوائية صفة جسيمات الغاز ذات القوى الضعيفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2097, 1, 'بالانصهار تتغلب الجسيمات على قوى التجاذب التي تثبتها وتصبح قادرة على الانزلاق، فتنساب المادة وتصبح مائعًا.', '["هذا عكس ما يحدث؛ فالتسخين يزيد حركة الجسيمات.","","الانصهار يحدث بالتغلب على قوى التجاذب لا بزيادتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2098, null, null, null, 'الموائع مواد تستطيع الانسياب. في السوائل تنزلق الجسيمات بعضها فوق بعض، وفي الغازات تتحرك الجسيمات بحرية، فكلاهما ينساب ويأخذ شكل الإناء فهما من الموائع. أما في المواد الصلبة فالجسيمات مثبتة في مواقع ثابتة بقوى تجاذب قوية جدًا، فلا تستطيع إلا الاهتزاز في أماكنها ولا تنزلق، فلا تنساب ولا تُصنف من الموائع.', '["تعريف الموائع (القدرة على الانسياب)","تفسير انسياب السوائل والغازات","جسيمات الصلب في مواقع ثابتة بقوى قوية","الصلب لا ينساب فليس مائعًا"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الموائع","marks":1},{"element":"تفسير السوائل والغازات","marks":1},{"element":"تفسير الصلب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالات الثلاث"},{"level":"3 درجات","description":"تفسير الصلب صحيح مع نقص في غيره"},{"level":"1–2 درجة","description":"ذكر أن الصلب لا ينساب دون تعليل"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["تفسير عدم الانسياب بكتلة المادة الصلبة","عدّ الغازات غير موائع","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:02.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2099, null, null, null, 'العبارة خاطئة. الرمل والسكر مادتان صلبتان؛ فكل حبيبة منهما لها شكل ثابت وحجم ثابت، وجسيماتها مثبتة في مواقعها لا تنزلق بعضها فوق بعض. وما يبدو انسيابًا هو انسكاب حبيبات صلبة صغيرة متفرقة تتحرك ككتل منفصلة، لا انسياب للمادة نفسها كما في السوائل والغازات.', '["الحكم: العبارة خاطئة","كل حبيبة صلبة ثابتة الشكل","جسيمات الحبيبة لا تنزلق","التمييز بين انسكاب الحبيبات وانسياب المائع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بخصائص الحبيبة الصلبة","marks":2},{"element":"التمييز بين الانسكاب والانسياب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح بتعليل كامل"},{"level":"3 درجات","description":"حكم صحيح بتعليل ناقص"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"قبول العبارة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن المساحيق تنسكب","الحكم الصحيح دون تمييز بين الانسكاب والانسياب","عدّ الرمل سائلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.147Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2100, null, null, null, 'مكعب الجليد يحتفظ بشكله المكعب ولا يأخذ شكل الكأس؛ لأن جزيئاته مثبتة في مواقع ثابتة بقوى تجاذب قوية تهتز فقط ولا تنزلق. أما الماء السائل فينساب ويأخذ شكل الجزء السفلي من الكأس؛ لأن جزيئاته تنزلق بعضها فوق بعض. لذلك يُعد الماء السائل مائعًا، ولا يُعد الجليد مائعًا.', '["الجليد يحتفظ بشكله","الماء يأخذ شكل الإناء","تفسير سلوك الجليد بثبات الجزيئات","تفسير سلوك الماء بانزلاق الجزيئات","الحكم: الماء مائع والجليد ليس مائعًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الشكلين","marks":1},{"element":"تفسير الجليد","marks":2},{"element":"تفسير الماء","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة وتفسير وحكم كاملة"},{"level":"3–4 درجات","description":"نقص في تفسير إحدى الحالتين"},{"level":"1–2 درجة","description":"وصف دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجليد يأخذ شكل الكأس","عدّ الجليد والماء كليهما موائع لأنهما المادة نفسها","التفسير باختلاف نوع الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.148Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2101, 0, 'يغرق الجسم في سائل أقل منه كثافة، وكثافة البنزين الصلب أكبر من كثافة البنزين السائل لتراص جزيئاته في الحالة الصلبة.', '["","الغرق والطفو يحددهما مقارنة الكثافة لا مقارنة الكتلة الكلية.","لو كانت كثافة الصلب أقل لطفا على السائل كما يطفو الجليد على الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.150Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2102, 1, 'المقصود بالبنزين هنا المركب C₆H₆ (benzene) لا وقود السيارات، وهو مادة نقية يمكن تجميدها إلى مكعبات صلبة.', '["وقود السيارات خليط من مواد عدة، وليس المقصود في الكتاب.","","لا علاقة للماء بالعبارة؛ فالمادة نفسها في الحالتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.150Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2103, 2, 'تتراص جزيئات البنزين في الحالة الصلبة في ترتيب منتظم أقرب بعضها إلى بعض منها في السائل، فيقل الحجم وتزداد الكثافة.', '["التجمد يقلل حركة الجزيئات فتهتز في أماكنها فقط.","الترتيب السداسي المفتوح خاص بالجليد بسبب الروابط الهيدروجينية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.150Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2104, 2, 'البنزين يسلك سلوك معظم المواد فيغرق صلبه في سائله، أما الماء فيشذ فيطفو الجليد عليه.', '["هذا عكس الحالتين؛ فالجليد أقل كثافة من الماء.","البنزين الصلب أعلى كثافة من سائله فلا يطفو.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:02.150Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2105, 0, 'الكتلة ثابتة (10.0 g)، وبما أن كثافة البنزين الصلب أكبر من سائله فإن الحجم يقل عند التجمد (V = m ÷ d).', '["","زيادة الحجم عند التجمد سلوك شاذ كالماء، والبنزين يسلك السلوك المعتاد.","تراص الجزيئات عند التجمد يغير الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2106, 1, 'معظم المواد تكون كثافة حالتها الصلبة أعلى من حالتها السائلة، وغرق البنزين الصلب دليل على أنه يسلك هذا السلوك المعتاد.', '["لو لم تتغير الكثافة لبقي المكعب معلقًا لا يغرق.","","الشذوذ يعني طفو الصلب على سائله، والبنزين يغرق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:02.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2107, 0, 'تغرق الحالة الصلبة في السائلة عندما تكون كثافتها أكبر، وهذا يتحقق في المادة (أ) فقط (0.95 > 0.88).', '["","كثافة صلبها أقل من سائلها فيطفو كالجليد.","كثافة صلبها أقل من سائلها فيطفو على سائله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.151Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2108, null, null, null, 'تغرق مكعبات البنزين الصلبة لأن كثافة البنزين الصلب أكبر من كثافة البنزين السائل. والسبب أن جزيئات البنزين في الحالة الصلبة تتراص بشدة في ترتيب منتظم أقرب بعضها إلى بعض منها في الحالة السائلة، فتشغل الكتلة نفسها حجمًا أصغر فتزداد الكثافة، والجسم الأعلى كثافة يغرق في السائل الأقل كثافة.', '["كثافة الصلب أكبر من كثافة السائل","تراص الجزيئات في الحالة الصلبة","الكتلة نفسها في حجم أصغر","قاعدة الغرق: الأعلى كثافة يغرق"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الكثافتين","marks":1},{"element":"التفسير الجسيمي","marks":2},{"element":"قاعدة الغرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط الكثافة بترتيب الجزيئات"},{"level":"3 درجات","description":"مقارنة الكثافة مع تفسير ناقص"},{"level":"1–2 درجة","description":"مقارنة الكثافة دون تفسير"},{"level":"صفر","description":"تفسير بالكتلة أو لا إجابة"}]'::jsonb, '["تفسير الغرق بأن المكعب ثقيل","الخلط بين البنزين C₆H₆ ووقود السيارات","القول إن الجزيئات تكبر في الحالة الصلبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T11:15:02.153Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2109, null, null, null, 'مكعب البنزين الصلب يغرق في سائله لأن كثافته أكبر؛ إذ تتراص جزيئاته في الحالة الصلبة أقرب بعضها إلى بعض، وهذا هو السلوك المعتاد لمعظم المواد. أما مكعب الجليد فيطفو على الماء لأن كثافته أقل؛ إذ ترتبط جزيئات الماء عند التجمد بروابط هيدروجينية في ترتيب سداسي مفتوح فيه فراغات كبيرة، فتتباعد الجزيئات ويزداد الحجم، وهذا سلوك شاذ.', '["البنزين يغرق والجليد يطفو","تفسير البنزين بتراص الجزيئات","تفسير الجليد بالترتيب السداسي المفتوح والروابط الهيدروجينية","وصف البنزين بالمعتاد والماء بالشاذ"]'::jsonb, '[]'::jsonb, '[{"element":"وصف السلوكين","marks":1},{"element":"تفسير البنزين","marks":2},{"element":"تفسير الجليد","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة وتفسير كاملان للحالتين"},{"level":"3–4 درجات","description":"نقص في تفسير إحدى الحالتين"},{"level":"1–2 درجة","description":"وصف السلوكين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير طفو الجليد بفقاعات الهواء","عدّ البنزين شاذًا كالماء","إغفال الروابط الهيدروجينية في تفسير الجليد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T11:15:02.153Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2110, null, null, null, '(أ) d = m ÷ V = 9.40 g ÷ 9.80 cm³ = 0.959 g/cm³. (ب) تغرق؛ لأن كثافة البنزين الصلب (0.959 g/cm³) أكبر من كثافة سائله (0.879 g/cm³). (ج) يدل على أن البنزين يسلك سلوك معظم المواد؛ فحجمه يقل وكثافته تزداد عند التجمد لتراص جزيئاته.', '["d = m ÷ V","الكثافة 0.959 g/cm³","المقارنة والحكم بالغرق","الاستنتاج: سلوك معتاد مع التفسير"]'::jsonb, '["d = 9.40 g ÷ 9.80 cm³ = 0.959 g/cm³","0.959 > 0.879 ← تغرق العينة"]'::jsonb, '[{"element":"(أ) الحساب بالوحدة","marks":2},{"element":"(ب) الحكم مع التعليل","marks":2},{"element":"(ج) الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح وحكم معلل واستنتاج سليم"},{"level":"3–4 درجات","description":"خطأ في الحساب مع حكم صحيح أو استنتاج ناقص"},{"level":"1–2 درجة","description":"الحكم فقط دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الحجم على الكتلة (1.04)","الحكم بالطفو لأن الكتلة صغيرة","إهمال الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.154Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2111, 0, 'يطفو الجليد لأن كثافته (نحو 0.917 g/cm³) أقل من كثافة الماء السائل (نحو 1.00 g/cm³).', '["","الجسم الأعلى كثافة يغرق لا يطفو.","الطفو تحدده الكثافة لا الكتلة الكلية؛ فجبل جليدي ضخم يطفو أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2112, 1, 'عند التجمد ترتبط جزيئات الماء بروابط هيدروجينية في ترتيب سداسي منتظم مفتوح فيه فراغات كبيرة، فتتباعد الجزيئات.', '["جزيئات الماء تبقى سليمة عند التجمد؛ فالتجمد تغير فيزيائي.","","قوى التجاذب في الجليد لا تضعف؛ بل تنتظم الروابط الهيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2113, 2, 'V = m ÷ d = 50.0 g ÷ 0.917 g/cm³ = 54.5 cm³، وهو أكبر من حجم 50.0 g من الماء السائل (50.0 cm³).', '["ناتج قسمة الكثافة على الكتلة (d ÷ m).","ناتج ضرب الكتلة في الكثافة (m × d) بدل القسمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.156Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2114, 2, 'سبب الطفو أن الجليد نفسه أقل كثافة من الماء السائل بسبب ترتيب جزيئاته السداسي المفتوح، لا فقاعات الهواء.', '["الطفو يتحدد بالكثافة لا بالكتلة الكلية.","الجليد النقي الخالي من الفقاعات يطفو أيضًا، فالسبب في بنيته لا في الهواء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2115, 2, 'عند تجمد الماء يزداد حجمه (لأن كثافة الجليد أقل)، فيضغط على جدران القارورة المغلقة فتتشقق.', '["الكتلة محفوظة لا تتغير بتغير الحالة.","لو قل الحجم لما ضغط الجليد على جدران القارورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T11:15:02.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2116, 0, 'يطفو الجسم في سائل أعلى منه كثافة: الجليد (0.917) أقل كثافة من الماء (1.00) فيطفو فيه، وأعلى كثافة من الكحول (0.789) فيغرق فيه.', '["","كثافة الكحول (0.789) أقل من كثافة الجليد (0.917) فيغرق فيه الجليد.","الجليد أعلى كثافة من الكحول فيغرق فيه، ولا يطفو إلا في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2117, 1, 'يبقى الجليد على السطح فيعمل عازلًا يقلل فقد الحرارة، فيبقى الماء تحته سائلًا وتستمر الحياة فيه.', '["الجليد لا يرفع حرارة الماء كثيرًا؛ بل يمنع فقده للحرارة.","","طبقة الجليد السطحية تبطئ تجمد الماء تحتها لا تسرّعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.157Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2118, null, null, null, 'يطفو الجليد لأن كثافته (نحو 0.917 g/cm³) أقل من كثافة الماء السائل (نحو 1.00 g/cm³). فعند تجمد الماء ترتبط جزيئاته بروابط هيدروجينية في ترتيب سداسي منتظم مفتوح فيه فراغات كبيرة، فتكون الجزيئات في الجليد أكثر تباعدًا منها في الماء السائل، فيزداد الحجم وتقل الكثافة. وهذا سلوك شاذ يخالف معظم المواد.', '["كثافة الجليد أقل من الماء","الروابط الهيدروجينية","الترتيب السداسي المفتوح والفراغات","زيادة الحجم وقلة الكثافة","وصف السلوك بالشاذ"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الكثافة","marks":1},{"element":"الروابط الهيدروجينية والترتيب السداسي","marks":2},{"element":"الربط بالحجم والكثافة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط البنية بالكثافة"},{"level":"3 درجات","description":"تفسير ينقصه ذكر الروابط الهيدروجينية أو الترتيب"},{"level":"1–2 درجة","description":"مقارنة الكثافة فقط"},{"level":"صفر","description":"تفسير بفقاعات الهواء أو لا إجابة"}]'::jsonb, '["تفسير الطفو بفقاعات الهواء","القول إن كتلة الجليد أقل","القول إن الروابط تتكسر عند التجمد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T11:15:02.158Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2119, null, null, null, '(أ) V(ماء) = 100 ÷ 1.00 = 100 cm³، V(جليد) = 100 ÷ 0.917 = 109 cm³. (ب) النسبة المئوية للزيادة = (109 − 100) ÷ 100 × 100 ≈ 9.05% ≈ 9%. (ج) تشقق القوارير المغلقة المملوءة بالماء في المجمد، أو انفجار أنابيب المياه في الشتاء البارد جدًا.', '["V = m ÷ d","حجم الماء 100 cm³","حجم الجليد 109 cm³","الزيادة ≈ 9%","نتيجة عملية صحيحة"]'::jsonb, '["V(ماء) = 100 g ÷ 1.00 g/cm³ = 100 cm³","V(جليد) = 100 g ÷ 0.917 g/cm³ = 109 cm³","الزيادة = (109.05 − 100) ÷ 100 × 100 ≈ 9.05%"]'::jsonb, '[{"element":"(أ) الحجمان","marks":2},{"element":"(ب) النسبة المئوية","marks":2},{"element":"(ج) النتيجة العملية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة بالوحدات ونتيجة عملية مناسبة"},{"level":"3–4 درجات","description":"خطأ في خطوة حسابية أو نتيجة غير مناسبة"},{"level":"1–2 درجة","description":"حساب حجم واحد فقط"},{"level":"صفر","description":"حسابات خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في الكثافة (91.7 cm³) والاستنتاج أن الحجم يقل","القسمة على حجم الجليد بدل حجم الماء في النسبة المئوية","إهمال الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.158Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2120, null, null, null, 'معظم المواد كالبنزين: عند التجمد تتراص الجسيمات فيقل الحجم وتزداد الكثافة، فيغرق صلبها في سائلها. الماء: عند التجمد تنتظم الجزيئات بروابط هيدروجينية في ترتيب سداسي مفتوح فيزداد الحجم وتقل الكثافة، فيطفو الجليد. الأثر: تتكون طبقة الجليد على سطح البحيرات فتعزل الماء تحتها فيبقى سائلًا، فتستمر حياة الكائنات المائية في الشتاء.', '["معظم المواد: يقل الحجم وتزداد الكثافة","الماء: يزداد الحجم وتقل الكثافة","سبب شذوذ الماء","الأثر البيئي: عزل الماء تحت الجليد"]'::jsonb, '[]'::jsonb, '[{"element":"سلوك معظم المواد","marks":1},{"element":"سلوك الماء مع السبب","marks":2},{"element":"الأثر في الكائنات المائية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة مع السبب والأثر"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في السبب أو الأثر"},{"level":"1–2 درجة","description":"ذكر أن الجليد يطفو دون مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البنزين يطفو صلبه كالماء","عكس تغير الحجم","ذكر أثر غير صحيح (كتسريع تجمد البحيرة)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.158Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2121, 1, 'تقسم المواد الصلبة حسب ترتيب جسيماتها إلى متبلورة (بلورية) وغير متبلورة.', '["هذان نوعان من أنواع المواد المتبلورة الخمسة لا تقسيم حسب التبلور.","","هذان أيضًا من أنواع المواد المتبلورة لا تقسيم حسب التبلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.160Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2122, 0, 'المتبلورة جسيماتها مرتبة في شكل هندسي منتظم، وغير المتبلورة جسيماتها مرتبة عشوائيًا.', '["","اللون والشفافية لا يحددان ترتيب الجسيمات؛ فالزجاج شفاف وغير متبلور.","التوصيل الكهربائي خاصية تميز بعض أنواع المتبلورة كالفلزية، لا أساس التقسيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:02.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2123, 0, 'ملح الطعام NaCl مادة متبلورة أيونية، والزجاج مادة غير متبلورة.', '["","الألماس والكوارتز كلاهما متبلور.","الترتيب معكوس؛ فالزجاج غير متبلور والملح متبلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2124, 0, 'جسيمات المادة (ب) مرتبة عشوائيًا وتلين تدريجيًا عند التسخين، فهي مادة صلبة غير متبلورة.', '["","المادة المتبلورة بأنواعها منتظمة الجسيمات وتنصهر عند درجة محددة.","المواد الأيونية متبلورة منتظمة الترتيب، والمادة (ب) عشوائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2125, 0, 'عند التبريد السريع لا يتوافر للجسيمات وقت كافٍ لتنتظم في شكل بلوري، فتتكون مادة غير متبلورة.', '["","التسخين البطيء لا يحول المادة البلورية إلى غير متبلورة.","التبريد البطيء يعطي الجسيمات وقتًا لتنتظم فتتكون بلورات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2126, 2, 'تصنف المواد الصلبة المتبلورة إلى خمسة أنواع: ذرية، وجزيئية، وتساهمية شبكية، وأيونية، وفلزية.', '["الأنواع خمسة: ذرية، وجزيئية، وتساهمية شبكية، وأيونية، وفلزية.","النوعان (متبلورة وغير متبلورة) تقسيم للمواد الصلبة كلها لا للمتبلورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T11:15:02.161Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2127, 1, 'الفرق في ترتيب الجسيمات: منتظم متكرر في الكوارتز، وعشوائي في الزجاج.', '["المادتان تتكونان أساسًا من الذرات نفسها (Si وO).","","الزجاج مادة صلبة غير متبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2128, null, null, null, '1) المواد الصلبة المتبلورة (البلورية): جسيماتها مرتبة في شكل هندسي منتظم متكرر، مثل ملح الطعام NaCl والألماس. 2) المواد الصلبة غير المتبلورة: جسيماتها مرتبة ترتيبًا عشوائيًا غير منتظم، مثل الزجاج والمطاط.', '["تسمية النوعين","تعريف المتبلورة","تعريف غير المتبلورة","مثال لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية النوعين وتعريفهما","marks":2},{"element":"مثال المتبلورة","marks":1},{"element":"مثال غير المتبلورة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"النوعان معرّفان بمثالين صحيحين"},{"level":"3 درجات","description":"خطأ في مثال أو تعريف"},{"level":"1–2 درجة","description":"تسمية النوعين فقط"},{"level":"صفر","description":"ذكر أنواع المتبلورة الخمسة بدلًا منهما أو لا إجابة"}]'::jsonb, '["ذكر أيونية وفلزية مثلًا بدل النوعين","عدّ الزجاج مادة متبلورة","تعريف غير المتبلورة بأنها ليست صلبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T11:15:02.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2129, null, null, null, 'المتبلورة: جسيماتها مرتبة في شكل هندسي منتظم متكرر، وتنصهر عند درجة حرارة محددة، وتتكون عادة عندما تبرد المادة ببطء فتنتظم جسيماتها، ومثالها NaCl. غير المتبلورة: جسيماتها مرتبة عشوائيًا، وتلين تدريجيًا عند التسخين، وتتكون غالبًا عند التبريد السريع للمادة المنصهرة، ومثالها الزجاج.', '["ترتيب الجسيمات","السلوك عند التسخين","طريقة التكون","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"ترتيب الجسيمات","marks":2},{"element":"السلوك عند التسخين","marks":1},{"element":"طريقة التكون","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في المعايير مع مثالين"},{"level":"3–4 درجات","description":"نقص في معيار أو مثال"},{"level":"1–2 درجة","description":"مقارنة الترتيب فقط"},{"level":"صفر","description":"مقارنة خاطئة أو لا إجابة"}]'::jsonb, '["عكس السلوك عند التسخين","القول إن التبريد السريع ينتج بلورات","أمثلة خاطئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2130, null, null, null, 'متبلورة: ملح الطعام، والألماس، والسكر، والجليد. غير متبلورة: الزجاج، والمطاط، والبلاستيك. تعليل الزجاج: جسيماته مرتبة ترتيبًا عشوائيًا لا يتكرر بنمط هندسي منتظم، ولا ينصهر عند درجة محددة بل يلين تدريجيًا.', '["تصنيف المتبلورة الأربع","تصنيف غير المتبلورة الثلاث","تعليل تصنيف الزجاج بالترتيب العشوائي"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المتبلورة","marks":2},{"element":"تصنيف غير المتبلورة","marks":2},{"element":"تعليل الزجاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح كامل مع تعليل"},{"level":"3–4 درجات","description":"خطأ في مادة أو تعليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لنصف المواد"},{"level":"صفر","description":"تصنيف خاطئ أو لا إجابة"}]'::jsonb, '["عدّ الزجاج متبلورًا لشفافيته","عدّ الجليد غير متبلور","تعليل الزجاج بالشفافية أو الهشاشة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T11:15:02.162Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2131, 1, 'المواد المتبلورة مواد صلبة تترتب جسيماتها (ذرات أو أيونات أو جزيئات) في شكل هندسي منتظم ثلاثي الأبعاد يتكرر.', '["جسيمات المواد الصلبة كلها تربطها قوى تجاذب.","","هذا تعريف المواد الصلبة غير المتبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.164Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2132, 1, 'يسمى الترتيب الهندسي المنتظم المتكرر لجسيمات المادة المتبلورة الشبكة البلورية.', '["الرابطة التساهمية نوع من الروابط بين الذرات لا اسم للنمط الهندسي.","","السحابة الإلكترونية تصف منطقة وجود الإلكترونات حول النواة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.164Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2133, 0, 'السكر (C₁₂H₂₂O₁₁) مادة صلبة متبلورة جزيئية جسيماتها مرتبة بنمط منتظم.', '["","الزجاج جسيماته مرتبة عشوائيًا فهو غير متبلور.","المطاط مادة غير متبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2134, 2, 'للمادة المتبلورة درجة انصهار محددة لانتظام ترتيب جسيماتها.', '["هذا سلوك المواد غير المتبلورة كالزجاج.","المواد المتبلورة تنصهر إذا سُخنت إلى درجة انصهارها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2135, 2, 'تتكون الشبكة البلورية من ذرات (كالألماس) أو أيونات (كـ NaCl) أو جزيئات (كالسكر والجليد).', '["الشبكة البلورية تتكون من جسيمات المادة لا من الهواء.","الإلكترونات الحرة جزء من الفلزات فقط، ولا تكوّن الشبكة وحدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2136, 2, 'المادة (أ) تنصهر عند درجة حرارة محددة (801 °C)، وهذه صفة المادة المتبلورة المنتظمة الجسيمات، أما (ب) فتلين على مدى واسع فهي غير متبلورة.', '["الليونة التدريجية على مدى من درجات الحرارة صفة المادة غير المتبلورة.","سلوك المادتين مختلف، فلا يمكن أن تنتميا إلى النوع نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2137, 1, 'الزجاج غير متبلور لأن جسيماته مرتبة عشوائيًا ولا يتكرر فيها نمط هندسي منتظم.', '["الزجاج يلين تدريجيًا ولا ينصهر عند درجة محددة.","","الصلابة والشفافية لا تحددان التبلور؛ فالمعيار ترتيب الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2138, null, null, null, 'المواد الصلبة المتبلورة: مواد صلبة تترتب جسيماتها (ذرات أو أيونات أو جزيئات) في شكل هندسي منتظم ثلاثي الأبعاد يتكرر يسمى الشبكة البلورية. ومن أمثلتها: ملح الطعام NaCl، والسكر، والألماس، والكوارتز.', '["مواد صلبة","جسيمات مرتبة في شكل هندسي منتظم متكرر","مثال أول صحيح","مثال ثان صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومثالان صحيحان"},{"level":"3 درجات","description":"تعريف صحيح ومثال واحد"},{"level":"1–2 درجة","description":"تعريف ناقص أو مثالان دون تعريف"},{"level":"صفر","description":"تعريف غير المتبلورة أو لا إجابة"}]'::jsonb, '["إغفال صفة الانتظام والتكرار","التمثيل بالزجاج أو البلاستيك","تعريف المتبلورة بالصلابة أو الشفافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.165Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2139, null, null, null, 'في المادة المتبلورة تترتب الجسيمات ترتيبًا منتظمًا متكررًا، فتكون قوى التجاذب بينها متماثلة في أجزاء البلورة كلها، فتحتاج إلى الطاقة نفسها للتغلب عليها، فتنصهر عند درجة حرارة محددة. أما في المادة غير المتبلورة فالجسيمات مرتبة عشوائيًا فتختلف قوى التجاذب من موضع إلى آخر، فتتحرر الجسيمات تدريجيًا على مدى من درجات الحرارة فتلين المادة تدريجيًا.', '["الترتيب المنتظم في المتبلورة","تماثل قوى التجاذب ← درجة انصهار محددة","الترتيب العشوائي في غير المتبلورة","اختلاف القوى ← ليونة تدريجية"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير المتبلورة","marks":2},{"element":"تفسير غير المتبلورة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالتين"},{"level":"3 درجات","description":"تفسير إحداهما كاملًا والأخرى ناقصًا"},{"level":"1–2 درجة","description":"ذكر الترتيب دون ربطه بالانصهار"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن المادة غير المتبلورة لا تنصهر إطلاقًا","ربط الانصهار باللون أو الشفافية","عكس سلوك المادتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2140, null, null, null, 'الشبكة البلورية: الترتيب الهندسي المنتظم ثلاثي الأبعاد المتكرر لجسيمات المادة الصلبة. علاقتها بالتعريف: المادة المتبلورة هي المادة التي تترتب جسيماتها في شبكة بلورية، فوجود الشبكة هو ما يميزها. بلورات ملح الطعام منتظمة الشكل لأن أيونات Na⁺ وCl⁻ تترتب بنمط منتظم يتكرر في الأبعاد الثلاثة، فينعكس هذا الانتظام الداخلي على الشكل الخارجي للبلورة.', '["تعريف الشبكة البلورية","الربط بتعريف المادة المتبلورة","تفسير انتظام بلورات الملح بترتيب الأيونات المتكرر"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الشبكة البلورية","marks":1},{"element":"الربط بالتعريف","marks":1},{"element":"تفسير شكل بلورات الملح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة مترابطة"},{"level":"3 درجات","description":"نقص في الربط أو التفسير"},{"level":"1–2 درجة","description":"تعريف الشبكة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الشبكة البلورية والجزيء الواحد","تفسير شكل البلورة بطريقة الطحن أو القطع","عدّ ملح الطعام مكونًا من جزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.166Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2141, 1, 'كلوريد الصوديوم مادة صلبة متبلورة أيونية تترتب أيوناتها في شبكة بلورية منتظمة.', '["الزجاج مادة صلبة غير متبلورة.","","المطاط مادة صلبة غير متبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.168Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2142, 0, 'الألماس (تساهمي شبكي) والسكر والجليد (جزيئيان) كلها مواد صلبة متبلورة.', '["","المطاط والبلاستيك مادتان غير متبلورتين.","الزجاج مادة غير متبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T11:15:02.168Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2143, 0, 'الكوارتز SiO₂ والألماس مثالان على المواد الصلبة المتبلورة التساهمية الشبكية.', '["","الكوارتز ليس فلزًا ولا يحتوي على إلكترونات حرة.","الكوارتز لا يتكون من أيونات؛ فذراته مرتبطة بروابط تساهمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.168Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2144, 1, 'KBr يتكون من أيونات K⁺ وBr⁻، فهو مثال على المواد المتبلورة الأيونية مثل NaCl وCaCO₃.', '["اليود الصلب مادة متبلورة جزيئية.","","الألماس مادة متبلورة تساهمية شبكية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:02.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2145, 2, 'جميع العناصر الفلزية كالنحاس أمثلة على المواد الصلبة المتبلورة الفلزية.', '["النحاس عنصر واحد لا يتكون من أيونات موجبة وسالبة.","النحاس عنصر فلزي لا يتكون من جزيئات منفصلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2146, 2, 'المواد الصلبة الذرية تتكون من ذرات عناصر المجموعة 18، مثل الأرجون الصلب.', '["كربونات الكالسيوم مادة متبلورة أيونية.","CO₂ الصلب مادة متبلورة جزيئية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T11:15:02.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2147, 1, 'الجليد والسكر واليود مواد صلبة متبلورة جزيئية، أما الزجاج فمادة غير متبلورة.', '["اليود مادة متبلورة جزيئية كبقية المجموعة.","","الجليد مادة متبلورة جزيئية كبقية المجموعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.169Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2148, null, null, null, 'الذرية: الأرجون الصلب (عناصر المجموعة 18). الجزيئية: الجليد H₂O أو السكر أو اليود I₂ أو CO₂ الصلب أو NH₃. التساهمية الشبكية: الألماس C أو الكوارتز SiO₂. الأيونية: كلوريد الصوديوم NaCl أو KBr أو CaCO₃. الفلزية: النحاس أو أي عنصر فلزي.', '["مثال ذري","مثال جزيئي","مثال تساهمي شبكي","مثال أيوني","مثال فلزي"]'::jsonb, '[]'::jsonb, '[{"element":"الذرية","marks":1},{"element":"الجزيئية","marks":1},{"element":"التساهمية الشبكية","marks":1},{"element":"الأيونية","marks":1},{"element":"الفلزية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خمسة أمثلة صحيحة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة أمثلة صحيحة"},{"level":"1–2 درجة","description":"مثال أو مثالان"},{"level":"صفر","description":"أمثلة خاطئة أو لا إجابة"}]'::jsonb, '["التمثيل للجزيئية بـ NaCl","التمثيل بمواد غير متبلورة كالزجاج","التمثيل للذرية بعنصر فلزي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2149, null, null, null, 'متبلورة: KBr (أيونية)، الثلج الجاف CO₂ (جزيئية)، الحديد Fe (فلزية)، الكوارتز SiO₂ (تساهمية شبكية). غير متبلورة: البلاستيك، والشمع.', '["تحديد المتبلورة الأربع","تحديد غير المتبلورة","نوع KBr","نوع CO₂","نوع Fe","نوع SiO₂"]'::jsonb, '[]'::jsonb, '[{"element":"التصنيف إلى متبلورة وغير متبلورة","marks":2},{"element":"أنواع المواد المتبلورة","marks":4}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف صحيح وأنواع صحيحة للأربع"},{"level":"4–5 درجات","description":"خطأ في نوع واحد أو مادتين"},{"level":"2–3 درجات","description":"تصنيف صحيح دون أنواع"},{"level":"صفر","description":"تصنيف خاطئ أو لا إجابة"}]'::jsonb, '["عدّ الثلج الجاف أيونيًا","عدّ الكوارتز جزيئيًا","عدّ البلاستيك متبلورًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2150, null, null, null, 'العبارة خاطئة جزئيًا: الجليد والسكر مادتان صلبتان متبلورتان فعلًا لكنهما جزيئيتان لا أيونيتان؛ لأن جسيماتهما جزيئات متعادلة (H₂O وC₁₂H₂₂O₁₁) لا أيونات. الصياغة الصحيحة: «الجليد والسكر مثالان على المواد الصلبة المتبلورة الجزيئية». ومن أمثلة المتبلورة الأيونية: كلوريد الصوديوم NaCl، وبروميد البوتاسيوم KBr، وكربونات الكالسيوم CaCO₃.', '["تحديد الخطأ: النوع جزيئي لا أيوني","التعليل: جسيماتهما جزيئات متعادلة","الصياغة الصحيحة","مثالان صحيحان على الأيونية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ مع التعليل","marks":2},{"element":"الصياغة الصحيحة","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصحيح وتعليل ومثالان صحيحة"},{"level":"3 درجات","description":"تصحيح وتعليل دون أمثلة كاملة"},{"level":"1–2 درجة","description":"تصحيح دون تعليل"},{"level":"صفر","description":"قبول العبارة أو لا إجابة"}]'::jsonb, '["عدّ الجليد والسكر غير متبلورين","التمثيل للأيونية بالسكر","إغفال التعليل بنوع الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.170Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2151, 1, 'المواد الصلبة غير المتبلورة تترتب جسيماتها بشكل عشوائي غير منتظم ولا يوجد فيها نمط هندسي متكرر.', '["هذا وصف المواد المتبلورة.","","المواد غير المتبلورة صلبة لها شكل ثابت ولا تنساب كالموائع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:02.172Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2152, 2, 'عند التبريد السريع لا يتوافر للجسيمات الوقت الكافي لتنتظم في شكل بلوري، فتبقى عشوائية الترتيب.', '["التبريد البطيء يسمح للجسيمات بالانتظام في بلورات.","التسخين البطيء لا يكوّن مادة صلبة جديدة غير متبلورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.173Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2153, 1, 'ليس للمادة غير المتبلورة درجة انصهار محددة، بل تلين تدريجيًا عند التسخين.', '["الانصهار عند درجة محددة صفة المواد المتبلورة.","","التحول المباشر إلى غاز هو التسامي، وليس سلوكًا عامًا للمواد غير المتبلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.173Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2154, 0, 'المادة تلين تدريجيًا وتتحول إلى سائل لزج على مدى واسع من درجات الحرارة دون درجة انصهار محددة، وهذه صفة المادة غير المتبلورة.', '["","الفلزات متبلورة تنصهر عند درجة حرارة محددة.","المواد الأيونية متبلورة تنصهر عند درجة حرارة محددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.173Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2155, 0, 'المواد غير المتبلورة مواد صلبة لها شكل وحجم ثابتان، لكن جسيماتها مرتبة عشوائيًا.', '["","المواد غير المتبلورة لا تنساب في الظروف العادية ولها شكل ثابت.","عدم انتظام الترتيب لا ينفي كونها صلبة؛ فهو يحدد نوع الصلب فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:02.173Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2156, 0, 'الترتيب العشوائي يجعل قوى التجاذب مختلفة من موضع إلى آخر، فتتحرر الجسيمات تدريجيًا على مدى من درجات الحرارة.', '["","الترتيب المنتظم صفة المادة المتبلورة ذات درجة الانصهار المحددة.","لو لم توجد قوى تجاذب لما كانت المادة صلبة أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.174Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2157, 2, 'التبريد السريع لم يمنح جزيئات السكر وقتًا كافيًا للانتظام، فتكونت مادة صلبة عشوائية الترتيب غير متبلورة.', '["الشفافية لا تنفي كون المادة صلبة.","المادة نفسها قد تكون متبلورة أو غير متبلورة بحسب طريقة تبريدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.175Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2158, null, null, null, 'المواد الصلبة غير المتبلورة: مواد صلبة تترتب جسيماتها بشكل عشوائي غير منتظم، ولا يوجد فيها نمط هندسي متكرر. وتتكون غالبًا عندما تبرد المادة المنصهرة بسرعة، فلا يتوافر لجسيماتها الوقت الكافي لتنتظم في شكل بلوري.', '["مواد صلبة","ترتيب عشوائي دون نمط متكرر","التكون بالتبريد السريع","عدم توافر الوقت لانتظام الجسيمات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"طريقة التكون مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وتفسير التكون"},{"level":"3 درجات","description":"تعريف صحيح وتكون دون تعليل"},{"level":"1–2 درجة","description":"تعريف ناقص"},{"level":"صفر","description":"تعريف المتبلورة أو لا إجابة"}]'::jsonb, '["عدّ غير المتبلورة مواد غير صلبة","القول إنها تتكون بالتبريد البطيء","إغفال صفة العشوائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-11T11:15:02.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2159, null, null, null, 'المادة المتبلورة تنصهر عند درجة حرارة محددة، أما غير المتبلورة فتلين تدريجيًا على مدى من درجات الحرارة. السبب: في المتبلورة تترتب الجسيمات بانتظام فتتماثل قوى التجاذب في البلورة كلها فتتحرر الجسيمات عند درجة حرارة واحدة، أما في غير المتبلورة فالترتيب عشوائي فتتفاوت قوى التجاذب فتتحرر الجسيمات تدريجيًا.', '["المتبلورة: درجة انصهار محددة","غير المتبلورة: ليونة تدريجية","التفسير بانتظام الترتيب وتماثل القوى","التفسير بالعشوائية وتفاوت القوى"]'::jsonb, '[]'::jsonb, '[{"element":"وصف السلوكين","marks":2},{"element":"تفسير الاختلاف","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة وتفسير كاملان"},{"level":"3 درجات","description":"مقارنة صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"وصف سلوك مادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس سلوك المادتين","القول إن غير المتبلورة لا تنصهر أبدًا","تفسير الفرق بالكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2160, null, null, null, '(أ) المادة (أ) متبلورة، والمادة (ب) غير متبلورة. (ب) المادة (أ) لها درجة انصهار محددة (80 °C) تبقى عندها الحرارة ثابتة أثناء الانصهار، وهذه صفة المواد المتبلورة المنتظمة الترتيب؛ أما (ب) فليس لها درجة انصهار محددة بل تلين تدريجيًا، وهذه صفة المواد غير المتبلورة عشوائية الترتيب. (ج) الزجاج أو البلاستيك أو الشمع.', '["(أ) متبلورة","(ب) غير متبلورة","التعليل بدرجة الانصهار المحددة","التعليل بالليونة التدريجية","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النوعين","marks":2},{"element":"التعليل","marks":2},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد وتعليل ومثال صحيحة"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل ناقص أو مثال خاطئ"},{"level":"1–2 درجة","description":"تحديد نوع واحد صحيح"},{"level":"صفر","description":"تحديد معكوس أو لا إجابة"}]'::jsonb, '["عكس نوعي المادتين","التمثيل للمادة (ب) بملح الطعام","تعليل دون الإشارة إلى درجة الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T11:15:02.176Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
