(2167, 2, 'البلاستيك من المواد الصلبة غير المتبلورة.', '["الملح الصخري (NaCl) مادة متبلورة أيونية.","النحاس مادة متبلورة فلزية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T11:15:02.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2168, null, null, null, 'من أمثلتها: الزجاج، والمطاط، والبلاستيك (والشمع). الخاصية المشتركة: جسيماتها مرتبة ترتيبًا عشوائيًا لا يتكرر بنمط هندسي منتظم، وليس لها درجة انصهار محددة بل تلين تدريجيًا عند التسخين.', '["ثلاثة أمثلة صحيحة","الترتيب العشوائي","الليونة التدريجية عند التسخين"]'::jsonb, '[]'::jsonb, '[{"element":"الأمثلة الثلاثة","marks":3},{"element":"الخاصية المشتركة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ثلاثة أمثلة صحيحة وخاصيتان مشتركتان"},{"level":"3–4 درجات","description":"أمثلة صحيحة مع خاصية واحدة"},{"level":"1–2 درجة","description":"مثال أو مثالان فقط"},{"level":"صفر","description":"أمثلة متبلورة أو لا إجابة"}]'::jsonb, '["التمثيل بالسكر أو الملح","عدّ الكوارتز غير متبلور","ذكر الشفافية خاصية مشتركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2169, null, null, null, 'غير متبلورة: زجاج النافذة، والكيس البلاستيكي، والشمعة. متبلورة: خاتم الذهب (فلزية)، وبلورة السكر (جزيئية)، والملح الصخري (أيونية). تعليل الكيس البلاستيكي: البلاستيك جسيماته مرتبة ترتيبًا عشوائيًا دون نمط هندسي متكرر، ويلين تدريجيًا عند التسخين.', '["تصنيف غير المتبلورة الثلاث","تصنيف المتبلورة الثلاث","تعليل البلاستيك"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف غير المتبلورة","marks":2},{"element":"تصنيف المتبلورة","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح كامل مع تعليل"},{"level":"3–4 درجات","description":"خطأ في مادة أو تعليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لنصف الأشياء"},{"level":"صفر","description":"تصنيف خاطئ أو لا إجابة"}]'::jsonb, '["عدّ الذهب غير متبلور لأنه يلين عند الطرق","عدّ الزجاج متبلورًا","تعليل البلاستيك بخفته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T11:15:02.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2170, null, null, null, 'العبارة خاطئة؛ فالصلابة والشفافية والملمس ليست معيارًا للتبلور. المعيار هو ترتيب الجسيمات، وجسيمات الزجاج مرتبة ترتيبًا عشوائيًا لا يتكرر، كما أنه يلين تدريجيًا ولا ينصهر عند درجة محددة، فهو مادة صلبة غير متبلورة. ومن الفئة نفسها: المطاط، والبلاستيك.', '["الحكم: العبارة خاطئة","المعيار ترتيب الجسيمات لا الصفات الظاهرية","الزجاج عشوائي الترتيب فهو غير متبلور","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل","marks":2},{"element":"تصنيف الزجاج الصحيح","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتعليل ومثالان صحيحة"},{"level":"3 درجات","description":"حكم صحيح بتعليل ناقص"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"قبول العبارة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الزجاج صلب","التمثيل بالكوارتز من الفئة نفسها","تعليل بالشفافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.180Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
