(2172, 0, 'البلورة تتكون من تكرار وحدة البناء في الأبعاد الثلاثة.', '["","المواد غير المتبلورة ليس فيها نمط متكرر ولا وحدة بناء.","العلاقة معكوسة؛ فالبلورة هي التي تتكون من وحدات البناء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2173, 2, 'الوحدة التي فيها جسيمات في الأركان وفي مراكز الأوجه هي المكعب المتمركز الوجه، كما في الجدول.', '["جسيماته في الأركان فقط.","فيه جسيم واحد في مركز المكعب لا في مراكز الأوجه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2174, 1, 'من أشكال وحدات البناء المكعبة: المكعب البسيط، والمكعب المتمركز الجسم، والمكعب المتمركز الوجه.', '["هذه أشكال الجزيئات لا وحدات البناء.","","هذه أنواع المواد الصلبة المتبلورة لا أشكال وحدات البناء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2175, 2, 'وحدة البناء أصغر ترتيب متكرر في الشبكة البلورية، والمواد غير المتبلورة جسيماتها عشوائية فلا وحدة بناء لها.', '["الترتيب العشوائي لا يحتوي على وحدة تتكرر مهما كبر حجمها.","وحدة البناء خاصة بالمواد المتبلورة ذات الترتيب المتكرر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:02.183Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2176, 1, 'وحدة البناء في NaCl ترتيب صغير من أيونات Na⁺ وCl⁻ يتكرر في الأبعاد الثلاثة لتكوين البلورة.', '["وحدة البناء ترتيب لعدة جسيمات يتكرر، لا ذرة واحدة معزولة.","","NaCl مركب أيوني لا يتكون من جزيئات منفصلة، وهذا خلط بين وحدة البناء والجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T11:15:02.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2177, 2, 'كما تُغطى الأرضية بتكرار قطعة البلاط نفسها، تتكون البلورة بتكرار وحدة البناء نفسها في الأبعاد الثلاثة.', '["الذوبان لا علاقة له بتكرار نمط منتظم.","التبعثر العشوائي يشبه المواد غير المتبلورة لا البلورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2178, null, null, null, 'وحدة البناء: أصغر ترتيب للذرات (أو الجسيمات) في الشبكة البلورية، ويحمل التماثل نفسه الموجود في البلورة كلها. العلاقة: تتكون الشبكة البلورية (البلورة) من تكرار وحدة البناء في الأبعاد الثلاثة.', '["أصغر ترتيب للذرات","في الشبكة البلورية","تحمل تماثل البلورة","البلورة تتكون من تكرارها في ثلاثة أبعاد"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"العلاقة بالشبكة البلورية","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وعلاقة صحيحة"},{"level":"3 درجات","description":"تعريف صحيح وعلاقة ناقصة"},{"level":"1–2 درجة","description":"تعريف ناقص"},{"level":"صفر","description":"الخلط بين وحدة البناء والجزيء أو لا إجابة"}]'::jsonb, '["تعريف وحدة البناء بأنها جزيء واحد","القول إنها أكبر وحدة في البلورة","إغفال التكرار في الأبعاد الثلاثة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T11:15:02.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2179, null, null, null, 'في المواد المتبلورة تترتب الجسيمات في نمط هندسي منتظم يتكرر في الأبعاد الثلاثة، فيمكن تحديد أصغر ترتيب يتكرر وهو وحدة البناء. أما المواد غير المتبلورة فجسيماتها مرتبة عشوائيًا دون نمط متكرر، فلا يوجد ترتيب صغير يتكرر بانتظام يمكن عدّه وحدة بناء.', '["المتبلورة: نمط منتظم متكرر","وحدة البناء أصغر ترتيب متكرر","غير المتبلورة: ترتيب عشوائي بلا تكرار","النتيجة: لا وحدة بناء لغير المتبلورة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير المتبلورة","marks":2},{"element":"تفسير غير المتبلورة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالتين"},{"level":"3 درجات","description":"تفسير إحداهما كاملًا والأخرى ناقصًا"},{"level":"1–2 درجة","description":"ذكر الفرق في الترتيب دون ربط بوحدة البناء"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كل مادة صلبة لها وحدة بناء","ربط وحدة البناء بالصلابة","الخلط بين وحدة البناء والجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-11T11:15:02.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2180, null, null, null, '1) المكعب البسيط: الجسيمات في الأركان الثمانية للمكعب فقط. 2) المكعب المتمركز الجسم: جسيمات في الأركان الثمانية وجسيم في مركز المكعب. 3) المكعب المتمركز الوجه: جسيمات في الأركان الثمانية وجسيم في مركز كل وجه من الأوجه الستة.', '["المكعب البسيط ومواقعه","المكعب المتمركز الجسم ومواقعه","المكعب المتمركز الوجه ومواقعه"]'::jsonb, '[]'::jsonb, '[{"element":"المكعب البسيط","marks":2},{"element":"المتمركز الجسم","marks":2},{"element":"المتمركز الوجه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأشكال الثلاثة بأوصاف صحيحة"},{"level":"4–5 درجات","description":"الأشكال الثلاثة مع خطأ في وصف واحد"},{"level":"2–3 درجات","description":"تسمية الأشكال دون أوصاف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين المتمركز الجسم والمتمركز الوجه","ذكر أشكال الجزيئات (خطي، هرمي)","إغفال الجسيمات في الأركان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T11:15:02.184Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2181, 0, 'أساس تصنيف المواد الصلبة البلورية هو نوع الجسيمات المكونة لها (ذرات، جزيئات، أيونات...) ونوع الروابط أو القوى التي تربط بينها.', '["","اللون ودرجة الانصهار خصائص ناتجة عن التصنيف لا أساس له، واللون لا علاقة له بنوع البلورة.","حجم البلورة وكتلتها المولية لا يحددان نوع الصلب البلوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.186Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2182, 2, 'الكوارتز SiO2 شبكة متصلة من ذرات السيليكون والأكسجين المرتبطة بروابط تساهمية، لذا فهو صلب تساهمي شبكي صلب جدًا مرتفع درجة الانصهار.', '["كتابة صيغة SiO2 تشبه CO2 فيظن الطالب أنه جزيئي، لكن SiO2 لا يتكون من جزيئات منفصلة.","SiO2 مكون من لافلزين مرتبطين تساهميًا لا من أيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T11:15:02.187Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2183, 2, 'اليود I2 وثاني أكسيد الكربون الصلب CO2 والسكروز C12H22O11 كلها تتكون من جزيئات تربطها قوى بين جزيئية، فهي مواد صلبة جزيئية.', '["الألماس وSiO2 تساهمية شبكية، والحديد Fe صلب فلزي.","هذه مواد صلبة أيونية تتكون من أيونات موجبة وسالبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.187Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2184, 1, 'المادة (ج) قابلة للطرق والسحب وممتازة التوصيل الكهربائي في الحالة الصلبة، وهذه خصائص المواد الصلبة الفلزية.', '["المادة (ب) صلبة جدًا مرتفعة الانصهار رديئة التوصيل، وهذه خصائص الصلب التساهمي الشبكي.","","المادة (د) صلبة هشة لا توصل وهي صلبة، وهذه خصائص الصلب الأيوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.187Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2185, 0, 'جسيمات الصلب الذري ذرات الغازات النبيلة، وتربطها قوى تشتت ضعيفة، لذا يكون لينًا جدًا منخفض درجة الانصهار رديء التوصيل.', '["","الصلب التساهمي الشبكي ذراته مرتبطة بروابط تساهمية قوية، لا بقوى تشتت ضعيفة.","الذرات النبيلة لا تملك إلكترونات حرة كالفلزات، فهي رديئة التوصيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.187Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2186, 2, 'الصلب الأيوني يتكون من أيونات موجبة وسالبة مرتبة بانتظام تربطها روابط أيونية قوية، بينما الجليد يتكون من جزيئات H2O متعادلة.', '["هذا وصف الصلب الفلزي.","هذا وصف الصلب الجزيئي (كالجليد) لا الأيوني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2187, 1, 'الصلابة مع الهشاشة وارتفاع درجة الانصهار وعدم التوصيل في الحالة الصلبة خصائص المواد الأيونية مثل CaCO3.', '["السكروز صلب جزيئي متوسط اللين، وينصهر عند درجة أقل نسبيًا من الأيونية.","","النحاس فلز قابل للطرق ممتاز التوصيل وليس هشًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2188, null, null, null, 'NaCl: صلب أيوني، جسيماته أيونات موجبة وسالبة. الألماس: صلب تساهمي شبكي، جسيماته ذرات مرتبطة بروابط تساهمية في شبكة متصلة. Fe: صلب فلزي، جسيماته أيونات فلزية موجبة محاطة بإلكترونات حرة. الجليد H2O: صلب جزيئي، جسيماته جزيئات. Ar الصلب: صلب ذري، جسيماته ذرات غاز نبيل.', '["NaCl أيوني (أيونات)","الألماس تساهمي شبكي (ذرات بروابط تساهمية)","Fe فلزي (أيونات موجبة وإلكترونات حرة)","H2O جزيئي (جزيئات)","Ar ذري (ذرات المجموعة 18)"]'::jsonb, '[]'::jsonb, '[{"element":"NaCl","marks":1},{"element":"الألماس","marks":1},{"element":"Fe","marks":1},{"element":"H2O","marks":1},{"element":"Ar","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمواد الخمس مع نوع الجسيمات"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاث أو أربع مواد"},{"level":"1–2 درجة","description":"تصنيف صحيح لمادة أو مادتين"},{"level":"صفر","description":"لا تصنيف صحيح"}]'::jsonb, '["تصنيف الألماس صلبًا جزيئيًا","تصنيف Ar صلبًا جزيئيًا بدل ذري","وصف جسيمات الفلز بأنها ذرات متعادلة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2189, null, null, null, 'الصلب الجزيئي: جسيماته جزيئات منفصلة تربطها قوى بين جزيئية ضعيفة نسبيًا، فهو متوسط اللين منخفض درجة الانصهار نسبيًا، مثل اليود I2 أو السكر. الصلب التساهمي الشبكي: جسيماته ذرات ترتبط جميعها بروابط تساهمية قوية في شبكة متصلة، فهو صلب جدًا مرتفع درجة الانصهار، مثل الألماس أو الكوارتز SiO2.', '["الجزيئي: جزيئات ↔ الشبكي: ذرات","الجزيئي: قوى بين جزيئية ضعيفة ↔ الشبكي: روابط تساهمية قوية","الجزيئي: لين نسبيًا وانصهار منخفض ↔ الشبكي: صلب جدًا وانصهار مرتفع","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الجسيمات","marks":1},{"element":"قوة الترابط","marks":1},{"element":"الصلابة ودرجة الانصهار","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة في البنود الثلاثة مع مثالين صحيحين"},{"level":"3 درجات","description":"مقارنة صحيحة مع نقص بند واحد"},{"level":"2 درجتان","description":"بندان صحيحان"},{"level":"1 درجة","description":"بند أو مثال واحد صحيح"},{"level":"صفر","description":"لا مقارنة صحيحة"}]'::jsonb, '["الظن أن الروابط داخل جزيء I2 هي التي تنكسر عند الانصهار","عدّ SiO2 صلبًا جزيئيًا مثل CO2","الخلط بين الصلب التساهمي الشبكي والأيوني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.188Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2190, null, null, null, '(س) صلب فلزي، الدليل: اللمعان وقابلية الطرق والتوصيل الكهربائي في الحالة الصلبة. (ص) صلب تساهمي شبكي، الدليل: صلابة شديدة ودرجة انصهار مرتفعة جدًا وعدم التوصيل. (ع) صلب أيوني، الدليل: الهشاشة وعدم التوصيل وهو صلب، وتوصيل محلوله لتحرر أيوناته وحركتها في الماء.', '["(س) فلزي مع الدليل","(ص) تساهمي شبكي مع الدليل","(ع) أيوني مع الدليل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (س) ودليله","marks":2},{"element":"تصنيف (ص) ودليله","marks":2},{"element":"تصنيف (ع) ودليله","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف صحيح للعينات الثلاث مع الأدلة"},{"level":"4–5 درجات","description":"تصنيف صحيح للثلاث مع نقص في دليل أو تصنيف اثنتين بأدلة كاملة"},{"level":"2–3 درجات","description":"تصنيف صحيح لعينة أو اثنتين بأدلة ناقصة"},{"level":"1 درجة","description":"تصنيف صحيح لعينة واحدة بلا دليل"},{"level":"صفر","description":"لا تصنيف صحيح"}]'::jsonb, '["تصنيف (ع) جزيئيًا لعدم توصيلها وهي صلبة وإغفال توصيل محلولها","تصنيف (ص) أيونيًا لارتفاع درجة انصهارها","ذكر التصنيف دون الدليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.189Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2191, 0, 'التآصل وجود العنصر الواحد في أكثر من شكل (تركيب) في الحالة الفيزيائية نفسها، وتسمى هذه الأشكال المتآصلات.', '["","هذا تعريف النظائر لا التآصل.","هذا تعريف التسامي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T11:15:02.191Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2192, 2, 'الألماس والجرافيت والبكمنستر فوليرين أشكال مختلفة لعنصر الكربون وحده في الحالة الصلبة، فهي متآصلات الكربون.', '["الكوارتز SiO2 وكربيد السيليكون مركبات تحتوي عناصر أخرى غير الكربون.","CO2 وCO مركبان من عنصرين لا شكلان لعنصر واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.191Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2193, 2, 'التآصل خاص بالعناصر وفي الحالة الفيزيائية نفسها، أما الماء فمركب، وأشكاله الثلاثة حالات فيزيائية مختلفة لا متآصلات.', '["صيغتها الكيميائية واحدة H2O في الحالات الثلاث.","جميعها جزيئات H2O متطابقة، ولا اختلاف في عدد البروتونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T11:15:02.191Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2194, 1, 'كلا المتآصلين مكون من ذرات الكربون فقط، لكن ترتيب الذرات وطريقة ارتباطها في البلورة مختلف، فتختلف خصائصهما الفيزيائية.', '["كلاهما مكون من ذرات كربون فقط، فلا اختلاف في نوع الذرات.","","عدد البروتونات ثابت (6) في كل ذرات الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.191Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2195, 0, 'O2 وO3 شكلان مختلفان لعنصر الأكسجين في الحالة الغازية نفسها، فهما متآصلان.', '["","مادتان مختلفتان (مركبان مختلفان) لا شكلان لعنصر واحد.","الكربون-12 والكربون-14 نظيران يختلفان في عدد النيوترونات، لا متآصلان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2196, 2, 'الشكلان لعنصر واحد في الحالة الفيزيائية نفسها (الصلبة) مع اختلاف ترتيب الذرات، وهذا هو التآصل.', '["المركب يتكون من عنصرين أو أكثر، والشكلان هنا لعنصر واحد.","كلا الشكلين في الحالة الصلبة، فهي حالة فيزيائية واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2197, 1, 'يُظهر الجدول اختلاف الألماس والجرافيت في الصلابة والتوصيل الكهربائي، وهي خصائص فيزيائية، رغم أن كليهما كربون، فالمتآصلات تختلف في بعض خصائصها الفيزيائية.', '["الجدول يعرض خصائص فيزيائية مختلفة (الصلابة والتوصيل)، لا كيميائية.","","الجدول يبين اختلافًا واضحًا في الصلابة والتوصيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T11:15:02.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2198, null, null, null, 'التآصل: وجود العنصر الواحد بأكثر من شكل في الحالة الفيزيائية نفسها. متآصلات الكربون: الألماس، والجرافيت، والبكمنستر فوليرين.', '["التعريف: أكثر من شكل للعنصر","في الحالة الفيزيائية نفسها","الألماس","الجرافيت","البكمنستر فوليرين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف كاملًا","marks":2},{"element":"المتآصلات الثلاثة","marks":3}]'::jsonb, '[{"level":"5 درجات","description":"تعريف كامل يشمل قيد الحالة الفيزيائية نفسها مع ثلاثة متآصلات صحيحة"},{"level":"4 درجات","description":"تعريف ناقص قيد الحالة مع ثلاثة متآصلات، أو تعريف كامل مع متآصلين"},{"level":"2–3 درجات","description":"تعريف صحيح فقط أو متآصلات صحيحة مع تعريف خاطئ"},{"level":"1 درجة","description":"متآصل واحد صحيح أو تعريف ناقص"},{"level":"صفر","description":"إجابة خاطئة"}]'::jsonb, '["إغفال قيد «الحالة الفيزيائية نفسها»","الخلط بين التآصل والنظائر","ذكر CO2 أو الفحم الحجري ضمن متآصلات الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T11:15:02.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2199, null, null, null, 'التآصل: يختلف فيه ترتيب ذرات العنصر وطريقة ارتباطها (اختلاف في التركيب/البناء)، والذرات نفسها متماثلة، مثل الألماس والجرافيت للكربون. النظائر: تختلف فيها ذرات العنصر نفسه في عدد النيوترونات (اختلاف على مستوى الذرة الواحدة)، مثل الكربون-12 والكربون-14.', '["التآصل: اختلاف ترتيب الذرات وارتباطها","النظائر: اختلاف عدد النيوترونات","التآصل على مستوى التركيب، والنظائر على مستوى الذرة","مثال صحيح لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"ما يختلف في التآصل","marks":1},{"element":"ما يختلف في النظائر","marks":1},{"element":"مستوى الاختلاف","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة مع مثالين"},{"level":"3 درجات","description":"مقارنة صحيحة مع نقص عنصر واحد"},{"level":"2 درجتان","description":"تمييز صحيح لأحدهما مع مثال"},{"level":"1 درجة","description":"مثال صحيح فقط"},{"level":"صفر","description":"خلط تام بين المفهومين"}]'::jsonb, '["القول إن المتآصلات تختلف في عدد البروتونات","عدّ O2 وO3 نظيرين","عدّ الكربون-12 والكربون-14 متآصلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.192Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2200, null, null, null, 'العبارة غير دقيقة: الجرافيت والألماس ليسا مادتين مختلفتين في التركيب الكيميائي، فكلاهما يتكون من ذرات الكربون فقط، وهما متآصلان للكربون (شكلان للعنصر نفسه في الحالة الصلبة). أما اختلاف الصلابة فسببه اختلاف ترتيب ذرات الكربون وطريقة ارتباطها في كل منهما، لا اختلاف نوع الذرات.', '["الحكم: العبارة غير صحيحة/غير دقيقة","كلاهما من ذرات الكربون فقط","هما متآصلان للكربون في الحالة الصلبة","سبب اختلاف الخصائص: ترتيب الذرات وارتباطها"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"كلاهما كربون","marks":1},{"element":"تسميتهما متآصلين","marks":1},{"element":"تفسير اختلاف الصلابة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تبرير كامل يشمل التآصل وسبب اختلاف الخصائص"},{"level":"3 درجات","description":"حكم وتبرير صحيحان مع نقص تفسير سبب الاختلاف"},{"level":"2 درجتان","description":"حكم صحيح مع ذكر أنهما من الكربون فقط"},{"level":"1 درجة","description":"حكم صحيح بلا تبرير"},{"level":"صفر","description":"تأييد العبارة"}]'::jsonb, '["تأييد العبارة لاختلاف الخصائص الفيزيائية","تفسير الاختلاف باختلاف عدد البروتونات أو النيوترونات","إغفال ذكر سبب اختلاف الخصائص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.193Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2201, 0, 'وحدات بناء الصلب الجزيئي جزيئات متعادلة كهربائيًا، ولا توجد فيه أيونات أو إلكترونات حرة الحركة تنقل الشحنة، لذا فهو رديء التوصيل.', '["","هذا وصف الصلب الأيوني لا الجزيئي.","هذا وصف الصلب التساهمي الشبكي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.195Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2202, 1, 'الجزيئات في الصلب الجزيئي ترتبط بقوى بين جزيئية ضعيفة نسبيًا (قوى تشتت أو ثنائية القطب أو روابط هيدروجينية).', '["الروابط الأيونية تربط الأيونات في الصلب الأيوني.","","بحر الإلكترونات من خصائص الصلب الفلزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.195Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2203, 2, 'اليود I2 صلب جزيئي مكون من جزيئات متعادلة لا تحوي شحنات حرة الحركة، فهو رديء التوصيل.', '["الألومنيوم فلز ممتاز التوصيل لاحتوائه على إلكترونات حرة.","الجرافيت متآصل للكربون موصل للكهرباء، وليس صلبًا جزيئيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T11:15:02.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2204, 1, 'السكر مادة جزيئية تذوب في الماء جزيئات متعادلة دون أن تتأين، فلا تتوفر شحنات حرة في المحلول، فلا يوصل الكهرباء.', '["مفهوم خاطئ شائع: السكر لا يتفكك إلى أيونات عند ذوبانه.","","حركة الجزيئات المتعادلة لا تنقل شحنة كهربائية؛ التوصيل يحتاج جسيمات مشحونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2205, 1, 'المادة (أ) رديئة التوصيل في الحالتين الصلبة والمنصهرة، ودرجة انصهارها منخفضة، وهذا يدل على صلب جزيئي ليس فيه أيونات ولا إلكترونات حرة.', '["المادة (ب) لا توصل وهي صلبة لكنها توصل منصهرة، وهذا سلوك المادة الأيونية.","","المادة (ج) توصل وهي صلبة ومنصهرة، وهذا سلوك الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T11:15:02.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2206, 0, 'التوصيل الكهربائي يتطلب وجود جسيمات مشحونة (أيونات أو إلكترونات) قادرة على الحركة، وهذا ما ينقص المواد الصلبة الجزيئية.', '["","تقارب الجزيئات المتعادلة لا يوفر شحنات متحركة.","قوة الروابط التساهمية لا تعني وجود شحنات حرة؛ الألماس مثلًا رديء التوصيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T11:15:02.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2207, 2, 'كل من CO2 الصلب والجليد صلب جزيئي، وحداته جزيئات متعادلة تربطها قوى بين جزيئية، ولا تحوي شحنات حرة الحركة.', '["CO2 وH2O مركبان جزيئيان لا يتكونان من أيونات.","كلاهما صلب جزيئي لا شبكي، ودرجة انصهارهما منخفضة نسبيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2208, null, null, null, 'لأن وحدات بناء الصلب الجزيئي جزيئات متعادلة كهربائيًا تربطها قوى بين جزيئية ضعيفة، ولا تحتوي على أيونات أو إلكترونات حرة الحركة يمكنها نقل الشحنة الكهربائية أو نقل الطاقة الحرارية بسرعة خلال المادة.', '["جسيماتها جزيئات متعادلة","قوى بين جزيئية ضعيفة","لا توجد أيونات أو إلكترونات حرة الحركة","لا ناقل للشحنة أو للطاقة الحرارية"]'::jsonb, '[]'::jsonb, '[{"element":"الجسيمات جزيئات متعادلة","marks":1},{"element":"غياب الأيونات والإلكترونات الحرة","marks":1},{"element":"الربط بعدم نقل الشحنة والحرارة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل يربط طبيعة الجسيمات بغياب الشحنات الحرة وعدم التوصيل"},{"level":"2 درجتان","description":"ذكر غياب الشحنات الحرة دون ذكر طبيعة الجسيمات"},{"level":"1 درجة","description":"ذكر أنها جزيئات فقط"},{"level":"صفر","description":"تعليل خاطئ"}]'::jsonb, '["تعليل عدم التوصيل بقوة الروابط بين الجزيئات","القول إن الجزيئات مشحونة لكنها ثابتة","الخلط مع الصلب الأيوني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T11:15:02.198Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2209, null, null, null, 'الصلب الجزيئي: جسيماته جزيئات متعادلة، لا يحتوي شحنات حرة الحركة، رديء التوصيل للكهرباء والحرارة، مثل السكر C12H22O11 أو الجليد. الصلب الفلزي: جسيماته أيونات فلزية موجبة محاطة ببحر من الإلكترونات الحرة، يحتوي إلكترونات حرة الحركة، ممتاز التوصيل للكهرباء والحرارة، مثل النحاس Cu.', '["الجسيمات: جزيئات ↔ أيونات موجبة وإلكترونات حرة","الشحنات الحرة: غائبة ↔ موجودة (إلكترونات)","التوصيل: رديء ↔ ممتاز","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الجسيمات","marks":1},{"element":"الشحنات الحرة","marks":1},{"element":"التوصيل","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة مع مثالين"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا مقارنة صحيحة"}]'::jsonb, '["القول إن الأيونات الموجبة في الفلز هي التي تنقل التيار","عدّ السكر موصلًا عند إذابته","إغفال المثالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T11:15:02.199Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2210, null, null, null, 'الخطوات: 1) نختبر كل عينة وهي صلبة بوضع القطبين عليها: لا يضيء المصباح مع أي منها (لا الجزيئي ولا الأيوني يوصل وهو صلب). 2) نذيب كمية من كل عينة في ماء مقطر في كؤوس منفصلة، ونختبر توصيل كل محلول، مع اختبار الماء المقطر وحده للمقارنة. النتائج: محلول السكر لا يضيء المصباح لأن السكر مادة جزيئية تذوب جزيئات متعادلة لا تتأين؛ محلول NaCl يضيء المصباح لأن أيوناته تتحرر وتتحرك في الماء. التفسير: إذا أضاء المصباح مع محلول المادة المجهولة فهي أيونية، وإن لم يضئ فهي جزيئية (بشرط ذوبانها في الماء).', '["اختبار المواد في الحالة الصلبة وتوقع عدم التوصيل","إذابة العينات في ماء مقطر واختبار المحاليل","استخدام الماء المقطر وحده والسكر وNaCl للمقارنة","النتيجة المتوقعة لكل محلول","تفسير بوجود أو غياب أيونات حرة الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات تجربة صحيحة","marks":2},{"element":"ضبط المقارنة (ماء مقطر، عينات معروفة)","marks":1},{"element":"النتائج المتوقعة","marks":1},{"element":"التفسير والاستنتاج","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصميم كامل مع مقارنة، ونتائج متوقعة صحيحة، وتفسير بالشحنات الحرة"},{"level":"4–5 درجات","description":"تصميم صحيح مع نقص في الضبط أو التفسير"},{"level":"2–3 درجات","description":"فكرة الإذابة واختبار التوصيل دون تفسير كاف"},{"level":"1 درجة","description":"ذكر اختبار التوصيل للمواد الصلبة فقط"},{"level":"صفر","description":"تصميم غير صالح"}]'::jsonb, '["الاعتماد على اختبار الحالة الصلبة وحده، مع أن الجزيئي والأيوني كليهما لا يوصل وهو صلب","استخدام ماء الصنبور بدل الماء المقطر","توقع توصيل محلول السكر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-11T11:15:02.199Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2211, 0, 'يتكون الصلب الفلزي من أيونات موجبة محاطة ببحر من إلكترونات التكافؤ الحرة الحركة، وهذه الإلكترونات تتحرك عند تطبيق فرق جهد فتنقل التيار.', '["","الجزيئات المتعادلة لا تنقل الشحنة، وهي من خصائص الصلب الجزيئي.","الفلز لا يحتوي أيونات سالبة، والجسيمات الثابتة لا تنقل التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:02.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2212, 2, 'نموذج بحر الإلكترونات: أيونات فلزية موجبة مرتبة بانتظام تحيط بها إلكترونات تكافؤ غير متمركزة حرة الحركة.', '["هذا وصف الصلب الأيوني مثل NaCl.","هذا وصف الصلب الجزيئي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2213, 1, 'الإلكترونات الحرة غير المتمركزة هي التي تتحرك خلال الفلز عند تطبيق فرق جهد، بينما تبقى الأيونات الموجبة في مواقعها في الشبكة.', '["مفهوم خاطئ شائع: الأيونات الموجبة تبقى في مواقعها في الشبكة ولا تنقل التيار.","","الذرات المتعادلة لا تحمل شحنة، والفلز يوصف بأيونات موجبة وإلكترونات حرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T11:15:02.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2214, 0, 'تكتسب الإلكترونات الحرة في الفلز طاقة حركية عند التسخين، وتنقل هذه الطاقة بسرعة إلى بقية أجزاء الفلز، لذا يسخن طرف الملعقة الآخر سريعًا.', '["","الملعقة لا تنصهر، والحرارة تنتقل دون انتقال مادة الفلز.","الخشب لا يحتوي إلكترونات حرة، ولهذا فهو رديء التوصيل للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T11:15:02.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2215, 1, 'الحديد صلب فلزي يحتوي إلكترونات حرة الحركة تنقل الشحنة، بينما اليود صلب جزيئي مكون من جزيئات I2 متعادلة لا تحوي شحنات حرة.', '["الحديد لا يتكون من جزيئات أصلًا، بل أيونات موجبة وإلكترونات حرة.","","الكتلة المولية لا تحدد قدرة المادة على التوصيل الكهربائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T11:15:02.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2216, 0, 'في NaCl الصلب الأيونات مقيدة في مواقعها ولا توجد إلكترونات حرة، أما في الصوديوم الفلزي فإلكترونات التكافؤ غير متمركزة حرة الحركة فتنقل التيار.', '["","NaCl الصلب لا يحتوي إلكترونات حرة إطلاقًا، لا عددًا أقل منها.","الفلز لا يحتوي أيونات سالبة؛ الناقل فيه هو الإلكترونات الحرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T11:15:02.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2217, 2, 'الإلكترونات الحرة في الفلز تنقل الشحنة الكهربائية (أسلاك الكهرباء) وتنقل الطاقة الحرارية بسرعة (قيعان الأواني).', '["الصلابة ودرجة الانصهار لا تفسران التوصيل؛ الألماس صلب جدًا لكنه رديء التوصيل.","الفلزات لا تتكون من جزيئات، والجزيئات المتعادلة لا تنقل الشحنة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T11:15:02.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2218, null, null, null, 'لأن الصلب الفلزي يتكون من أيونات فلزية موجبة محاطة ببحر من إلكترونات التكافؤ الحرة الحركة (غير المتمركزة). فعند تطبيق فرق جهد تتحرك هذه الإلكترونات خلال الفلز فتنقل الكهرباء، وعند تسخين جزء منه تنقل الإلكترونات الحرة الطاقة الحرارية بسرعة إلى بقية الأجزاء.', '["أيونات موجبة في بحر من الإلكترونات الحرة","حركة الإلكترونات عند فرق الجهد تنقل الكهرباء","الإلكترونات الحرة تنقل الطاقة الحرارية بسرعة"]'::jsonb, '[]'::jsonb, '[{"element":"نموذج بحر الإلكترونات","marks":1},{"element":"تفسير التوصيل الكهربائي","marks":1},{"element":"تفسير التوصيل الحراري","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل للتوصيلين بالإلكترونات الحرة"},{"level":"2 درجتان","description":"تعليل أحد التوصيلين مع ذكر الإلكترونات الحرة"},{"level":"1 درجة","description":"ذكر الإلكترونات الحرة دون ربط بالتوصيل"},{"level":"صفر","description":"تعليل خاطئ"}]'::jsonb, '["نسبة التوصيل إلى حركة الأيونات الموجبة","إغفال تفسير التوصيل الحراري","وصف الفلز بأنه يتكون من جزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T11:15:02.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
